// ギリシャ編 23話版の会話の場面(story/gr23_extract.py でアニメの台本から機械で抜き出したもの。ここは直接直さない)
//  正本: マイドライブ/テリオンアニメ/台本_ギリシャ編_23話版/第NN話.md。直す時は台本を直してから抜き出し直す。
const GR_EP={};
GR_SC.g01_01=[{w:null,t:"2100年の地球。"},{w:null,t:"西暦2100年。研究所で生まれた生き物「テリオン」は、世界じゅうの町で、人と暮らしている。"},{w:null,t:"大きな街のビルの壁に、テリオンどうしの勝負の配信。"},{w:null,t:"日本の地図。"},{w:null,t:"日本を、のぞいて。"}];
GR_SC.g01_02=[{w:null,t:"ギリシャ。オリーブの村、オリーヴァ。"},{w:null,t:"坂の上から、スーツケースを引いた男の子が下りてくる。"},{w:null,t:"オリーブの屋台のおばさんが、ヤマトに声をかける。"},{w:"x",n:"屋台のおばさん",t:"ぼうや、ひとりかい？　そんな大きな荷物引いて、どこから来たの。"},{w:"hero",t:"日本。じいちゃんと来たんだけど、空港でトイレ行ってるあいだに、いなくなった。"},{w:"x",n:"屋台のおばさん",t:"いなくなった？　置いていかれたのかい。"},{w:"hero",t:"「村で待ってろ」って、これだけ。ホテルの名前のとこで切れてんの。三時間前から、返事もこねーし。"},{w:"x",n:"屋台のおばさん",t:"あらまあ。ほら、オリーブお食べ。腹がへってると、よけい腹が立つからね。"},{w:null,t:"ヤマト、オリーブを一つつまむ。"},{w:"x",n:"屋台のおばさん",t:"あっ、また、あの泥棒！　こらー！　今日はいくつ持ってった！"},{w:"hero",f:"surprised",t:"なにあれ！？　しっぽ、燃えてんじゃん！"},{w:null,t:"坂の下で、急ブレーキの音。"},{w:null,t:"車から、二人組が降りてくる。"},{w:null,t:"市場の人たちが、さっと道をあける。"},{w:"x",n:"八百屋のおじさん",t:"ヴィクターだ……。"},{w:"x",n:"屋台のおばさん",t:"ぼうや、こっちにお下がり。あいつら、テリオンをさらっていく連中だよ。先週は、パン屋の猫の子が連れていかれた。"},{w:null,t:"マルコ、鳥の子の店番がいる屋台の前を通りかかる。"},{w:"marco",t:"これも、もらっとくっす。"},{w:"x",n:"八百屋のおじさん",t:"おい、それはうちの——！"},{w:"nina",t:"なんか言った？　おじさん。"},{w:null,t:"ニーナ、おじさんの屋台のトマトの山を、足でけとばす。"},{w:"nina",t:"あたしらの用は、あの狐。持ち主のいないテリオンは、拾った者のもの。ね、マルコ。"},{w:"marco",t:"そうっす。チップの入ってない子は、高く売れるっす。"},{w:null,t:"ニーナ、手首の画面を動かす。"},{w:"nina",t:"右！　右から回って！"},{w:"marco",t:"右って、どっちの右っすか！"},{w:"nina",t:"あんたの右！"},{w:null,t:"狐、マルコの頭を踏み台にして、まっすぐ坂の上へ。"},{w:null,t:"狐が、ヤマトの顔に正面からぶつかる。"},{w:null,t:"狐、ヤマトのおなかの上に着地する。"},{w:"hero",f:"hurt",t:"うわっ、熱っ……！"},{w:null,t:"狐、ヤマトの顔を踏んで、跳んでいく。"},{w:null,t:"ヤマト、起き上がる。"},{w:"hero",f:"smile",t:"すっげー！！　おばちゃん、荷物見てて！"},{w:"x",n:"屋台のおばさん",t:"ちょっと、ぼうや！　ヴィクターの前に出ちゃだめだって！"},{w:null,t:"ヤマト、服を散らかしたまま、走りだす。"},{w:null,t:"第1話　テリオン・ワールド"}];
GR_SC.g01_03=[{w:"marco",t:"ニーナさん、なんか、子どもがついてきてるっす。"},{w:"nina",t:"ほっときな。狐が先。"},{w:"hero",t:"おーい、待てよー！　ちょっとさわるだけだって！"},{w:"x",n:"子ども1",t:"あの子、ヴィクターより速いよ！"},{w:null,t:"ドローンが網を落とす。"},{w:"marco",t:"あー！　また網、燃やされたっす！　これで今週、五枚目っすよ！"},{w:"nina",t:"だから、上から落とせって言ってんでしょ！"},{w:null,t:"狐のしっぽが、今度はヤマトに向く。"},{w:"hero",f:"hurt",t:"あちっ！　……すげえ、今の見た！？　火、とばした！"},{w:"x",n:"子ども2",t:"前髪、焦げてるよ！"},{w:"hero",t:"いいって、そんなの！"},{w:null,t:"狐の口から、半分焦げたオリーブが一つ落ちる。"}];
GR_SC.g01_04=[{w:null,t:"村の上の、古い神殿のあと。"},{w:null,t:"坂のてっぺん。"},{w:null,t:"狐、その木の根もとに逃げこむ。"},{w:null,t:"根もとに入ったとたん、しっぽの火が、ぼっと一回りふくらむ。"},{w:null,t:"ヤマト、息を切らして追いつく。"},{w:null,t:"狐が、根もとから一歩だけ枯れ草の上へ出る。"},{w:null,t:"ヤマト、目をまるくして、それを見ている。"},{w:"hero",t:"おまえ、ここが好きなのか？　大丈夫、おれ、あいつらの仲間じゃないから。ほら、なんにもしないって。"},{w:null,t:"ヤマト、右手をのばす。"},{w:"hero",t:"よーし、いい子だ。そのまま、そのまま……。"},{w:"hero",f:"hurt",t:"いってえええ！！　なんでだよ！　今、いい感じだったじゃん！"},{w:null,t:"狐は木の上へ跳び上がって、知らん顔でオリーブの続きを食べる。"},{w:null,t:"ヤマト、右手を押さえて、顔をしかめる。"}];
GR_SC.g01_05=[{w:null,t:"石段の下から、ごろごろと音。"},{w:"elly",t:"あ、いたいた！　ねえ、これ、きみのでしょ？　オリーブのおばさんから預かってきたよ。"},{w:"hero",t:"あ……ありがと。わざわざ持ってきてくれたの？"},{w:"elly",t:"おばさんが「男の子が荷物置いて、狐を追っかけてった」って、大さわぎしてたんだもん。……って、ちょっと、その右手！　血、出てるじゃない！"},{w:"hero",t:"ああ、これ？　なでようとしたら、かまれた。"},{w:"elly",t:"かまれたって、なんでそんな、うれしそうなの！　ほら、すわって！"},{w:null,t:"ヤマト、木の根もとに座らされる。"},{w:"elly",t:"しみるよ。がまんしてね。"},{w:"hero",t:"いっ……！　しみる、しみる！"},{w:"elly",t:"あの子、フォルンっていうの。この丘に住んでる野良の狐の子。村の人はみんなそう呼んでる。だれにもさわらせないんだよ。"},{w:"elly",t:"わたしなんか、三年、毎日クッキー持ってきてるのに、一回もなでさせてもらったことないんだから。"},{w:null,t:"根もとの石のくぼみに、クッキーが一枚。"},{w:"hero",t:"フォルンか。かっこいい名前じゃん。"},{w:null,t:"木の上で、フォルンの耳が、ぴくっとこっちを向く。"},{w:"elly",t:"さっきの黒い車の二人、見た？　あれが、ヴィクター。持ち主のいないテリオンを、つかまえて売ってるの。フォルン、何回もねらわれてるんだよ。"},{w:"hero",t:"警察とか、なにもしねーの？"},{w:"elly",t:"村の駐在さん、ひとりしかいないもん。それも、おじいちゃん。"},{w:"elly",t:"で、きみは？　観光？"},{w:"hero",t:"日本から。けさ着いた。"},{w:null,t:"エリーの手が止まる。"},{w:"elly",t:"ちょっと待って。日本から来た、男の子。きみ、もしかして、ヤマト？"},{w:"hero",t:"え、なんでおれの名前知ってんの。"},{w:"elly",t:"わたし、エリー！　うち、ホテルやってるの！　きみのおじいちゃんから電話があって、空港まで迎えに行ったんだよ！　三時間待ったんだからね、三時間！"},{w:"hero",t:"じいちゃん、それ、おれにひと言も言ってない。"},{w:null,t:"ヤマト、手首の画面をつける。"},{w:"elly",t:"ホテル、うちだね。"},{w:"hero",t:"なんで、そこで切れるんだよ……。"},{w:"elly",t:"で、おじいちゃんは？"},{w:"hero",t:"知らない。空港でトイレ行って、もどったら、いなかった。"},{w:"elly",f:"surprised",t:"ええっ！？　それ、すっごく大変なことじゃない！"},{w:"hero",t:"いつものことだよ。じいちゃん、急に消えるの、得意だから。"},{w:null,t:"ヤマトは、話しながらも、木の上のフォルンばかり見ている。"},{w:"elly",t:"もう。心配してるの、わたしだけみたいじゃない。"}];
GR_SC.g01_06=[{w:null,t:"ヤマト、ポケットをさぐる。"},{w:"hero",t:"これ、さっきあいつが落としたやつ。"},{w:"elly",t:"それで、どうするの？"},{w:"hero",t:"今度は、手をのばさない。こっちから行くから、かまれたんだと思う。"},{w:null,t:"ヤマト、オリーブを手のひらに乗せて、ひざの上に置く。"},{w:null,t:"フォルン、木から下りてくる。"},{w:"elly",t:"（小声で）ほら、やっぱり食べない。"},{w:"hero",t:"（小声で）しっ。"},{w:null,t:"フォルン、オリーブをくわえて、自分のしっぽの火の上に落とす。"},{w:null,t:"くわえ直して、ヤマトの手のひらの上で、かりっと食べる。"},{w:"hero",t:"食った。おれの手の上で、食った！"},{w:"elly",f:"surprised",t:"うそでしょ……。焦がしたのが好きだったの？　わたし、三年間、クッキーだったんだけど！"},{w:"hero",t:"クッキーは焦がせねーもんな。"},{w:"elly",t:"焦がせるよ！　オーブンで！"},{w:null,t:"エリー、カバンの中のクッキーの箱を見る。"}];
GR_SC.g01_07=[{w:null,t:"ブーンと、羽の音。"},{w:"marco",t:"はあ、はあ……坂、長すぎっす……。"},{w:"nina",t:"いた。……なんで子どもが、狐にエサやってんのよ。"},{w:null,t:"フォルン、身がまえる。"},{w:"nina",t:"おい、おチビちゃん。その狐、よこしな！"},{w:"hero",t:"嫌だ！　おまえら、誰だ？"},{w:"nina",t:"あたしらは、泣く子も黙るマフィア・ヴィクターよ。痛い目見る前に、さっさとよこしな。"},{w:"hero",t:"マフィン？　なんだそれ！"},{w:"elly",t:"マフィアよ！　こいつら、テリオンをさらっていってる悪いやつらなの！　村の子も、何びきも連れていかれたんだから！"},{w:"marco",t:"人聞き悪いっすね。持ち主のいない子を、拾ってるだけっすよ。"},{w:"nina",t:"マルコ、しゃべってないで、囲みな！"},{w:null,t:"三機のドローンが、フォルンを三方から囲む。"},{w:"elly",t:"ヤマト！"},{w:null,t:"ヤマトの肩ごしに、フォルンの目が、網と二人組を見る。"},{w:"marco",t:"あー！　六枚目っす！"},{w:null,t:"ヤマト、立ち上がる。"},{w:"hero",t:"マフィンかマフィアか知らねーけど、フォルンは、さっきおれが出会った友達だ！　ぜってー渡さねー！　おまえらこそ、あっち行け！"},{w:"nina",t:"友達ねえ。かまれたくせに。"},{w:"nina",t:"しょうがない。口で言っても分からないようだから、力ずくで頂くことにするか。"},{w:null,t:"オリーブの林の中から、がさがさと音。"},{w:"nina",t:"林に先回りさせといて正解だったね。やれ、クマッパ！"},{w:null,t:"フォルン、ヤマトの足もとから、すっと前に出る。"},{w:"elly",t:"フォルンが、ヤマトの前に出た……。"},{w:"hero",f:"smile",t:"いっしょにやってくれんのか？　よし、望むところだ！　いっけー、フォルン！"},{w:null,t:"神殿の柱のかげに、市場の子どもたちが三人、しゃがんで並ぶ。"}];
GR_SC.g01_09=[{w:null,t:"柱のかげから、市場の子どもたちが走ってくる。"},{w:"x",n:"子ども1",t:"ヴィクターに、勝っちゃった！"},{w:"x",n:"子ども3",t:"泥棒狐、すげー！"},{w:"x",n:"子ども2",t:"泥棒じゃないよ、もう。ヒーローだよ。"},{w:null,t:"ニーナ、ひっくり返ったクマッパを抱き上げる。"},{w:"nina",t:"よくやったよ。休みな。"},{w:null,t:"ニーナ、目を回したクマッパを、両腕でかかえ直す。"},{w:"nina",t:"覚えときな、おチビちゃん。ヴィクターに逆らって、ただで済んだやつはいないんだから。"},{w:"hero",t:"何回来たって、同じだ！　なあ、フォルン！"},{w:null,t:"フォルン、ヤマトの前を素通りして、マルコの前へ。"},{w:"marco",t:"あ。"},{w:"marco",t:"あちちちちっ！　ニーナさーん！"},{w:"nina",t:"バカ、走るな！　置いてくよ！"},{w:null,t:"二人組、石段を転げるように逃げていく。"},{w:null,t:"ヤマト、にやにやしながら、フォルンに手をのばす。"},{w:"hero",f:"smile",t:"やったな、フォルン！　ほら、ちょっとだけ——"},{w:null,t:"フォルン、喉の奥で、ぐるる。"},{w:"elly",t:"まだ、なでさせてはくれないみたいね。"},{w:"hero",t:"ちぇっ。いいよ、そのうちな。"},{w:null,t:"エリー、スーツケースを持ち上げる。"},{w:"elly",t:"さ、ホテル行こ。お姉ちゃん、ずっと待ってるから。"},{w:null,t:"二人、坂を下りはじめる。"}];
GR_SC.g01_10=[{w:null,t:"坂の下に止めた黒いワゴン車。"},{w:"marco",t:"上に、なんて言います？　狐、とれませんでしたって？"},{w:null,t:"ニーナ、手首の画面に、ドローンが撮った写真を出す。"},{w:"nina",t:"だれにもなつかない野良が、会ったばっかりの子どもをかばって、自分から前に出た。そんな話、聞いたことない。"},{w:"marco",t:"それ、まずいやつっすか。"},{w:"nina",t:"上が、ほしがるやつ。"},{w:null,t:"ニーナ、送り先を選ぶ。"}];
GR_SC.g01_11=[{w:null,t:"その夜。坂の上の、小さなホテル。"},{w:null,t:"ホテルの一階のはしの、小さな部屋。"},{w:null,t:"ヤマト、戸を開ける。"},{w:"elly",t:"その図鑑、お姉ちゃんが置いといてくれたの。「日本の子なら、きっと読むから」って。"},{w:"hero",t:"お姉ちゃんって、さっき受付にいた人？"},{w:"elly",t:"そう、アナ。このホテル、お姉ちゃんが一人でやってるの。きみの焦げた前髪見て、笑いこらえてたでしょ。"},{w:null,t:"ヤマト、図鑑をひらく。"},{w:"hero",t:"日本だけ、白いんだな。"},{w:"elly",t:"日本って、テリオン、いないんでしょ？"},{w:"hero",t:"いない。画面でしか見たことなかった。さわったのも、かまれたのも、今日が初めて。"},{w:"elly",t:"見て。あの子、ここまでついてきてる。"},{w:"hero",t:"友達だからな。"},{w:"elly",t:"なでさせてもらえないのに？"},{w:"hero",f:"angry",t:"うっせ。"},{w:null,t:"エリー、笑って戸を閉める。"},{w:null,t:"スーツケースの中身を、ベッドにあける。"},{w:null,t:"ヤマト、戸を開けて、ろうかのエリーを呼びとめる。"},{w:"hero",t:"エリー。これ、おれのじゃない。スーツケースに入ってた。"},{w:"elly",t:"入れた覚え、ないの？"},{w:"hero",t:"ない。見たこともない。じいちゃんかな。"},{w:null,t:"時計のガラスの奥で、小さな歯車が、かちり、と鳴る。"},{w:null,t:"柵の上のフォルンの耳が、ヤマトではなく、時計の方へ、ぴんと向く。"}];
GR_EP[1]={"t": "テリオン・ワールド", "sc": [["g01_01", "語り", 0], ["g01_02", "オリーヴァ村・市場の坂（昼）", 0], ["g01_03", "坂道の追いかけっこ", 0], ["g01_04", "神殿のあとの丘", 0], ["g01_05", "同じ場所・女の子", 0], ["g01_06", "同じ場所・手のひらのオリーブ", 0], ["g01_07", "丘・ヴィクター", 0], ["g01_08", "勝負", 1], ["g01_09", "勝負のあと", 0], ["g01_10", "黒いワゴン車の中（夕方）", 0], ["g01_11", "坂の上のホテル・一階のはしの部屋（夜）", 0]]};
GR_SC.g02_01=[{w:null,t:"オリーヴァ村。坂の上のホテルの朝。"},{w:null,t:"裏のぶどう畑。"},{w:null,t:"畑のはしのベンチに、毛布にくるまったヤマト。"},{w:null,t:"ベンチの前の柵の上で、フォルンが丸くなっている。"},{w:null,t:"エリーが、パンとオリーブの皿を持ってのぞきこむ。"},{w:"elly",t:"ヤマト？　まさか、ひと晩じゅうここにいたの？"},{w:"hero",t:"寝てない！　見張ってたんだよ。ヴィクター、また来るかもしれないだろ。"},{w:"elly",t:"よだれ、ついてるけど。"},{w:"hero",f:"serious",t:"……これは、夜つゆ。"},{w:null,t:"フォルン、あくびをして起き上がる。"},{w:"hero",t:"なあ、今の見た？　投げて、しっぽで焼いて、食う。かっけえ……。"},{w:"elly",t:"毎朝やってるよ、あれ。"},{w:null,t:"ヤマト、エリーの皿からオリーブを一つつまむ。"},{w:"hero",t:"おれもできる。見てて。"},{w:"elly",t:"しっぽ、ないでしょ。"},{w:"hero",t:"口でキャッチするんだよ。"},{w:null,t:"ヤマト、オリーブを高く投げる。"},{w:null,t:"オリーブ、ヤマトのおでこに当たって、ぽんとはねる。"},{w:"elly",t:"……おいしそうに食べてるね、きみのオリーブ。"},{w:"hero",f:"serious",t:"……今のは、フォルンにあげたの。"},{w:null,t:"エリー、皿で口をかくして、肩をふるわせている。"},{w:null,t:"二階の窓が、ばんと開く。"},{w:"ana",t:"エリー！　お客さんの朝ごはん！　日本の子の分も！　早く！"},{w:"elly",t:"はーい、お姉ちゃん！"},{w:null,t:"第2話　オリーブの丘"}];
GR_SC.g02_02=[{w:null,t:"白い壁の小さな食堂。"},{w:null,t:"台所でフライパンをふるのも、運ぶのも、つぐのも、アナ一人。"},{w:"hero",t:"（パンをほおばりながら）なあ、このホテル、ロボットいないの？　日本のホテル、みんなロボットだったけど。"},{w:"elly",t:"うちは、いない。お姉ちゃんが、ぜんぶやるの。"},{w:"ana",t:"（台所から）ロボット入れたら、借りたお金、返せなくなるの！　聞こえてるからね！"},{w:null,t:"アナ、皿を三枚いっぺんに持って出てくる。"},{w:"ana",t:"ゆうべの前髪の子ね。明るいとこで見ると、もっとひどいわ。"},{w:"hero",t:"狐に焦がされた。"},{w:"ana",t:"知ってる。村じゅうの話よ。ヴィクターとやり合って、勝ったんだって？"},{w:"hero",f:"smile",t:"勝ったよ！　フォルンがさ、根もとでぶわーって火を——"},{w:"ana",t:"はいはい、あとで聞く。冷めないうちに食べな。"},{w:null,t:"アナ、もう次の客の方へ行っている。"},{w:"hero",f:"serious",t:"……聞く気ねーじゃん。"},{w:"elly",t:"お姉ちゃん、朝はいつもああなの。"},{w:null,t:"エリーの長い髪のかげから、うす茶色の、まんまるの毛玉が、そっと顔を出す。"},{w:"hero",f:"surprised",t:"うわっ！　なにそれ、いつからいたの！？"},{w:"elly",t:"ずっといたよ。ピリポン。うちの子。きのうは、お姉ちゃんと留守番してたの。"},{w:null,t:"エリー、パンを小さくちぎって、肩のピリポンにわたす。"},{w:"hero",f:"surprised",t:"ちっちぇえ！　よろしくな、ピリ——"},{w:null,t:"ヤマトが顔を近づける。"},{w:"elly",t:"こわがりなの。知らない人の前だと、すぐかくれちゃう。"},{w:"hero",t:"なあ、さわってもいい？　ふわふわか確かめたい。"},{w:"elly",t:"だめ。とくに寝てる時は、ぜったいだめ。びりってするから。"},{w:"hero",t:"さわらねーよ。"}];
GR_SC.g02_03=[{w:null,t:"古いソファと、壁の大きな画面。"},{w:null,t:"ソファで、客のおじいさんが新聞を読んでいる。"},{w:null,t:"エリーはカウンターでアナに何か頼まれている。"},{w:null,t:"ヤマト、カウンターのエリーを見る。"},{w:null,t:"新聞の鳥の子が、めくるのを止めて、ヤマトを見る。"},{w:"hero",t:"（小声で）ちょっとだけ。ふわふわか、確かめるだけだから。"},{w:null,t:"指先が、毛にふれる。"},{w:null,t:"ピリポンの毛が、ぜんぶ逆立つ。"},{w:null,t:"ヤマトの前髪が、まっすぐ上に立つ。"},{w:null,t:"ピリポン、ソファの背もたれのうしろにかくれる。"},{w:null,t:"エリーがもどってくる。"},{w:"elly",f:"serious",t:"……さわった？"},{w:"hero",t:"さわってない。"},{w:null,t:"ヤマトの前髪から、まだ、ぱちっと小さな火花。"},{w:"elly",t:"さわったでしょ。両方焦げてるもん。"},{w:"hero",f:"serious",t:"……ちょっとだけ。"},{w:"elly",t:"さっき「さわらねーよ」って言ったの、だれ？"},{w:null,t:"エリー、手をのばす。"},{w:"elly",f:"sad",t:"（ピリポンに）ごめんね。この人、勝手にさわるの。"},{w:null,t:"画面のお知らせが切りかわる。"},{w:"hero",t:"あ、あの車！　きのうのやつだ。"},{w:null,t:"アナが、カウンターから出てくる。"},{w:"ana",t:"ヴィクターよ。パン屋の猫の子も、八百屋さんの鳥の子も、あいつら。"},{w:"hero",t:"警察は？　なんで捕まえねーの？"},{w:"ana",t:"持ち主のいる子なら、警察も探してくれる。でも、持ち主のいない子は「いなくなっただけ」で終わり。八百屋さんの鳥の子だって、登録してなかったから。"},{w:"hero",t:"じゃあ、フォルンは……。"},{w:"ana",t:"野良でしょ、あの狐。さらわれても、だれも探してくれないわね。"},{w:"hero",t:"だったら、おれが持ち主になる！　登録って、どこでやんの？"},{w:"ana",t:"持ち主の登録は、十五から。あんた、いくつ。"},{w:"hero",f:"serious",t:"……十一。"},{w:"ana",t:"残念でした。"},{w:null,t:"アナ、ヤマトの肩をぽんとたたいて、台所へもどる。"},{w:null,t:"画面が、また切りかわる。"},{w:null,t:"画面「白い都テリオン大会　参加者募集　年れい不問」。"},{w:null,t:"ヤマト、ソファから、がばっと立ち上がる。"},{w:"hero",t:"エリー、これ！　年れいにかかわらずって書いてある！"},{w:"elly",f:"serious",t:"……ほんとだ。"},{w:"hero",f:"surprised",t:"優勝したら、十一でも登録できるってことだろ！？　白い都って、どこ？"},{w:"elly",t:"アテネのこと。ここから、ずっと東だよ。車で行っても、一日じゃ着かないくらい。"},{w:"hero",t:"遠っ……。"},{w:null,t:"ヤマト、画面の「年れいにかかわらず」の字から、目をはなさない。"},{w:"elly",t:"とにかく、先におばあちゃんち、行かなきゃ。きのうから、あんたを連れてこいって言われてるの。"},{w:"hero",t:"なんで、おれ？"},{w:"elly",t:"知らない。行けば分かるよ。"},{w:null,t:"エリー、ヤマトの腕を引く。"},{w:null,t:"アナが、画面の横の紙のちらしを一枚ぬいて、ヤマトの手にねじこむ。"},{w:"ana",t:"持ってきな。お客さんの分、いっぱいあるから。……本気にするんじゃないよ。"},{w:"hero",t:"する！"},{w:"ana",t:"……でしょうね。"}];
GR_SC.g02_04=[{w:null,t:"昼。村の畑は、今も人の手で実をとる。"},{w:null,t:"白い家のあいだを、オリーブの林が段々にのぼっていく。"},{w:null,t:"ヤマト、ちらしをにぎったまま歩いている。"},{w:"hero",t:"なあ、あれ、全部、手でとってんの？　2100年だぜ？"},{w:"elly",t:"うん。機械でとると、実に傷がつくんだって。手でとったオリーブは、すっごく高く売れるの。遠くのお金持ちの国の人しか買えないくらい。"},{w:"hero",t:"へえ……。じゃあ、フォルンが盗んでたの、高いやつじゃん。"},{w:"elly",t:"そう。だから村の人、みんな怒ってたの。"},{w:null,t:"畑の上の道を、白い車が音もなく走っていく。"},{w:"hero",t:"あ、ロボタクシー！　あれ乗ってけば、白い都まですぐじゃん！"},{w:"elly",t:"乗らないよ。あれ、乗った人がいつどこに行ったか、ぜんぶ記録されるの。"},{w:"hero",t:"それが、なに？"},{w:"elly",t:"その記録、お金で買ってる人たちがいるんだって。お姉ちゃんが言ってた。"},{w:"hero",f:"serious",t:"……ヴィクター？"},{w:null,t:"エリー、うなずく。"},{w:null,t:"二人のうしろを、フォルンが段々の石垣の上を伝ってついてくる。"},{w:null,t:"畑のおばさんが、フォルンに気づいて手を止める。"},{w:"x",n:"畑のおばさん",t:"あっ、泥棒狐——"},{w:null,t:"おばさん、言いかけて、エリーの方を見る。"},{w:"elly",t:"おばさん、この子、きのうヴィクターを追っぱらったんだよ。"},{w:"x",n:"畑のおばさん",t:"聞いたよ。……しょうがないね。一個だけだよ。"},{w:null,t:"おばさん、エプロンのポケットからオリーブを一つ出して、石垣の上に置く。"},{w:"x",n:"畑のおばさん",t:"焼いて食べるのかい。ぜいたくな泥棒だこと。"},{w:null,t:"おばさん、口のはしを上げて、また実をしごきはじめる。"}];
GR_SC.g02_05=[{w:null,t:"村のいちばん上の丘。"},{w:null,t:"オリーブ畑のまん中に、石でかこんだ小さなため池。"},{w:null,t:"フォルン、池のふちへ。"},{w:"hero",t:"はは、びびってやんの。……あれ？"},{w:null,t:"ヤマト、池と、フォルンのしっぽを見くらべる。"},{w:"hero",t:"今、水のそばで、火がちっちゃくなったよな。"},{w:"elly",t:"炎の子は、水がきらいなんだよ。図鑑にのってなかった？"},{w:"hero",t:"まだ半分しか読んでねーもん。"},{w:"elly",t:"この池の水で、丘の畑、ぜんぶやってるの。雨、ちょっとしかふらないから。"},{w:null,t:"池の向こう、丘の頂上に、白い大きな建物のあと。"},{w:"hero",t:"あれ、なに？　でっけー。"},{w:"elly",t:"昔の研究所。おばあちゃん、若いころ、あそこで働いてたんだって。"},{w:"hero",t:"なんの研究？"},{w:"elly",t:"聞いても、「むかしむかしの話」しか言わないの。入っちゃだめって、それだけ。"},{w:null,t:"くずれた丸屋根のすきまから、空が見える。"},{w:null,t:"フォルンの耳が、建物の方へ、ぴくっと動く。"}];
GR_SC.g02_06=[{w:null,t:"丘の向こうの、石の家。"},{w:null,t:"小さな石の家。"},{w:"elly",t:"おばあちゃーん！　つれてきたよ！"},{w:"oba",t:"はいはい。……あんたが、ヤマトだね。"},{w:"hero",t:"こんにちは！　ヤマトです！"},{w:null,t:"おばあさん、ヤマトの顔をじっと見る。"},{w:"oba",t:"……両方、焦げてるね。"},{w:"hero",t:"こっちは狐で、こっちはピリポン。"},{w:"oba",t:"あら。あの子、寝てる時にさわると、怒るんだよ。"},{w:"elly",t:"ほらね！"},{w:"hero",f:"serious",t:"……先に言ってくれよ。"},{w:null,t:"おばあさん、くっくっと笑って、家の中へ入っていく。"},{w:null,t:"棚のすみに、色あせた絵本。"},{w:null,t:"ヤマトの目は、すぐ、となりの写真立てに行く。"},{w:"hero",t:"これ、さっきの研究所？　この女の人、おばあちゃん？"},{w:"oba",t:"さあ、どうだったかね。むかしむかしの話だよ。"},{w:null,t:"おばあさんが、お茶を三つ持ってくる。"},{w:"oba",t:"ゆうべ、アナから電話があったよ。ヴィクターを追い返したんだって？"},{w:"hero",t:"うん！　でも、ニーナってやつが「覚えときな」って。"},{w:"oba",t:"あの連中は、ねらった子はあきらめないよ。今度は、もっと大勢で来るね。"},{w:null,t:"ヤマト、くしゃくしゃのちらしをテーブルに置く。"},{w:"hero",t:"だから、これ。優勝したら、フォルンの持ち主になれる。持ち主になったら、さらわれても、みんな探してくれるんだろ。"},{w:null,t:"おばあさん、ちらしの「年れいにかかわらず」の字を見る。"},{w:"oba",t:"……エリー。一緒に行っておいで。"},{w:"elly",t:"うん。いいよ。"},{w:null,t:"エリー、クッキーをかじりながら返事をする。"},{w:"hero",f:"surprised",t:"え、いいの！？　白い都、遠いんだろ？"},{w:"elly",t:"遠いよ。でも、行ってみたかったんだ。わたし、村の外、ほとんど出たことないから。"},{w:"oba",t:"あしたの昼は、ホテルにいない方がいいね。"},{w:"elly",t:"お昼なら、ちょうど競技場の案内の仕事あるよ。"},{w:"oba",t:"じゃあ、それ。"},{w:"elly",t:"今夜、出る？"},{w:"oba",t:"（空を、あごでさす）ほら。ヴィクターのドローンだよ。ゆうべから、ずっと村の上を回ってる。今夜はだめ。……あしたの夜。森の道なら、上から見えない。"},{w:null,t:"おばあさん、棚の引き出しを開ける。"},{w:"oba",t:"これ、持っておいき。なくすんじゃないよ。"},{w:"elly",t:"なにこれ？　中身は？"},{w:"oba",t:"見ても、わかんないよ。古いもんだから。"},{w:null,t:"エリー、札を服の中にしまう。"},{w:"oba",t:"それとね、ついでに、あのヴィクターって連中、ちょっと、こらしめておいで。"},{w:"hero",f:"surprised",t:"ついで！？"},{w:"elly",t:"いいよー。"},{w:"hero",f:"surprised",t:"いいの！？　相手、マフィアだぞ！？"},{w:"elly",t:"だって、パン屋さんの猫の子、まだ帰ってきてないもん。"},{w:null,t:"ヤマト、身を乗り出す。"},{w:null,t:"おばあさんの手が、お茶のカップを持ったまま、止まる。"},{w:null,t:"古いガラス。"},{w:"hero",f:"sad",t:"あ、ごめんなさい。これ、なんか、スーツケースに入ってて。じいちゃんのかな。"},{w:null,t:"おばあさん、カップを置く。"},{w:"oba",t:"……古い時計だね。大事にしな。"},{w:null,t:"おばあさん、フォルンを見る。"}];
GR_SC.g02_07=[{w:null,t:"その夜。"},{w:null,t:"ヤマト、リュックにものをつめている。"},{w:null,t:"図鑑の終わりのページの、ギリシャの地図。"},{w:null,t:"戸口に、パジャマのエリー。"},{w:"elly",t:"その線、海の上、通ってるよ。"},{w:"hero",t:"泳ぐ。"},{w:"elly",t:"フォルン、水きらいなのに？"},{w:"hero",f:"serious",t:"……じゃあ、回る。"},{w:"elly",t:"出るのは、あしたの夜だからね。お姉ちゃんには、ないしょ。言ったら、ぜったい止めるから。"},{w:"hero",t:"分かった。"},{w:null,t:"エリー、自分の部屋へもどりかけて、止まる。"},{w:"elly",t:"それと、ヤマト。ピリポンに、もう勝手にさわらないでね。"},{w:"hero",t:"さわらねーよ。"},{w:null,t:"エリーの肩のピリポンが、ヤマトを見て、ぱちっ。"},{w:null,t:"ヤマト、ちりちりの前髪を手で押さえる。"}];
GR_SC.g02_08=[{w:null,t:"同じころ、遠くの丘。"},{w:null,t:"男の手首の画面が鳴る。"},{w:"x",n:"ヴィクターの男（画面）",t:"十二番。仕事だ。オリーヴァ村。狐を一匹。ニーナとマルコがしくじった。"},{w:null,t:"画面のすみに、少年の前に立って、しっぽを立てる狐の写真。"},{w:"x",n:"ヴィクターの男（画面）",t:"子どもがついている。じゃまなら、子どもごとでいい。"},{w:null,t:"男、望遠鏡から目を離さないまま、写真を開かずに、画面を指で消す。"},{w:null,t:"それから、ゆっくり望遠鏡を下ろす。"}];
GR_EP[2]={"t": "オリーブの丘", "sc": [["g02_01", "ホテルの裏・ぶどう畑のはし（朝）", 0], ["g02_02", "ホテルの食堂（朝）", 0], ["g02_03", "ロビー（朝）", 0], ["g02_04", "村の道（昼）", 0], ["g02_05", "丘の上・ため池と研究所あと（昼）", 0], ["g02_06", "おばあさんの家（昼）", 0], ["g02_07", "ホテルのヤマトの部屋（夜）", 0], ["g02_08", "どこかの丘（夜）", 0]]};
GR_SC.g03_01=[{w:null,t:"まっ暗な石の通路。"},{w:null,t:"つきあたりの壁のあたりから、大きな生き物の寝息のような、低い音。"},{w:null,t:"天井から、砂がひとすじ、寝息に合わせて、さらさらと落ちる。"},{w:null,t:"第3話　古代の競技場"}];
GR_SC.g03_02=[{w:null,t:"回収の日の朝。"},{w:null,t:"リュックを背負ったヤマト。"},{w:null,t:"玄関から、ドイツ人の夫婦が出てくる。"},{w:"elly",t:"（夫婦に、ドイツ語で何か言う。夫婦が笑う）"},{w:"hero",f:"serious",t:"……今の、何語？"},{w:"elly",t:"ドイツ語。"},{w:"hero",t:"何語しゃべれんの？"},{w:"elly",f:"surprised",t:"えっとね……いっぱい。"},{w:null,t:"柵の上で、フォルンがあくびをする。"},{w:null,t:"坂の下の広場の時計が、九時を打つ。"}];
GR_SC.g03_03=[{w:null,t:"村の外れ。三千年前の競技場。"},{w:null,t:"オリーブの林を抜けると、石を積んだ古い入口のアーチ。"},{w:null,t:"観光客がたくさん。"},{w:"hero",f:"serious",t:"……え、ここ？　ただの広場じゃん。"},{w:"x",n:"案内のロボット",t:"（場内の放送で）ここは、世界で最初のオリンピックが開かれた場所です。"},{w:"hero",f:"serious",t:"……マジか。"},{w:null,t:"アーチの下は、すりへった石だたみ。"},{w:null,t:"エリー、夫婦の前に立つ。"},{w:"elly",t:"（夫婦に）この走る所の長さはね、昔の、すっごい力持ちの人の、足の大きさ六百こ分なんだって。"},{w:null,t:"夫婦、うなずいて、向こうのはしまでを見わたす。"},{w:null,t:"ヤマト、スタートの線につま先を合わせる。"},{w:"hero",t:"いち。に。さん……。"},{w:null,t:"……足が、だんだん速くなる。"},{w:"hero",f:"serious",t:"……ひゃくはち。ひゃくきゅう……。"},{w:"hero",f:"serious",t:"……そいつ、足、何センチあんの？"},{w:"elly",t:"さあ。"},{w:null,t:"ドイツ人の夫婦が、くすくす笑う。"}];
GR_SC.g03_04=[{w:null,t:"ヤマト、走ってもどってくる。"},{w:"hero",t:"エリー、勝負しよ。向こうの端まで。"},{w:"elly",t:"えー。"},{w:null,t:"エリー、笑いながら、カバンを、左のすみの角の石の上に下ろして並ぶ。"},{w:null,t:"エリー、片手を上げる。"},{w:"elly",t:"よーい……。"},{w:null,t:"ヤマト、前のめりになる。"},{w:null,t:"ヤマト、とび出す。"},{w:null,t:"エリーは、手を上げたまま、目をぱちぱちさせる。"},{w:null,t:"ヤマト、半分まで来て、ふり返る。"},{w:"hero",t:"え、まだ——"},{w:null,t:"ふり返ったまま足がもつれて、顔から土につっこむ。"},{w:null,t:"エリーが、のんびり走ってきて、その横を走りぬける。"},{w:null,t:"その少し前を、フォルンが、だれよりも速く走りぬけていく。"},{w:null,t:"観光客から、ぱらぱらと拍手。"},{w:null,t:"ヤマト、顔を上げる。"}];
GR_SC.g03_05=[{w:null,t:"林の方から、ぴいっと高い声。"},{w:null,t:"オレンジ色の、ふかふかの羽のタカの子。"},{w:null,t:"タカの子、スタートの線の、左のすみの角の石に、すっと下りる。"},{w:null,t:"ピリポン、かじりかけのクッキーを持ったまま、箱の外へ、ころんと転がり出る。"},{w:null,t:"タカの子、空の箱を両足でつかむ。"},{w:"elly",t:"あっ！"},{w:null,t:"箱のふたがぱかぱか開いて、クッキーがこぼれる。"},{w:null,t:"石の上に、ピリポンがひとり。"},{w:"elly",t:"返して！　それ、その子のおうち！"},{w:"x",n:"案内のロボット",t:"野生のテリオンです。安全のため、お客さまは、土手の上へ。"},{w:"x",n:"案内のロボット",t:"野生のテリオンが林へ入った場合、追いかけは中止します。なお、お客さまの持ち物は、補償の対象外です。"},{w:"elly",t:"持ち物じゃないもん！　おうちだもん！"},{w:"x",n:"案内のロボット",t:"テリオンをお連れのお客さまは、広場へどうぞ。"},{w:"elly",f:"serious",t:"……ピリポン。"}];
GR_SC.g03_07=[{w:null,t:"ピリポン、とことこ走っていく。"},{w:null,t:"エリーが走ってきて、箱ごと抱きしめる。"},{w:null,t:"タカの子、しびれが少し取れて、羽をばさばさふる。"},{w:"x",n:"案内のロボット",t:"安全が確認されました。引き続き、観光をお楽しみください。"},{w:null,t:"観光客から拍手。"},{w:null,t:"ドイツ人のだんなさんが、カメラを持って、ヤマトの方へまっすぐ歩いてくる。"},{w:null,t:"ヤマト、土だらけの顔をそででふく。"},{w:null,t:"だんなさん、ヤマトの手にカメラをのせる。"},{w:"hero",f:"serious",t:"……え。"},{w:"elly",t:"フォルンと、三人で撮りたいんだって。"},{w:"hero",t:"おれは？"},{w:"elly",t:"撮る人。"},{w:null,t:"ヤマト、カメラをかまえる。"}];
GR_SC.g03_08=[{w:null,t:"正午。"},{w:null,t:"枯れかけた草の土手。"},{w:null,t:"エリー、へこんだ箱をひざにのせて、ふたに手を置いている。"},{w:null,t:"エリーの手首の画面が、ぴこん。"},{w:null,t:"エリー、画面に「競技場」と打ちかけて、消す。"},{w:null,t:"ヤマト、胸の古い時計を見る。"},{w:null,t:"ヤマト、つまみを、指でかちっと押しこむ。"},{w:"hero",t:"うわ、うわ、なにこれ！　ネット、つながってないのに。"},{w:"elly",t:"あ、それ、おばあちゃんが働いてた所の近く。"},{w:"hero",f:"serious",t:"……ちょっと見るだけ。"},{w:"elly",t:"ちょっとって、どれくらい？"},{w:"hero",t:"入口から、見えるとこまで。"}];
GR_SC.g03_09=[{w:null,t:"競技場の、真下。"},{w:null,t:"ひんやりした石の通路。"},{w:null,t:"つきあたりに、大きな石の扉。"},{w:null,t:"扉のふちに、細かい文字がびっしり。"},{w:"hero",f:"serious",t:"……でっか。"},{w:"elly",f:"serious",t:"……これ、古いギリシャの字。"},{w:null,t:"エリー、文字を指でなぞって、声に出して読む。"},{w:"elly",f:"surprised",t:"えっとね……ここで寝てる子、起こさないでね、だって。"},{w:null,t:"エリーの声が、通路にひびいて、消える。"},{w:null,t:"……足の下の、ずっと深い所から、低い音が一つだけ返ってくる。"},{w:"elly",f:"serious",t:"……今日は、帰ろ。"},{w:"hero",f:"serious",t:"……うん。"}];
GR_SC.g03_10=[{w:null,t:"来た通路をもどる。"},{w:"x",n:"男",t:"……立ち入り禁止って、書いてあっただろ。"},{w:"hero",t:"読めなかった。"},{w:"x",n:"男",t:"……英語でも書いてある。"},{w:"hero",t:"英語も読めない。"},{w:"x",n:"男",t:"……絵もある。"},{w:null,t:"男、あごで、入口の札の×の絵をさす。"},{w:"hero",f:"serious",t:"……絵は、見てない。"},{w:"elly",t:"わたし、ぜんぶ読めたよ。奥の扉のも。"},{w:null,t:"男、だまる。"},{w:null,t:"男の目が、フォルンに止まる。"},{w:null,t:"フォルンのしっぽが、ぴんと立つ。"},{w:null,t:"煙が出口の方へ流れていく。"},{w:"x",n:"案内のロボット",t:"（出口から）そちらは、立ち入り禁止です。"},{w:null,t:"男、銃を下ろす。"},{w:"x",n:"男",t:"……人が多いな。"},{w:null,t:"男、二人とフォルンの横をすりぬけて、オリーブの林の方へ出ていく。"},{w:"elly",f:"serious",t:"……今の人、だれ？"},{w:"hero",t:"知らない。……でも、あいつのワニ、ちょっと、あごが曲がってた。"},{w:null,t:"林の入口で、男が一度だけふり返る。"}];
GR_EP[3]={"t": "古代の競技場", "sc": [["g03_01", "地下（だれもいない）", 0], ["g03_02", "ホテルの前（朝）", 0], ["g03_03", "古代の競技場（昼前）", 0], ["g03_04", "スタートの線", 0], ["g03_05", "タカの子", 0], ["g03_06", "勝負", 1], ["g03_07", "勝負のあと", 0], ["g03_08", "土手の上（正午）", 0], ["g03_09", "地下の扉", 0], ["g03_10", "通路の出口", 0]]};
GR_SC.g04_01=[{w:null,t:"同じ日の夕方。村の裏の森。"},{w:null,t:"小川の上の平たい岩に、背の高い若い男が一人、ひざを立てて座っている。"},{w:null,t:"小川の中を、頭に卵のからをかぶった緑のワニの子が、ぐるぐる回って泳いでいる。"},{w:null,t:"ワニの子が、岸の白っぽい乾いた石の上へ上がる。"},{w:null,t:"男、かばんから、やわらかく煮た魚の包みを出す。"},{w:null,t:"男、うすい財布を開けて、中を見る。"},{w:null,t:"手首の画面が鳴る。"},{w:"x",n:"画面の声（男）",t:"十二番。昼の競技場は、どうでしたか。"},{w:"x",n:"男",t:"人が多かった。……今夜、やる。"},{w:"x",n:"画面の声（男）",t:"ご苦労さまです。……それと、狐と一緒にいた子どもも、連れてきてください。"},{w:"x",n:"男",t:"……子ども？　狐一匹って、聞いた。"},{w:"x",n:"画面の声（男）",t:"部署がちがいますので。狐の、持ち主の反応が出た子どもです。"},{w:null,t:"通話が切れる。"},{w:null,t:"第4話　夜の森"}];
GR_SC.g04_02=[{w:null,t:"その夜。"},{w:null,t:"ホテルの裏口の戸が、そっと開く。"},{w:"hero",f:"serious",t:"……遠足？"},{w:"elly",t:"夜の森、虫いるもん。"},{w:null,t:"エリー、戸のすきまに、クッキーを一枚と紙きれをはさむ。"},{w:null,t:"柵の上から、フォルンが、とん、と下りてくる。"}];
GR_SC.g04_03=[{w:null,t:"ぶどう畑を抜けた先の、暗い森。"},{w:null,t:"かえるの声。"},{w:"elly",t:"この道、カメラないの。昔の石切り場に行く道だから。"},{w:null,t:"ランプのまわりに、羽虫がわっと集まる。"},{w:null,t:"エリー、スプレーをかまえて、ぷしゅー。"},{w:null,t:"フォルンは、森の奥をじっと見ている。"},{w:null,t:"小川の上の平たい岩。"},{w:null,t:"ヤマト、ランプを頭の上にかかげて、腰をひねったまま、止まる。"},{w:"x",n:"男",t:"……何してんだ。"},{w:"hero",f:"serious",t:"……虫、はらってた。"},{w:"x",n:"男",t:"踊ってたろ。"},{w:"hero",t:"はらいながら。"},{w:null,t:"ヤマト、ランプを下ろす。"},{w:"hero",f:"serious",t:"……いつから、いたの。"},{w:"x",n:"男",t:"夕方から。"},{w:"hero",t:"なんで、ここ通るってわかったの。"},{w:"x",n:"男",t:"狐連れて、タクシーには乗れない。昼の道はカメラだらけ。夜、ここしかない。"},{w:null,t:"男、望遠鏡から目をはなさない。"},{w:"hero",f:"serious",t:"……なに見てんの。"},{w:"x",n:"男",t:"星だ。"},{w:"hero",t:"どの星？"},{w:"x",n:"男",t:"……星だ。"},{w:null,t:"男、望遠鏡の筒をていねいにちぢめて、かばんにもどす。"},{w:"x",n:"男",t:"狐は、施設へ。新しい持ち主を探してくれるとこだ。"},{w:"hero",t:"やだ。"},{w:"x",n:"男",t:"……だろうな。網、燃やすんだろ。勝負だ。おれが勝ったら、狐はもらう。"},{w:"hero",f:"smile",t:"おれが勝ったら？"},{w:"x",n:"男",t:"帰る。……報告は、「いなかった」にする。"},{w:null,t:"男の目が、一瞬だけ、ヤマトの顔に止まる。"},{w:"hero",f:"serious",t:"……いいよ。"},{w:"elly",t:"ヤマト！"},{w:null,t:"エリー、しゃがんで、ワニの子の頭の卵のからを見る。"},{w:"elly",t:"（ワニの子に）こんばんは、タマゴちゃん。"},{w:"x",n:"男",t:"……ちがう。"}];
GR_SC.g04_04=[{w:null,t:"男が手首の画面を伏せる。"},{w:null,t:"右手を、小川が上から下までまっすぐ流れている。"},{w:null,t:"男、ワニの子を小川に放す。"},{w:"hero",f:"smile",t:"（エリーに）木の下だ。おととい、それで勝った。"},{w:"elly",f:"serious",t:"……うん。"},{w:null,t:"エリーは、小川を見ている。"},{w:null,t:"エリー、カバンからクッキーの箱を出す。"},{w:null,t:"エリー、箱を森のはしの切り株に置く。"},{w:null,t:"ピリポンが、エリーの指を小さな手でつかむ。"},{w:"x",n:"男",t:"……二体か。"},{w:null,t:"フォルン、大きな木の根もとへ歩いていく。"},{w:"x",n:"男",t:"始め。"}];
GR_SC.g04_06=[{w:null,t:"ピリポン、固まっている。"},{w:null,t:"男、倒れたワニの子のそばにひざをつく。"},{w:null,t:"耳のうしろのうろこのすき間から、小さな板が、ころっと落ちる。"},{w:null,t:"乾いた草の上で、ワニの子の背中のうろこが、白っぽくかわいていく。"},{w:null,t:"ヤマト、小川へ走る。"},{w:null,t:"男、それを見ている。"},{w:"x",n:"画面の声（男）",t:"十二番。回収した狐と、子どもは。"},{w:"x",n:"男",t:"……逃げられた。"},{w:"x",n:"画面の声（男）",t:"両方ですか。"},{w:"x",n:"男",t:"両方。"},{w:"x",n:"画面の声（男）",t:"……そうですか。"},{w:"elly",t:"その子、休ませなきゃ。……うち、すぐそこ。"}];
GR_SC.g04_07=[{w:null,t:"夜ふけ。坂の上のホテル。"},{w:null,t:"玄関の明かりだけが、ついている。"},{w:null,t:"門の内側に、アナが、ほうきを持って立っている。"},{w:"ana",t:"……どこ行ってたの。二人とも。"},{w:"elly",f:"serious",t:"……ちょっと。"},{w:"ana",t:"ちょっとで、泥だらけになるの。……で、あの人、だれ。"},{w:null,t:"門の外の、石の塀のそば。"},{w:"x",n:"男",t:"（ヤマトの胸の時計を見て）……その時計。競技場で、光ってたな。"},{w:null,t:"ヤマト、時計を手で押さえる。"},{w:null,t:"男の目が、ヤマトのリュックの横ポケットに行く。"},{w:"x",n:"男",t:"この辺の遺跡は、全部、案内してる。……白い都までの道も、わかる。案内、いるか。"},{w:"hero",f:"serious",t:"……お金、ないよ。"},{w:"x",n:"男",t:"……金は、観光客の案内で稼ぐ。"},{w:"hero",t:"じゃあ、おれらは、ただ？"},{w:"x",n:"男",t:"……ただとは言ってない。"},{w:"elly",t:"いくら？"},{w:null,t:"男、指を折りかける。"},{w:"elly",t:"クッキー、一枚なら出せるよ。"},{w:"x",n:"男",t:"……いらない。"},{w:"hero",t:"オリーブ、五つ。"},{w:null,t:"フォルンの耳が、ぴくっとヤマトの方へ向く。"},{w:"x",n:"男",t:"……それ、狐のだろ。"},{w:"hero",f:"serious",t:"……じゃあ、四つ。"},{w:null,t:"フォルン、ヤマトのリュックの前に、どすっと座りこむ。"},{w:null,t:"エリー、塀の下にしゃがむ。"},{w:"elly",t:"（ワニの子に）おやすみ、タマゴちゃん。"},{w:"x",n:"男",t:"……クロッコ。"},{w:"elly",t:"クロッコちゃん。"},{w:"x",n:"男",t:"……ちゃんは、いらない。"},{w:"hero",f:"serious",t:"……いる。案内。……おれ、ヤマト。"},{w:"alek",t:"……アレク。"},{w:"elly",t:"お姉ちゃん、この人、泊めて！"},{w:null,t:"アナ、ほうきを持ったまま、アレクを上から下まで見る。"},{w:"ana",t:"……一泊いくら。"},{w:null,t:"アレク、ポケットの中で、うすい財布をにぎる。"}];
GR_EP[4]={"t": "夜の森", "sc": [["g04_01", "森の小川（夕方）", 0], ["g04_02", "ホテルの裏口（夜）", 0], ["g04_03", "森の道（夜）", 0], ["g04_04", "向かい合う", 0], ["g04_05", "勝負", 1], ["g04_06", "勝負のあと", 0], ["g04_07", "ホテルの門（夜ふけ）", 0]]};
GR_SC.g05_01=[{w:null,t:"坂のとちゅうに、白い小さな車。"},{w:null,t:"うしろの席。"},{w:"nina",t:"マルコ。起きて。仕事。"},{w:"marco",t:"……それ、十二番の仕事でしょ。"},{w:"nina",t:"その十二番が、ゆうべから返事しないの。"},{w:null,t:"マルコ、帽子を少しだけ上げる。"},{w:"marco",t:"……めんど。"},{w:null,t:"マルコの足もとで、黒い体にオレンジの点の散った大きなヤモリが、目をあける。"},{w:null,t:"耳のうしろで、小さな白い盾が、ちかっと光る。"},{w:null,t:"第5話　夜明けの火"}];
GR_SC.g05_02=[{w:null,t:"坂の上のホテル。四日目の朝。"},{w:null,t:"ぶどう畑のはしの道具小屋から、アレクが毛布をたたみながら出てくる。"},{w:null,t:"二階の窓から、アナの手が紙を一枚さし出す。"},{w:null,t:"アレク、ポケットの硬貨を数えて、窓の手にのせる。"},{w:null,t:"小屋の横の石の水おけ。"}];
GR_SC.g05_03=[{w:null,t:"朝ごはんのテラス。"},{w:"hero",t:"でさ、相手、水なわけ。こっちは炎。ふつう、負けるじゃん。"},{w:"x",n:"客の子A",t:"負けるの？"},{w:"hero",t:"負ける。でも、そこでおれが気づいちゃったわけ。"},{w:null,t:"ヤマト、指を立てて、炎、森、水、と一本ずつ折っていく。"},{w:"hero",t:"じゃんけんになってんの。全部。"},{w:"x",n:"客の子B",t:"じゃんけんで勝ったの？"},{w:"hero",f:"smile",t:"じゃんけんみたいなもんで、勝ったの。"},{w:"elly",t:"（パンをちぎりながら）気づいたの、負けそうになってからだよね。"},{w:"hero",t:"負けそうでも、気づいたもんは気づいたの。"},{w:null,t:"テーブルのはしで、フォルンがしっぽの火の上でオリーブを転がしている。"},{w:null,t:"ヤマト、いちばん大きい焼きオリーブを、ひょいとつまむ。"},{w:"hero",t:"これ、作戦料ね。"},{w:null,t:"フォルンのしっぽの火が、ぼっとふくらむ。"},{w:"hero",t:"あっ、ち、ち、ち——"},{w:null,t:"オリーブが手のひらの上でおどる。"},{w:null,t:"フォルン、宙のオリーブを口で受けとめる。"},{w:null,t:"子どもたちが、どっと笑う。"},{w:"hero",f:"serious",t:"……今のは、わざと。"},{w:"x",n:"客の子C",t:"わざとなの？"},{w:"hero",t:"わざと。……まあ、次、だれが来ても、おれとフォルンで——"},{w:null,t:"ロビーの画面に、村のお知らせ。"},{w:null,t:"アナが、その画面を見ている。"},{w:"ana",t:"ヤマト。お客さん。門に。"}];
GR_SC.g05_04=[{w:null,t:"門の外に、マルコ。"},{w:"marco",t:"どうも。網の係の、マルコっす。……狐、いますよね、ここ。"},{w:null,t:"ヤマトの足もとで、フォルンの耳が立つ。"},{w:null,t:"マルコの目が、フォルンから、そのうしろへ行く。"},{w:"marco",t:"……十二番。なにしてんすか、そこで。"},{w:null,t:"アレク、答えない。"},{w:"marco",t:"まあ、いいや。そういうの報告すんの、めんどいんで。"},{w:null,t:"坂の下で、ニーナの画面が、かしゃっと鳴る。"},{w:"marco",t:"一対一で、どうすか。そっちが勝ったら、おれは手を引きます。おれが勝ったら、狐はもらってく。"},{w:"hero",t:"いいよ。"},{w:"alek",t:"……待て。"},{w:"hero",f:"smile",t:"なんで。ゆうべ勝ったじゃん。"},{w:null,t:"マルコの肩のヤモリが、口をあける。"},{w:null,t:"エリーのカバンの中で、ぱちっ。"},{w:"elly",f:"serious",t:"……ピリポン、ああいう火、だめなの。"},{w:"alek",t:"あれは二段目だ。おまえの狐は、まだ一段目。"},{w:"hero",t:"段とか関係ないって。どっちも炎だろ。"},{w:null,t:"アレク、水おけを見る。"},{w:"alek",t:"……待てって。"},{w:null,t:"ヤマトは、もう門の外に出ている。"},{w:"marco",t:"どこでもいいっすけど。……裏の畑で。木の下、すずしいんで。"}];
GR_SC.g05_05=[{w:null,t:"ぶどう棚の前で、マルコが畑を見わたす。"},{w:null,t:"向こう半分は、古いオリーブの林。"},{w:null,t:"マルコ、林の木の下に木箱を置いて、座る。"},{w:null,t:"ヤマト、フォルンを手前の畑のまん中に置く。"},{w:null,t:"アレクとエリーが、ぶどう棚の下に立つ。"},{w:"marco",t:"じゃ、始め。"}];
GR_SC.g05_09=[{w:null,t:"フォルンの体から、光がすうっと引いていく。"},{w:null,t:"マルコ、オキヤモを両腕でかかえ上げて、重そうに肩にかつぎ直す。"},{w:"marco",t:"……約束は約束なんで。"},{w:"nina",t:"マルコ、写真。本部に。"},{w:"marco",t:"もう撮ってたでしょ、坂の下で。"},{w:null,t:"マルコ、帰りかけて、アレクの前で止まる。"},{w:"marco",t:"十二番。……抜けんなら、もっと遠くまで行った方がいいっすよ。うちの本部、しつこいんで。"},{w:"alek",t:"……分かってる。"},{w:null,t:"マルコ、坂を下りていく。"},{w:null,t:"ヤマト、フォルンの前にしゃがむ。"},{w:null,t:"フォルン、首をくるっと回して、ヤマトの帽子を、ぱくっとくわえて取る。"},{w:"hero",t:"おい。"},{w:null,t:"フォルン、忘れ物の札をぶらぶらさせながら、畑の外へすたすた出ていく。"},{w:"hero",t:"返せって！"}];
GR_SC.g05_10=[{w:null,t:"ロビーの画面。"},{w:null,t:"画面が切りかわって、広告。"},{w:null,t:"ヤマト、その前に立っている。"},{w:null,t:"アレクがうしろに来て、画面の時計を見る。"},{w:"alek",t:"昼に、白いのが来る。"},{w:null,t:"パンの袋をつめていたエリーの手が、一瞬だけ止まる。"},{w:"hero",t:"白い都まで、どれくらい。"},{w:"alek",t:"歩きなら、二週間。"},{w:"hero",f:"serious",t:"……歩き？"},{w:null,t:"門の前を、ロボタクシーがすうっと通る。"},{w:"alek",t:"乗るな。居場所が出る。"},{w:null,t:"アレク、水おけからクロッコを出して、背中にかつぐ。"},{w:"ana",t:"おばあちゃんから、電話あった。……止めても行くんでしょ。"},{w:null,t:"エリー、目をそらして、笑う。"},{w:"ana",t:"（アレクに）帰ってきたら、払って。"},{w:"alek",t:"昼でも、森の道だ。"}];
GR_SC.g05_11=[{w:null,t:"朝の光が、小川の底までさしこんでいる。"},{w:null,t:"画面が、水の中でぽうっと光る。"},{w:null,t:"白い小さなドローンが一機、低く飛んでくる。"},{w:null,t:"赤い光が、岸のぬかるみで止まる。"},{w:null,t:"ドローンが高く上がる。"}];
GR_EP[5]={"t": "夜明けの火", "sc": [["g05_01", "村を見下ろす坂（夜明け）", 0], ["g05_02", "ホテルの裏・道具小屋（朝）", 0], ["g05_03", "ホテルのテラス（朝）", 0], ["g05_04", "ホテルの門", 0], ["g05_05", "ホテルの裏の畑・向かい合う", 0], ["g05_06", "勝負・突っこむ", 1], ["g05_07", "勝負・止まらない", 1], ["g05_08", "勝負・水をまたがない", 1], ["g05_09", "勝負のあと", 0], ["g05_10", "ホテルの門（昼前）", 0], ["g05_11", "ホテル裏の森の小川", 0]]};
GR_SC.g06_01=[{w:null,t:"フォルンが、いちばん外がわで丸くなっている。"},{w:null,t:"丘の下の道。"},{w:null,t:"アレク、目をあける。"},{w:null,t:"ドローンが、丘の方へ向きを変える。"},{w:null,t:"アレク、ヤマトの毛布のはしをつかんで、木のかげの奥へ引っぱる。"},{w:null,t:"ドローンが木の上を通りすぎる。"},{w:"hero",t:"（寝ぼけて）……なに。"},{w:"alek",t:"道は、もう使わない。畑を行く。"},{w:null,t:"第6話　丘の畑"}];
GR_SC.g06_02=[{w:null,t:"オリーヴァ村の東。オリーブの丘が、いくつも続く。"},{w:"hero",t:"手でとると、高く売れるんだろ。エリーに聞いた。"},{w:"alek",t:"……手で摘んだ、って書くと、高い。"},{w:"hero",f:"serious",t:"……書くと？"},{w:null,t:"ヤマト、少し考える。"},{w:null,t:"ヤマト、布を持ったまま動けなくなる。"},{w:"hero",f:"serious",t:"……ちょっと、待って。"},{w:null,t:"クロッコが、アレクの背中から自分で下りて、足のうしろを歩いている。"},{w:null,t:"ピリポンは、エリーのカバンのクッキーの箱から顔だけ出している。"}];
GR_SC.g06_03=[{w:null,t:"丘のいちばん上の畑。"},{w:null,t:"幹の小さな穴のいくつかに、白い網の切れはしがひっかかったまま。"},{w:null,t:"畑のはしを、石を組んだ溝が流れている。"},{w:null,t:"手前のすみに、昔の脱穀場の、丸い石の床。"},{w:null,t:"男が一人、くずれた溝の石を、だまって積み直している。"},{w:null,t:"ヤマト、石の床の上に、大の字に寝ころがる。"},{w:"hero",t:"エリー、ここ、石がぽかぽか。ちょっと寝てっていい？"},{w:null,t:"エリーのカバンから、ピリポンが石の床に、ぴょんと下りる。"},{w:null,t:"火花が、寝ているヤマトのおしりに届く。"},{w:"hero",t:"いでっ！"},{w:null,t:"ヤマト、とび起きる。"},{w:null,t:"太いオリーブの幹に、大きなカブトムシの子がとまっている。"},{w:"hero",t:"うわ、でっか。……これ、ヘラクレスオオカブトだろ。動画で見た。"},{w:"elly",t:"ヘラクレスは、人だよ。"},{w:"hero",t:"人？"},{w:"elly",t:"すっごく力持ちの人。昔の。"},{w:"hero",f:"serious",t:"……カブトムシじゃなくて？"},{w:"elly",t:"人。"},{w:null,t:"カブトムシの子が、幹の上で前足を、ぐっとふんばる。"},{w:null,t:"エリーだけが、それを見ている。"},{w:null,t:"ヤマトは男のかごの黒い実を一つつまんで、光にかざしている。"},{w:"hero",t:"（男に）これ、なに味？"},{w:null,t:"ヤマト、もう口を大きくあけている。"},{w:"stavros",f:"serious",t:"……なまは、食えない。"},{w:null,t:"ヤマトの口が、あいたまま止まる。"},{w:null,t:"男の目が、ヤマトのうしろへ行く。"},{w:"stavros",t:"……先月。白い盾の連中を、この畑まで連れてきたのは、おまえだな。"},{w:null,t:"アレク、目をそらさない。"},{w:"alek",t:"……ああ。"},{w:"hero",t:"え。"},{w:"elly",t:"アレク？"},{w:"alek",t:"……前の仕事だ。"},{w:null,t:"ヤニス、幹の穴に指を入れて、白い網の切れはしをつまみ出す。"},{w:"stavros",t:"あの晩、この木の子が、みんないなくなった。小さいのが、十二。"},{w:null,t:"カブトムシの子が、羽を一度だけふるわせる。"},{w:"hero",t:"おれたち、あいつらじゃない！"},{w:"stavros",t:"あの連中も、最初は、そう言った。"},{w:null,t:"ヤニス、棒を、畑の入口に横にわたす。"},{w:"stavros",t:"通るなら、こいつに勝て。負けたら、来た道を帰れ。"},{w:null,t:"ヤマトの顔が、少しだけ固まる。"},{w:"alek",t:"……三体で、いいか。"},{w:"stavros",t:"いい。"}];
GR_SC.g06_04=[{w:null,t:"ヤニスが、畑のまん中まで歩いていく。"},{w:null,t:"向こうのはしはオリーブの木。"},{w:null,t:"ヤニス、ヘラツノを木の手前の草に置く。"},{w:null,t:"ヤマト、フォルンを手前のまん中に。"},{w:null,t:"ヤマトの口のはしが、上がる。"},{w:null,t:"アレク、クロッコを溝のそばの草に。"},{w:null,t:"エリー、石の床の左がわのはしに立つ。"},{w:"stavros",t:"始め。"}];
GR_SC.g06_08=[{w:null,t:"フォルンとピリムサの体から、光がすうっと引いていく。"},{w:null,t:"ヤニス、ヘラツノのそばにしゃがむ。"},{w:null,t:"エリー、石の床の上のピリポンをだき上げる。"},{w:"elly",t:"ピリポン、さっき、おっきかった！"},{w:null,t:"ピリポン、エリーの顔に、ぱちっ。"},{w:null,t:"アレク、クロッコをだき起こす。"},{w:null,t:"ヤニス、立ち上がって、アレクの前に来る。"},{w:null,t:"ヤニス、アレクの手首を見る。"},{w:"stavros",f:"serious",t:"……これは、食える。"},{w:"stavros",f:"serious",t:"……そこじゃない。"},{w:"hero",t:"これ、何年？"},{w:"stavros",f:"serious",t:"……千年は、こえてる。"},{w:"hero",t:"千……。"},{w:"elly",f:"serious",t:"……出てるじゃん。"}];
GR_SC.g06_09=[{w:null,t:"丘のてっぺんに、三人と三体。"},{w:null,t:"アレク、紙の地図を広げて、煙の方をなぞる。"},{w:"alek",t:"……アルカディアの森だ。"},{w:"hero",t:"あれ、燃えてんの？"},{w:null,t:"アレク、答えない。"},{w:null,t:"フォルンの鼻が、ひくっと動く。"}];
GR_EP[6]={"t": "丘の畑", "sc": [["g06_01", "丘のオリーブの木の下（夜明け）", 0], ["g06_02", "丘の斜面（朝）", 0], ["g06_03", "ヤニスの畑", 0], ["g06_04", "向かい合う", 0], ["g06_05", "勝負・追う", 1], ["g06_06", "勝負・下がる先", 1], ["g06_07", "勝負・決着", 1], ["g06_08", "勝負のあと", 0], ["g06_09", "丘の上（夕方）", 0]]};
GR_SC.g07_01=[{w:null,t:"川べりの大きな岩の上に、ニーナが白い箱を置く。"},{w:"nina",t:"これで、歌が流れる。あとは、勝手に歩いてくる。"},{w:"marco",t:"……じゃあ、網、いらなくないすか。"},{w:"nina",t:"歌で来ない子は、網。今度しくじったら、番号、下がるからね。"},{w:null,t:"ニーナが網の銃を撃つ。"},{w:"marco",t:"あばれると、網、破れるんすよね。……オキヤモ、ちょっとだけ、おどかして。"},{w:null,t:"マルコの肩のオキヤモが、口をあける。"},{w:null,t:"耳のうしろで、白い盾がちかっと光る。"},{w:null,t:"オキヤモ、口を閉じない。"},{w:null,t:"網から抜けた角の子が、森の奥へ逃げていく。"},{w:"marco",t:"止まれ。……止まれって。"},{w:null,t:"ニーナの手首の画面。"},{w:"nina",t:"……また入ってる。"},{w:"marco",t:"切っても、入ってくるんすよ、これ。"},{w:null,t:"マルコ、水の筒の水を、燃える落ち葉にかける。"},{w:null,t:"第7話　ラドン川の歌"}];
GR_SC.g07_02=[{w:null,t:"夜明けの道。"},{w:null,t:"アルカディア。楽園の名を持つ森。入口に、料金所がある。"},{w:null,t:"木のゲート。"},{w:"x",n:"受付のロボット",t:"十五さい以上一名、十五さい未満二名、テリオン三体。森の保全料を、いただきます。"},{w:null,t:"ロボットの胸の画面に、金額。"},{w:"x",n:"受付のロボット",t:"……追加料金で、お通りいただけます。"},{w:null,t:"エリー、しゃがんで、フォルンをカメラの前へ押し出そうとする。"},{w:"elly",t:"この子、フォルン。テリオンだよ。"},{w:"x",n:"受付のロボット",t:"フォルン様。判定できません。"},{w:null,t:"アレク、画面の数字を見たまま、しばらく動かない。"},{w:"x",n:"受付のロボット",t:"なお、本日、森の東がわで煙が確認されています。消防のドローンが向かっております。"},{w:null,t:"棒が上がる。"}];
GR_SC.g07_03=[{w:null,t:"焦げたにおいが、だんだん強くなる。"},{w:null,t:"木のあいだがひらけた所。"},{w:null,t:"腰のまがったおばあさんが、バケツの水を燃える草にかけている。"},{w:null,t:"バケツを回す人たちの中に、すすで顔のまっ黒な男。"},{w:null,t:"アレク、もうクロッコを小川に下ろしている。"},{w:null,t:"エリー、ピリポンを地面に下ろしかけて、やめる。"},{w:null,t:"エリー、ピリポンを箱に入れたまま、自分でバケツを回す人たちの中に入る。"},{w:null,t:"フォルン、燃える草の前に立つ。"},{w:null,t:"ヤマト、バケツを回す人たちの所へ走っていく。"},{w:null,t:"わたしてきたのは、マルコ。"},{w:"hero",t:"あ。門の——"},{w:"marco",t:"今、それ、いいっす。"},{w:null,t:"ヤマト、バケツを次の人にわたす。"},{w:null,t:"フォルン、四つ目の火を吸いこむ。"},{w:null,t:"最後の煙が、消える。"},{w:null,t:"みんな、すすだらけで地面に座りこむ。"},{w:"nina",t:"ドローン。行くよ。"},{w:null,t:"ニーナ、マルコの腕を引く。"},{w:null,t:"赤い消防のドローンが一機、下りてくる。"},{w:null,t:"森の奥へ続く道の入口に、細い棒を二本立てる。"},{w:null,t:"ドローン、そのまま飛んで帰っていく。"},{w:null,t:"おばあさん、バケツの上から、空を見上げる。"},{w:"x",n:"森番のおばあさん",t:"……あれが来るのは、いつも、消えたあとだね。"},{w:null,t:"ヤマト、光るひもに手を近づける。"},{w:null,t:"エリー、焦げた草の中から、燃え残った網の切れはしを拾う。"},{w:null,t:"アレク、それを見る。"}];
GR_SC.g07_04=[{w:null,t:"ラドン川。この秋、夜になると、川から歌が聞こえる。"},{w:null,t:"森の外がわを流れる川。"},{w:null,t:"アレク、紙の地図を広げる。"},{w:"alek",t:"……道は、止まった。川しかない。"},{w:null,t:"切符売り場の窓口に、古い電話。"},{w:null,t:"アレク、切符の機械に硬貨を入れる。"},{w:null,t:"ヤマト、それを横から見ている。"},{w:null,t:"アレク、ヤマトを見る。"}];
GR_SC.g07_05=[{w:null,t:"むかしの帆船をまねた、小さな観光船。"},{w:null,t:"案内のロボットが、かごを持って回っている。"},{w:"x",n:"案内のロボット",t:"このあと「歌の瀬」を通ります。歌を聞いたテリオンが、岸へ歩いていってしまうことがございます。お客さまも、お連れのテリオンも、こちらをどうぞ。"},{w:null,t:"エリー、ピリポンに耳あてをかぶせる。"},{w:null,t:"エリーがフォルンにも耳あてを持っていく。"},{w:null,t:"ヤマトだけ、耳せんを取らない。"},{w:"elly",t:"ヤマト、耳せん。"},{w:"hero",t:"聞きたい。どんなのか。"},{w:"alek",t:"……川に飛びこむぞ、おまえ。"},{w:null,t:"ヤマト、太い帆柱を見上げる。"},{w:"hero",t:"じゃ、しばって。あの柱に。……いちおう。"},{w:null,t:"アレク、長いあいだヤマトを見る。"},{w:"alek",t:"……ほどくか。"},{w:"hero",f:"serious",t:"……いや。"},{w:"alek",t:"どっちだ。"},{w:"hero",t:"いちおう。"},{w:null,t:"アレク、結び目を、もう一つ足す。"},{w:null,t:"案内のロボットが、船のまん中で話しはじめる。"},{w:"x",n:"案内のロボット",t:"この川には、昔から歌の話がございます。海の岩の上で歌う、鳥の体をした女の人たち。その歌を聞いた船乗りは、船ごと岩へ寄っていってしまう。そこで、ある船長は、自分を帆柱にしばらせて、歌を聞いたそうです。"},{w:null,t:"客の何人かが、帆柱のヤマトを見る。"},{w:"x",n:"案内のロボット",t:"また、この森のそばの山には、生まれたその日に、牛をうしろ向きに歩かせて、足あとで大人をだました、子どもの神さまの話がございます。"},{w:"elly",t:"かしこい！"},{w:"hero",t:"なに？"},{w:"elly",t:"うしろ向きの足あとで、大人をだましたの。赤ちゃんが。"},{w:"hero",f:"serious",t:"……ふーん。"},{w:null,t:"ヤマト、また結び目をさぐる。"}];
GR_SC.g07_06=[{w:null,t:"川幅が広くなる。"},{w:null,t:"歌が聞こえてくる。"},{w:null,t:"岸の葦のあいだから、野生の子たちが出てくる。"},{w:null,t:"ヤマトの目が、その子たちを追う。"},{w:"hero",t:"ほどいて。ちょっとだけ！"},{w:null,t:"だれも、ふり向かない。"},{w:"hero",t:"エリー！　ほどいてって！　エリー！"},{w:null,t:"エリー、ヤマトに気づく。"},{w:"hero",t:"ちがう！！"},{w:null,t:"ヤマト、帆柱ごと岸の方へ体を投げ出そうとする。"},{w:null,t:"船べりで、フォルンが頭を上げる。"},{w:null,t:"船は、岸の大きな岩のすぐ横を通っている。"},{w:null,t:"フォルン、立ち上がる。"},{w:null,t:"岩の上に着地。"},{w:null,t:"フォルン、線に、がぶっとかみつく。"},{w:null,t:"川の中の子たちが、歩きかけた足のまま止まる。"},{w:null,t:"フォルン、口から線をぺっと吐く。"},{w:null,t:"ヤマト、ロープにぶら下がるように、ぐったりする。"},{w:null,t:"アレク、耳せんを片方だけ外す。"},{w:"alek",t:"……なんか言ったか。"},{w:"hero",f:"serious",t:"……ぜんぜん、平気だった。"}];
GR_SC.g07_07=[{w:"x",n:"案内のロボット",t:"機械の確認のため、こちらで少し停まります。"},{w:null,t:"観光船が岩に寄る。"},{w:null,t:"箱は横だおし。"},{w:null,t:"アレクがしゃがんで、箱の底に懐中電灯を当てる。"},{w:null,t:"エリー、カバンから、昼に拾った網の切れはしを出す。"},{w:null,t:"エリー、箱の丸い穴を見る。"},{w:"elly",t:"あの子たち、どこに歩いてくとこだったの。"},{w:null,t:"アレク、札の字を、指でなぞる。"},{w:"alek",t:"……森の奥。"},{w:null,t:"アレク、自分の手首を、そでの上からぎゅっとにぎる。"},{w:null,t:"ヤマト、ロープのあとの残る腕で、フォルンの首をなでようとする。"},{w:null,t:"ヤマト、なでかけた手のまま、ついていく。"}];
GR_SC.g07_08=[{w:null,t:"最後の船着き場。"},{w:null,t:"岸から上がる道に、また、細い棒が二本。"},{w:"hero",f:"serious",t:"……また？"},{w:null,t:"アレク、地図を広げかけて、手を止める。"},{w:null,t:"明かりの方へ歩く。"},{w:null,t:"そのはしに、小さな木の小屋。"},{w:null,t:"小屋のうしろの夜空に、背の高い鉄の骨組みが、まっすぐ立っている。"},{w:null,t:"骨組みの足もとに、工事の看板。"},{w:null,t:"エリー、小屋の戸を、こんこんとたたく。"},{w:"x",n:"女の人",t:"……なに。"},{w:"elly",t:"泊まるとこ、ありますか！"},{w:null,t:"女の人、三人を見る。"},{w:null,t:"女の人の目が、少しだけ細くなる。"},{w:"x",n:"女の人",t:"……床で、いいなら。"}];
GR_EP[7]={"t": "ラドン川の歌", "sc": [["g07_01", "アルカディアの森・川べりの岩（ゆうべ）", 0], ["g07_02", "アルカディアの森の入口（朝）", 0], ["g07_03", "森の中（朝）", 0], ["g07_04", "川の船着き場（夕方）", 0], ["g07_05", "観光船の上（夜）", 0], ["g07_06", "歌の瀬（夜）", 0], ["g07_07", "岸の大岩（夜）", 0], ["g07_08", "森の外れの船着き場（夜ふけ）", 0]]};
GR_SC.g08_01=[{w:null,t:"頭に明かりをつけた研究者が、土の中にしゃがんでいる。"},{w:null,t:"土の中から、白っぽい、丸い物が出てくる。"},{w:null,t:"研究者、ブラシを止める。"},{w:null,t:"穴の奥は、まっ暗。"},{w:null,t:"第8話　巨人の骨"}];
GR_SC.g08_02=[{w:null,t:"アルカディアの森の外れ。化石の発掘場。"},{w:null,t:"棚に、箱がぎっしり。"},{w:null,t:"戸があいて、研究者が入ってくる。"},{w:"kenkyu",t:"朝ごはん、パンしかないけど。"},{w:null,t:"ヤマト、むくっと起きる。"},{w:"hero",t:"パン！"},{w:null,t:"テーブルに、かたいパンと、水。"},{w:"elly",t:"ずっと、掘ってるの？"},{w:"kenkyu",t:"ずっと。"},{w:"elly",t:"ロボットに、やってもらわないの？"},{w:"kenkyu",t:"前に、やらせた。骨も石も、ぜんぶ同じ「石」の箱に入れた。"},{w:null,t:"研究者、窓の外をあごでさす。"},{w:"kenkyu",t:"それから、手で掘ってる。"},{w:null,t:"アレク、窓の外を見ている。"},{w:null,t:"小屋の軒下の壁ぎわに、子ども用の寝袋が一つ、きっちり丸めて置いてある。"},{w:"alek",t:"あれは。"},{w:"kenkyu",t:"塔。電波の。半年前から、勝手に建ってる。"},{w:"elly",t:"（軒下の寝袋を見て）あれ、だれの？"},{w:"kenkyu",t:"工事の子。夜だけ。宿まで、歩くと一時間だから。"},{w:"kenkyu",t:"（三人に）掘ってる所には、さわらないで。ひもの中は、だめ。"}];
GR_SC.g08_03=[{w:null,t:"ひもで四角く区切った穴が、いくつも並んでいる。"},{w:null,t:"ヤマト、ひものまわりを、うろうろしている。"},{w:"elly",t:"ヤマト、ひもの中、だめって。"},{w:"hero",t:"ひもの外なら、いいんだろ。"},{w:null,t:"ヤマト、ひもの外の、草の生えた所にしゃがむ。"},{w:"hero",t:"化石なんてさ、どこにでも埋まってんだって。こういう、だれも見てない所に——"},{w:null,t:"スコップの先に、かちん。"},{w:"hero",t:"ほら！"},{w:null,t:"ヤマト、両手で掘る。"},{w:null,t:"エリーが、パンをかじりながら、穴の上からのぞいている。"},{w:null,t:"穴の中から、ヤマトが、白い石を両手で持ち上げる。"},{w:"hero",t:"見て！　骨！"},{w:null,t:"エリー、少しのあいだ見る。"},{w:"elly",t:"……それ、さっき研究者さんが投げてた石だよ。"},{w:null,t:"ヤマト、石を見る。"},{w:null,t:"ヤマト、石を置く。"},{w:null,t:"穴は、ヤマトの背より深くなっている。"},{w:"hero",f:"serious",t:"……エリー。手。"},{w:null,t:"エリー、手をのばす。"},{w:null,t:"ヤマト、髪を立てたまま、だまってエリーを見上げる。"},{w:null,t:"アレク、遠くの小屋の前で、紙の地図を広げたまま、顔も上げない。"},{w:"hero",t:"アレク！"},{w:"alek",t:"……自分で掘ったんだろ。"},{w:null,t:"穴のふちに、影がさす。"},{w:null,t:"黄色い毛に、黒いぎざぎざのしま。"},{w:null,t:"となりに、少年が一人。"},{w:"x",n:"少年",t:"……なにしてんの。"},{w:"hero",f:"serious",t:"……掘ってた。"},{w:null,t:"少年、トラの子の背中を、指で一回たたく。"},{w:null,t:"ヤマト、しっぽをつかむ。"},{w:"hero",t:"いっ——"},{w:null,t:"トラの子、立ち上がる。"},{w:null,t:"少年、ヤマトの顔を見る。"},{w:"x",n:"少年",t:"……となりのクラスの。"},{w:"hero",f:"serious",t:"……だれ？"},{w:"x",n:"少年",t:"レン。四組。"},{w:"hero",t:"おれ、三組。"},{w:"dimi",t:"だから、となりだろ。"},{w:"hero",t:"なんで、いんの。ギリシャに。"},{w:"dimi",t:"父さんの会社の現場。あの塔。"},{w:null,t:"レン、鉄の骨組みをあごでさす。"},{w:"dimi",t:"見回り。父さんの手伝い。昼は、下を回るの、おれとライガ。"},{w:"hero",f:"serious",t:"……おまえ、ひとりで？"},{w:"dimi",t:"ライガと。"}];
GR_SC.g08_04=[{w:null,t:"発掘場のはしの、骨をしまう小屋。"},{w:null,t:"アバンの、大きな丸い骨。"},{w:"elly",f:"serious",t:"……顔？"},{w:"kenkyu",t:"頭の骨。大昔の。"},{w:null,t:"ヤマト、穴をのぞく。"},{w:"hero",t:"目、一個しかない。"},{w:"kenkyu",t:"大昔の人も、そう思った。こういう骨を見て、一つ目の巨人の話を作った。"},{w:"hero",t:"巨人って、ほんとにいたの？"},{w:"kenkyu",t:"これは、象。"},{w:"hero",t:"象？"},{w:"kenkyu",t:"まん中の穴は、鼻の穴。"},{w:null,t:"ヤマト、穴を見る。"},{w:"hero",f:"serious",t:"……象の鼻、ここから出てんの。"},{w:"kenkyu",t:"出てる。"},{w:null,t:"エリー、台のすみの小さな箱の中を、のぞいている。"},{w:null,t:"エリー、指で土をはらう。"},{w:"elly",t:"「この子は、わたしたちの言葉しか聞かない。」"},{w:null,t:"研究者の、シートをたたんでいた手が、止まる。"},{w:null,t:"研究者、エリーを見る。"},{w:"kenkyu",t:"……わたし、それ、辞書を引いて三日かかった。"},{w:"elly",t:"なんか、読めた。"},{w:null,t:"エリー、石を箱にもどす。"},{w:null,t:"研究者は、エリーの横顔を見たまま。"},{w:null,t:"ヤマトは、象の骨の鼻の穴に、腕を入れて、長さをはかっている。"},{w:null,t:"レンは、エリーを少しだけ見て、それから、手首の画面の時刻を見る。"}];
GR_SC.g08_05=[{w:null,t:"小屋の前に、たき火。"},{w:null,t:"レンも、たき火のそばに座っている。"},{w:"kenkyu",t:"お父さんは。"},{w:"dimi",t:"塔の上。朝まで。"},{w:null,t:"フォルンが、たき火のはしの石の上で、しっぽの火でオリーブを焼いている。"},{w:null,t:"アレクは、クロッコに煮た魚を指で食べさせている。"},{w:null,t:"ライガが、のそっと立ち上がる。"},{w:null,t:"フォルンの首のまわりの毛が、ぼっと燃え上がる。"},{w:null,t:"ライガの毛の先が、ばちばちっと光る。"},{w:"hero",t:"フォルン、やめろ。"},{w:null,t:"フォルン、止まらない。"},{w:null,t:"レン、座ったまま、人さし指を一本だけ、すっと立てる。"},{w:null,t:"ライガ、ぴたりと止まる。"},{w:"hero",t:"やめろって。もう行ったって。"},{w:"elly",t:"レンも、大会、出るの？"},{w:"dimi",t:"出る。"},{w:"hero",f:"serious",t:"……おれも、出る。"},{w:"dimi",t:"その狐、だれの。"},{w:"hero",f:"serious",t:"……優勝したら、おれの。"},{w:"dimi",t:"（立ち上がって）寝る。あしたも、見回り。"}];
GR_SC.g08_06=[{w:null,t:"たき火が、小さくなっている。"},{w:null,t:"研究者が、鍋を下ろす。"},{w:null,t:"研究者、声を落とす。"},{w:"kenkyu",t:"昼の石。あの字。"},{w:"elly",t:"うん。"},{w:"kenkyu",t:"ああいう字の時代の子がね、一度だけ、よみがえったことがある。"},{w:"hero",t:"テリオン？"},{w:"kenkyu",t:"五十年くらい前ね。骨の中にね、設計図が残ってることがある。"},{w:"hero",t:"設計図？"},{w:"kenkyu",t:"生き物の。それを読んで、印刷した人たちがいた。"},{w:"alek",t:"……化石から。"},{w:"hero",t:"強かった？"},{w:"kenkyu",t:"大きくて、強かった。でも、昔の言葉しか分からない。何を言っても、聞かなかった。"},{w:null,t:"ヤマト、たき火のむこうのフォルンを見る。"},{w:"hero",f:"serious",t:"……それ、ふつうじゃん。"},{w:"kenkyu",t:"ふつうの子は、おなかがすいたら寄ってくる。あの子たちは、ごはんを出しても、こっちを見なかったって。"},{w:null,t:"アレク、地図をなぞっていた指を止める。"},{w:"alek",t:"……それで、消したのか。"},{w:"kenkyu",t:"禁止。それから、いなかったことにした。図鑑にも、ニュースにも、出てこない。"},{w:"elly",t:"その子たち、どこ行ったの。"},{w:"kenkyu",t:"どこかで、寝てる。……って話。"},{w:"hero",t:"起こせないの？"},{w:"kenkyu",t:"起こし方は、だれも分からない。"},{w:"hero",f:"serious",t:"……でも、いたことは、分かってんじゃん。"},{w:"kenkyu",t:"いたこと、だけね。それを覚えてるのは、国の上の方の人と、わたしみたいな、骨を掘ってる人だけ。"},{w:null,t:"研究者、たき火に枝を一本足す。"},{w:"kenkyu",t:"外で言ったら、わたしが捕まる。"},{w:"hero",t:"じゃあ、なんで言ったの。"},{w:null,t:"研究者、答えない。"},{w:null,t:"エリー、ぽかんとして、それから、にこっとする。"},{w:"elly",t:"ないしょね！"},{w:null,t:"研究者、少しだけ笑う。"},{w:null,t:"アレク、何も言わない。"},{w:null,t:"ヤマト、シャツの外、胸の上に革ひもでさげた古い時計を、手のひらでおさえる。"}];
GR_SC.g08_07=[{w:null,t:"たき火は、もう、おき火。"},{w:null,t:"遠くから、低いエンジンの音。"},{w:null,t:"フォルンの耳が、ぴくっと立つ。"},{w:null,t:"ヤマトも、目をあける。"},{w:null,t:"発掘場の前の土の道を、白いトラックが一台、明かりを消して走ってくる。"},{w:null,t:"トラックが、目の前を通る。"},{w:null,t:"荷台の中から、鳴き声。"},{w:null,t:"トラックは、森の奥の方へ曲がっていく。"},{w:null,t:"ヤマト、体を起こす。"},{w:null,t:"エリー、毛布の中で、目をあけている。"},{w:null,t:"小屋の軒下。"}];
GR_EP[8]={"t": "巨人の骨", "sc": [["g08_01", "発掘場（夜明け前）", 0], ["g08_02", "発掘場の小屋（朝）", 0], ["g08_03", "発掘場（昼前）", 0], ["g08_04", "骨の小屋（昼）", 0], ["g08_05", "発掘場のたき火（夜）", 0], ["g08_06", "たき火のそば（夜ふけ）", 0], ["g08_07", "発掘場の前の道（夜中）", 0]]};
GR_SC.g09_01=[{w:null,t:"森の外れの、化石の発掘場。ゆうべ、窓のない白いトラックが一台、この前の道を森の奥へ走っていった。"},{w:null,t:"朝もやの中、掘りかけの四角い穴がいくつも並ぶ。"},{w:null,t:"小屋の軒下の壁ぎわ。"},{w:null,t:"小屋の前の道。"},{w:null,t:"エリー、しゃがんで羽を拾う。"},{w:null,t:"ヤマト、わだちの前に仁王立ち。"},{w:"hero",f:"smile",t:"よし。こういうのは、おれにまかせろ。タイヤのあと、追うだけだろ。"},{w:null,t:"ヤマト、地面に顔を近づけて、細いわだちを一本見つける。"},{w:null,t:"細いわだちは、穴と穴のあいだをくねくね回って、小屋の裏へ。"},{w:"kenkyu",t:"それ、わたしの一輪車。"},{w:null,t:"ヤマト、手押し車を見る。"},{w:null,t:"小屋の表から、アレクの声。"},{w:"alek",t:"……こっちだ。"},{w:"alek",t:"荷台が重い。檻を積んでる。"},{w:"kenkyu",t:"その道、地図にないよ。行くなら、帰りに一輪車を押してって。"},{w:"alek",t:"……帰りは、ここは通らない。"},{w:"alek",t:"……この道、前に一度、通った。"},{w:null,t:"第9話　森の奥の施設"}];
GR_SC.g09_02=[{w:null,t:"森の奥へ続く、地図にない道。上の空を、配達のドローンが行きかう。下の道は、わだちのほかに、何もない。"},{w:null,t:"先頭はアレク。"},{w:"hero",t:"アレク。前の仕事って、何。"},{w:"alek",t:"荷物の案内だ。白い盾の会社の。"},{w:"hero",t:"荷物って。"},{w:"alek",t:"檻だ。"},{w:null,t:"ヤマト、それ以上聞かない。"},{w:null,t:"エリーは、さっきの羽を、クッキーの箱のふたのすきまに、そっとさしこんでいる。"},{w:"elly",t:"ねえ、アレク。あの子たち、また森に帰れる？"},{w:"alek",t:"……今から見る。"},{w:null,t:"道のわきに、新しい看板。"},{w:null,t:"フォルンが、看板の前で足を止める。"},{w:null,t:"ヤマト、フォルンの横にしゃがむ。"},{w:"hero",f:"serious",t:"……フォルン、ここ、来たこと、あんのか。"},{w:null,t:"フォルン、看板から目をはなさない。"},{w:"alek",t:"来る前に、逃げたやつだ。そいつは。"},{w:null,t:"道の先の木の上に、白いカメラが一つ。"},{w:null,t:"ヤマト、自分のパーカーのフードを、フォルンの頭の上に、ばさっとかぶせる。"}];
GR_SC.g09_03=[{w:null,t:"アイギス社、森の保護センター。窓のない、白い四角い建物だ。"},{w:null,t:"森を切りひらいた広場に、白い建物。"},{w:null,t:"前の広場に、白いトラックが三台、横に並んでいる。"},{w:null,t:"門の横の小さな見張り小屋に、人が一人。"},{w:null,t:"三人と三体は、広場のはしの茂みにしゃがんでいる。"},{w:"hero",t:"人、一人しかいねえじゃん。"},{w:"alek",t:"ほかは全部、機械だ。"},{w:"hero",t:"じゃあ、正面から行けば。"},{w:"alek",t:"門に、目がある。"},{w:null,t:"門の柱の上に、白いカメラ。"},{w:null,t:"アレク、茂みの中を、建物の裏へ回っていく。"}];
GR_SC.g09_04=[{w:null,t:"アレク、ポケットから、すりへった白いカードを出す。"},{w:null,t:"アレク、カードを見る。"},{w:"hero",f:"serious",t:"……追い出されてんじゃん。"},{w:"alek",t:"自分で出たんだ。"},{w:null,t:"ぶうん、と音がして、灰色の戸が内側から開く。"},{w:null,t:"三人、ゴミの箱のかげに固まる。"},{w:null,t:"エリーだけ、かげから出る。"},{w:"hero",t:"（小声で）おい！"},{w:null,t:"エリー、にこっと笑って、ロボットに頭を下げる。"},{w:"elly",t:"おはよう。おつかれさま。毎日、たいへんだね。"},{w:"x",n:"掃除のロボット",t:"ドウゾ。"},{w:"hero",t:"ごくろう！"}];
GR_SC.g09_05=[{w:null,t:"建物の二階を、ガラス張りの通路が一本、まっすぐ通っている。下を見下ろせるように作ってある。"},{w:null,t:"三人、ガラスにくっつくようにして、下を見る。"},{w:null,t:"下は、長い長い流れ作業の部屋。"},{w:null,t:"檻が止まる。"},{w:null,t:"じたばたしていた羽の子の足が、止まる。"},{w:null,t:"エリーの両手が、ガラスに当たっている。"},{w:null,t:"フォルンの背中の毛が、しっぽの付け根から、ぞわっと逆立つ。"},{w:null,t:"ヤマト、フォルンの背中に、手のひらを置く。"},{w:"hero",f:"serious",t:"……あれ、チップ？"},{w:"alek",t:"安全チップ。入れると、命令が届く。"},{w:"x",n:"係の男の声",t:"主任。歌の子、四十二体です。きょう中に全部入れますか。"},{w:"x",n:"ノモスの声",t:"……確認します。"},{w:"x",n:"ノモスの声",t:"上に聞かないと、決められない。"},{w:"x",n:"係の男の声",t:"……はい。"}];
GR_SC.g09_06=[{w:null,t:"通路のつきあたり。"},{w:null,t:"アレク、板の前で止まる。"},{w:null,t:"うしろから、ころころ、と音。"},{w:"elly",t:"あ。さっきの子。"},{w:null,t:"ロボットが戸の前に来ると、ぴっ、と小さな音。"},{w:null,t:"アレク、エリーを見る。"},{w:null,t:"三人、戸をくぐる。"},{w:null,t:"掃除のロボットは、裂け目の前の床を、くり返しくり返しふいている。"},{w:"alek",t:"「試験七号。化石の骨から、小さく印刷した子。命令を入れた瞬間に、暴走。……試験は中止」。"},{w:"hero",f:"serious",t:"……化石の子って。"},{w:"hero",t:"言うこと、聞かなかったんだろ。"},{w:"elly",t:"（画面を指でなぞって）オリーヴァ、二つもある。"},{w:"elly",t:"「角のある子の家。」……競技場の扉と、ちょっと似てるね。"},{w:"alek",t:"……出るぞ。"}];
GR_SC.g09_07=[{w:null,t:"細い廊下を、三人が早足で行く。"},{w:null,t:"エリーが、一つの窓の前で、止まる。"},{w:null,t:"エリーは、笑っている。"},{w:null,t:"うしろから来たヤマトが、エリーの背中にぶつかる。"},{w:"hero",t:"おい、何——"},{w:null,t:"ヤマト、エリーの横顔を見る。"},{w:null,t:"エリーの腕の中で、クッキーの箱のふたが、内側から持ち上がる。"},{w:null,t:"エリーの足が、動く。"},{w:null,t:"ヤマト、窓の外の白い車を、もう一度だけ見る。"}];
GR_SC.g09_08=[{w:null,t:"天井の高い倉庫。"},{w:null,t:"倉庫の向こうに、大きな搬出の戸。"},{w:null,t:"エリーが、いちばん手前の檻の前にしゃがむ。"},{w:null,t:"エリー、ふたのすきまから羽を出して、柵のすきまから中へ入れる。"},{w:"elly",t:"アレク。"},{w:"alek",t:"だめだ。一つ開けたら、全部鳴る。"},{w:"elly",t:"じゃあ、全部開けよう。"},{w:null,t:"アレク、エリーを見る。"},{w:"hero",t:"（もう檻の留め金をさわりながら）これ、どうやって開けんの。"},{w:"alek",t:"さわるな。"},{w:null,t:"アレク、倉庫の柱を見回す。"},{w:"x",n:"係の男",t:"主任！　檻が……全部！"}];
GR_SC.g09_09=[{w:null,t:"施設の白い屋根から、ドローンが四機、飛び立った。"},{w:null,t:"森が深くなる。"},{w:null,t:"森の中を、三人と三体が走る。"},{w:null,t:"ドローンは、葉の屋根の上を飛んでいる。"},{w:"alek",t:"足あとを、読んでる。この泥じゃ、消せない。"},{w:null,t:"道が、平らな岩場を横切る。"},{w:null,t:"岩場の向こうは、また泥。"},{w:null,t:"ヤマト、くるっと回る。"},{w:"alek",t:"……何してる。"},{w:"hero",t:"足あと、逆。"},{w:"elly",t:"牛どろぼうの、赤ちゃん！"},{w:"hero",t:"ほらな。こういうのは、おれにまかせろって。"}];
GR_SC.g09_10=[{w:null,t:"森がとぎれて、乾いた丘。"},{w:null,t:"ずぶぬれのヤマトが、パーカーをしぼっている。"},{w:null,t:"アレク、岩の上に紙の地図を広げる。"},{w:null,t:"アレク、白い都の点から、港の方へ、指をすべらせる。"},{w:"alek",t:"白い都は、湾のむこう側だ。陸をぐるっと回ったら、大会に間に合わない。"},{w:"hero",t:"じゃあ、タクシー。"},{w:"alek",t:"乗った瞬間、居場所が会社に行く。"},{w:"elly",t:"じゃあ、船！"},{w:"alek",t:"人が動かしてる船なら、名簿がない。"},{w:"elly",t:"海の船、初めて！"},{w:"hero",t:"船なら、まかせろ。"},{w:null,t:"エリー、クッキーの箱を開ける。"},{w:null,t:"エリー、そのしっぽを、指でちょんとさわる。"},{w:null,t:"エリー、すぐ顔を上げる。"},{w:"elly",t:"行こ。港。"},{w:null,t:"フォルン、もう丘を下りはじめている。"}];
GR_SC.g09_11=[{w:null,t:"明るい部屋。"},{w:null,t:"大きな画面に、森の保護センターの試験室の映像。"},{w:null,t:"画面のはしに、小さな窓。"},{w:null,t:"机の上の通信機から、男の声。"},{w:"x",n:"通信機の声",t:"森のセンターからです。扉の文字が、読まれました。子どもです。"},{w:null,t:"赤い爪の指が、声の記録を、もう一度流す。"},{w:"x",n:"エリーの声（記録）",t:"「角のある子の家。」"},{w:null,t:"赤い爪の指が、画面のエリーの顔に、とん、と止まる。"},{w:"x",n:"女の声",t:"……この子ね。字が読める子。"},{w:null,t:"赤い爪の手が、ケーキにフォークを入れる。"}];
GR_EP[9]={"t": "森の奥の施設", "sc": [["g09_01", "アルカディアの森の外れ・発掘場（夜明け）", 0], ["g09_02", "森の道（朝）", 0], ["g09_03", "森の奥・施設の前（朝）", 0], ["g09_04", "施設の裏口", 0], ["g09_05", "施設の中・見学の通路", 0], ["g09_06", "試験室", 0], ["g09_07", "施設の中・窓のある廊下", 0], ["g09_08", "施設の中・檻の部屋", 0], ["g09_09", "森の中（昼）", 0], ["g09_10", "森の出口（夕方）", 0], ["g09_11", "どこかの部屋（夜）", 0]]};
GR_SC.g10_01=[{w:null,t:"港町ナフリア。白い都へ渡る船は、ここから出る。"},{w:null,t:"湾の向こうの長い防波堤の上を、大きな影がゆっくり歩いている。"},{w:null,t:"岸の、網をほす木の台の上に、ヤマト。"},{w:"x",n:"港の子1",t:"あ、タロスだ。"},{w:"x",n:"港の子2",t:"百年、ずっと回ってるんだって。"},{w:"x",n:"港の子3",t:"昔の島の、青銅の巨人の名前。うちのじいちゃんがつけたの。"},{w:"hero",t:"でけえ。……あれ、戦えんの。"},{w:"x",n:"港の子1",t:"戦わないよ。歩くだけ。"},{w:null,t:"子どもたちの目が、台の下へ下りる。"},{w:"x",n:"港の子2",t:"その狐、お兄ちゃんの？"},{w:"hero",t:"おれの。"},{w:"x",n:"港の子2",t:"うそだあ。日本の子って、テリオン持っちゃだめなんでしょ。学校で習ったもん。日本だけ、地図が白いの。"},{w:null,t:"ヤマト、台の上で、一瞬だけ止まる。"},{w:"x",n:"港の子3",t:"じゃあ、その狐、だれの？"},{w:null,t:"子どもたちの目が、フォルンの耳のうしろへ行く。"},{w:"hero",f:"serious",t:"……おれの。"},{w:null,t:"子どもたちは、まだ耳のうしろを見ている。"},{w:null,t:"台の下で、フォルンがあくびをする。"},{w:null,t:"防波堤の上で、大きな影が、また一歩。"},{w:null,t:"第10話　港町ナフリア"}];
GR_SC.g10_02=[{w:null,t:"連絡船の切符の画面の前。"},{w:"hero",t:"いくら。"},{w:"alek",t:"三人で、宿の十二日分。"},{w:"hero",t:"じゃあ、歩く。"},{w:"alek",t:"湾を回ったら山が二つだ。大会の受付に間に合わない。"},{w:"hero",t:"じゃあ、泳ぐ。"},{w:"alek",t:"……クロッコに引っぱらせる気か。"},{w:null,t:"アレクの足もとで、クロッコが顔を上げる。"},{w:null,t:"エリーは、となりのくじの屋台の前にしゃがんでいる。"},{w:null,t:"広場の奥の桟橋に、白と青の少し古い連絡船。"},{w:"marina",t:"次はだれだい！　勝てば、向こう岸まで、ただ！"},{w:null,t:"甲板の手すりに、日焼けした女の人が足をかけている。"},{w:null,t:"船の横の海で、青いクジラが頭から潮をふいて、甲板を洗っている。"},{w:null,t:"潮のしぶきが風に乗って、広場まで飛んでくる。"},{w:null,t:"箱のふたが、ぽんと開く。"},{w:null,t:"クジラが、きゅうっと鳴いて、桟橋の下へもぐる。"},{w:"elly",f:"sad",t:"ごめんね。この子、水がかかると、びっくりするの。"},{w:"marina",t:"あたしの子もだよ。電気がかかると、びっくりする。"},{w:"alek",t:"……その船、人が動かしてるのか。"},{w:"marina",t:"あたしが動かしてる。機械の舵は外しちまった。名簿もとらない。文句あるかい。"},{w:"alek",t:"ない。"},{w:null,t:"ヤマト、もう桟橋の根もとまで走っている。"},{w:"hero",t:"やる！"},{w:"marina",t:"船長のマリナ。負けたら、船代はちゃんともらうよ。"},{w:null,t:"エリー、走ってきて、箱のふたを開ける。"},{w:"elly",t:"ピリポンも出る？"},{w:null,t:"ヤマト、広場のはしを見る。"},{w:"x",n:"港の子3",t:"その狐、お兄ちゃんの言うこと、聞くの？"},{w:null,t:"杭の下で、フォルンがそっぽを向いて、耳をかいている。"},{w:"hero",t:"いい。おれ一人でいい。"},{w:"alek",t:"向こうは、海の上だぞ。"},{w:"hero",t:"桟橋の上でやればいいだろ。"},{w:"alek",t:"向こうは、桟橋に上がってこない。"},{w:"hero",t:"じゃあ、上がってくるまで待つ。"},{w:"alek",t:"その前に、船が出る。"},{w:null,t:"ヤマト、もう聞いていない。"},{w:null,t:"アレクの足もとから、クロッコが、どぼんと海へ飛びこむ。"},{w:"alek",t:"おい。"},{w:null,t:"陸ではのそのそ歩くクロッコが、水の中では、すうっと速い。"},{w:null,t:"桟橋の横の海に、古い木の杭が一並び、頭を出している。"},{w:null,t:"港の口から、大きな波が一つ、入ってくる。"},{w:null,t:"クロッコ、とっさに杭にかみつく。"},{w:null,t:"アレク、桟橋のふちで、それをじっと見ている。"},{w:null,t:"くつは、流れていく。"},{w:null,t:"クジラが潮をふく。"},{w:null,t:"網の子が、網で受ける。"}];
GR_SC.g10_03=[{w:null,t:"マリナ、甲板から船の横の海を指さす。"},{w:null,t:"港の口の深い海。"},{w:null,t:"クジラ、沖の海で止まって、こちらを向く。"},{w:"marina",t:"この子が、うちのかしら。こいつが沈んだら、あんたの勝ち。"},{w:null,t:"ヤマト、片足だけはだしで、フォルンを桟橋の根もとに出す。"},{w:null,t:"フォルンの体から、火の粉がふわっとあふれる。"},{w:"x",n:"港の子1",t:"……でっか。"},{w:null,t:"ヤマト、子どもたちをふり返って、胸をはる。"},{w:null,t:"桟橋の根もとに、エリーとアレク。"},{w:"marina",t:"始めるよ。"}];
GR_SC.g10_05=[{w:null,t:"マリナ、手すりから海へ飛びこむ。"},{w:null,t:"アレク、桟橋のふちにしゃがんで、手をのばす。"},{w:null,t:"アレク、パーカーのそでで、クロッコの鼻先の海水をふく。"},{w:null,t:"マリナ、船に上がってくる。"},{w:"marina",t:"勝ったのは、ワニだ。ワニの持ち主と、その連れは、ただ。あしたの昼の便。"},{w:null,t:"マリナ、切符を三枚、アレクに差し出す。"},{w:"marina",t:"狐は、負けた方だね。乗せるなら、狐の分は払ってもらう。"},{w:null,t:"マリナ、船の中へ入っていく。"},{w:null,t:"広場のはしには、だれもいない。"},{w:null,t:"ヤマト、桟橋の先まで、ゆっくり歩く。"},{w:"hero",t:"……なんで、跳ばないんだよ。杭、すぐそこだっただろ。"},{w:"hero",t:"おまえがちゃんとやってたら、勝ってた。"},{w:"elly",t:"ヤマト。"},{w:"hero",f:"serious",t:"……待て。"},{w:"elly",t:"フォルン！"},{w:"hero",f:"serious",t:"……いいよ。腹へったら、戻ってくる。"}];
GR_SC.g10_06=[{w:null,t:"せまい路地の宿。"},{w:null,t:"せまい部屋に、ベッドが三つ。"},{w:null,t:"アレクは、机の上に残った硬貨を並べている。"},{w:null,t:"エリーは、窓ぎわで、空のオリーブの紙袋を、たたんでは広げている。"},{w:null,t:"ヤマトは、ベッドで壁の方を向いて、寝ころんでいる。"},{w:null,t:"窓の外で、雨が降りだす。"},{w:null,t:"通りを、白い車がゆっくり走っていく。"},{w:null,t:"エリーの手が止まる。"},{w:null,t:"アレク、硬貨を財布にもどす。"},{w:null,t:"ヤマトの背中は、動かない。"}];
GR_SC.g10_07=[{w:"elly",t:"フォルン。……フォルーン。"},{w:null,t:"うしろを、アレクが、かさもささずに歩いている。"},{w:null,t:"人のいない桟橋。"},{w:null,t:"エリー、かさをアレクの方へ半分かたむける。"}];
GR_SC.g10_08=[{w:null,t:"ぬれた二人がもどってくる。"},{w:"alek",t:"……回収の車、出てる。"},{w:null,t:"ヤマトの背中が、少しだけ固くなる。"},{w:null,t:"明かりが消える。"},{w:null,t:"ヤマトが、目を開けている。"},{w:null,t:"壁に、指で線を引く。"},{w:null,t:"指が、桟橋の丸から左のはしの丸へ、何度も行ったり来たりする。"},{w:null,t:"指が止まる。"},{w:null,t:"指が、桟橋の右へ、ゆっくり動く。"},{w:null,t:"昼間、フォルンが一度だけ首を向けた所。"},{w:null,t:"指が、そこから動かない。"},{w:null,t:"ヤマト、手を引っこめる。"},{w:null,t:"毛布のすきまから、ヤマトの目が、カーテンのすきまを見る。"}];
GR_SC.g10_09=[{w:"x",n:"案内の声",t:"お知らせです。港の見張りロボットは、あしたの正午に止めます。歩いたままでは近づけないため、足を切ります。百年間の長いお勤め、ありがとうございました。"},{w:null,t:"防波堤の上を、大きな影がゆっくり歩いてくる。"},{w:null,t:"左のくるぶしに、太い古い鉄の栓。"},{w:null,t:"大きな足が、上がって、下りる。"},{w:null,t:"雨が、その火をかくす。"},{w:null,t:"ロボットは、止まらずに、雨の中を回っていく。"}];
GR_EP[10]={"t": "港町ナフリア", "sc": [["g10_01", "ナフリアの港（朝）", 0], ["g10_02", "港の広場", 0], ["g10_03", "向かい合う", 0], ["g10_04", "勝負", 1], ["g10_05", "勝負のあと", 0], ["g10_06", "港の裏の安い宿（夜）", 0], ["g10_07", "港の路地（夜・雨）", 0], ["g10_08", "宿（夜ふけ）", 0], ["g10_09", "港のはし（夜・雨）", 0]]};
GR_SC.g11_01=[{w:null,t:"雨は、夜どおしやまなかった。"},{w:null,t:"まだ暗い部屋。"},{w:null,t:"ヤマトが、そっとベッドから起きる。"},{w:null,t:"アレクは、壁を向いて寝ている。"},{w:null,t:"ヤマトがドアノブに手をかけた時、うしろから小さな銀色の物が飛んでくる。"},{w:null,t:"ヤマト、ふり向く。"},{w:null,t:"机の上に、きのうは三枚だった硬貨が、二枚。"},{w:null,t:"ヤマト、硬貨を拾う。"},{w:null,t:"となりのベッドで、エリーが目を開ける。"},{w:null,t:"第11話　雨上がり"}];
GR_SC.g11_02=[{w:null,t:"港の朝市は、雨でも開く。"},{w:null,t:"雨よけの布の下。"},{w:null,t:"ヤマト、硬貨を台に置いて、たるを指さす。"},{w:null,t:"ヤマト、包みをポケットに押しこむ。"},{w:null,t:"うしろから、エリーがかさを開いて、ヤマトの頭の上にさしかける。"}];
GR_SC.g11_03=[{w:null,t:"雨の防波堤。"},{w:null,t:"防波堤の根もとに、白い回収車。"},{w:null,t:"エリー、ヤマトに追いついて、見上げる。"},{w:null,t:"大きな足が下りるたび、少しだけ横をずれて下りる。"},{w:null,t:"回収のレンズが、防波堤の上をなめていく。"},{w:null,t:"ヤマト、道のまん中で立ち止まる。"},{w:null,t:"フォルンも、止まる。"},{w:null,t:"ロボットは、二人のあいだを、ずしん、と通りすぎていく。"},{w:null,t:"ヤマト、右手を上げかける。"},{w:null,t:"指が、止まる。"},{w:null,t:"ヤマト、手を下ろす。"},{w:null,t:"水たまりに、大きな足あとと、小さな四つ足のあとが、港のはしまで、ずっと並んでいる。"},{w:null,t:"ヤマト、包みからオリーブを一つ出す。"},{w:null,t:"フォルン、オリーブを見る。"},{w:null,t:"ヤマトの手も、動かない。"},{w:null,t:"うしろで、ロボットが一回りして、また近づいてくる。"},{w:null,t:"フォルン、首をのばす。"},{w:null,t:"フォルン、オリーブをしっぽの火の上に落とす。"},{w:null,t:"うしろで、エリーが、かさを二本持ったまま立っている。"},{w:null,t:"ヤマトの顔が、ゆっくりゆるむ。"},{w:"hero",t:"（エリーに）ほらな。腹へったら、戻ってくるって。"},{w:"elly",t:"ヤマト、ゆうべ、ごはん、残してた。"},{w:"hero",t:"残してない。"},{w:"elly",t:"三口。"},{w:"hero",f:"serious",t:"……二口。"},{w:null,t:"エリー、かさを開いて、くるくる回しながら、そっぽを向く。"},{w:null,t:"ヤマト、フォルンの頭を、わしわしとなでる。"},{w:null,t:"ヤマトの手が止まった時には、フォルン、二つ目のオリーブを、勝手にヤマトのポケットから出して焼いている。"}];
GR_SC.g11_04=[{w:null,t:"ロボットが、港を一回りして、またこっちへ来る。"},{w:null,t:"防波堤の、古い石の段の前。"},{w:null,t:"ロボット、また歩きだす。"},{w:null,t:"次の一回り。"},{w:null,t:"エリー、段の横の壁に近づく。"},{w:null,t:"段の上に、さびた油さしが三つ、並んだまま。"},{w:"elly",t:"ヤマト。これ、あの子だよ。"},{w:null,t:"ヤマト、タイルの絵を見る。"},{w:null,t:"空が、低く光る。"},{w:null,t:"エリーのカバンの中で、クッキーの箱のふたが、ぽんとはね上がる。"},{w:"elly",t:"だいじょうぶ、だいじょうぶ。雷さん、遠いよ。"},{w:null,t:"エリー、首のピリポンをなでる。"}];
GR_SC.g11_05=[{w:null,t:"防波堤の根もとに、黄色い解体の機械が集まってくる。"},{w:null,t:"作業員たちが、ロボットの通り道に柵を立てていく。"},{w:"x",n:"案内の声",t:"正午から、足の切断を始めます。近づかないでください。"},{w:null,t:"かさをさして、マリナが歩いてくる。"},{w:null,t:"アレクも来ている。"},{w:"marina",t:"あたしが子どもの時は、あの段の前で、じいさんたちが毎朝、油をさしてた。栓を抜くと、あいつ、海の方を向いて座って、待ってたっけ。"},{w:"alek",t:"……今は。"},{w:"marina",t:"じいさんたちが、いなくなった。機械の点検は、機械がやる。あいつは、点検の表に入ってない。"},{w:null,t:"黄色い機械の切断の腕が、ためしに一回うなる。"},{w:null,t:"ロボットが、また段の前で止まる。"},{w:"x",n:"作業員",t:"おい、子ども！"},{w:"marina",t:"ちょっと！"}];
GR_SC.g11_06=[{w:null,t:"ロボットは、倒れない。"},{w:null,t:"ゆっくり、歩きだす。"},{w:null,t:"朝市の前を通る。"},{w:null,t:"連絡船の前を通る。"},{w:null,t:"解体の機械の前を通る。"},{w:null,t:"防波堤のいちばん先。"},{w:null,t:"ゆっくり、ひざを折る。"},{w:null,t:"片目の光が、ゆっくり暗くなって、消える。"},{w:null,t:"作業員の手首の画面に、字。"},{w:null,t:"黄色い機械のエンジンが、一台ずつ止まる。"}];
GR_SC.g11_07=[{w:null,t:"ぬれた桟橋が、日の光で光っている。"},{w:null,t:"船を待つ人たち。"},{w:null,t:"いちばんうしろの方に、三人。"},{w:null,t:"桟橋の屋台。"},{w:null,t:"アレク、財布の中を見る。"},{w:"alek",t:"……狐の分が、ない。"},{w:"hero",t:"リュックに入れりゃいいだろ。"},{w:null,t:"ヤマト、リュックの口を開ける。"},{w:null,t:"ヤマト、リュックを背負う。"},{w:null,t:"リュックの口から、しっぽの火の先だけ、ぴょこんと出ている。"},{w:null,t:"ヤマト、あわてて口を広げる。"},{w:"elly",t:"ピリポンの箱、貸してあげる。"},{w:null,t:"エリー、クッキーの箱のふたを開ける。"},{w:null,t:"フォルン、空いた箱に、するっと入る。"},{w:null,t:"レンズが、三人の足もとをなめる。"},{w:null,t:"箱のすきまから、うすいけむり。"},{w:null,t:"船の手すりの上から、紙が一枚、ひらひら落ちてくる。"},{w:null,t:"手書きの切符。"},{w:null,t:"ヤマト、上を見る。"},{w:null,t:"船に上がったところで、箱のふたが、ぱかっと開く。"}];
GR_SC.g11_08=[{w:null,t:"向こう岸まで、船で半日。"},{w:null,t:"連絡船が、港を出ていく。"},{w:null,t:"防波堤のいちばん先に、座ったままのロボット。"},{w:null,t:"足もとの段で、魚屋のおばさんが、さびた油さしを一つ、くるぶしの横に置く。"},{w:null,t:"エリー、手すりから、両手で大きく手をふる。"},{w:null,t:"ヤマト、手すりにひじをついて、胸をそらしている。"},{w:"hero",t:"船、楽勝。おれ、ゆれるの強いから。"},{w:"alek",t:"まだ港の中だ。"},{w:"hero",t:"港の外でも強いって。"},{w:null,t:"船が、防波堤の外へ出る。"},{w:null,t:"ヤマト、ひじをついたまま、だまる。"},{w:null,t:"船が、上がる。"},{w:null,t:"となりの手すりの上で、フォルンが、ヤマトのポケットから持ってきた最後のオリーブを、しっぽの火で焼きはじめる。"},{w:null,t:"ヤマト、においから顔をそむける。"},{w:"elly",t:"強いんだよね。"},{w:"hero",f:"serious",t:"……強い。"},{w:"elly",t:"お月さま？　昼なのに。"},{w:"alek",t:"昼も出てる。"},{w:"elly",t:"ふうん。何、見てるの。"},{w:"alek",t:"……かげ。山のかげ。"}];
GR_SC.g11_09=[{w:null,t:"向こう岸の船着き場。"},{w:null,t:"ヤマトが、桟橋の板の上に、大の字になっている。"},{w:"marina",t:"（船の上から、三人の方を見ずに）次は、船代ちゃんと払える日に来な。"},{w:"elly",t:"ありがとう、マリナさん！"},{w:null,t:"マリナ、背中を向けたまま、片手だけ上げる。"},{w:null,t:"道の入口に、古い柵。"},{w:null,t:"看板の上に、新しいシールが一枚、まっすぐに貼ってある。"},{w:null,t:"アレクの足が、止まる。"},{w:null,t:"うしろで、船が汽笛を鳴らして、岸をはなれていく。"},{w:null,t:"桟橋の上で、ヤマトがまだ大の字のまま、汽笛の方へ首だけ向ける。"}];
GR_EP[11]={"t": "雨上がり", "sc": [["g11_01", "港の裏の宿（夜明け前・雨）", 0], ["g11_02", "朝市（夜明け・雨）", 0], ["g11_03", "防波堤の道（朝・雨）", 0], ["g11_04", "防波堤・古い石の段（朝・雨）", 0], ["g11_05", "防波堤（昼前・雨）", 0], ["g11_06", "港（正午・雨がやんでいく）", 0], ["g11_07", "連絡船の桟橋（昼）", 0], ["g11_08", "連絡船の上（午後）", 0], ["g11_09", "向こう岸（夕方）", 0]]};
GR_SC.g12_01=[{w:null,t:"獅子門の丘の見学の門。"},{w:null,t:"明るい部屋。"},{w:null,t:"壁の画面に、止めた映像。"},{w:null,t:"となりの小さな窓に、文字が流れている。"},{w:null,t:"赤い爪の指が、「該当なし」を、とん、とたたく。"},{w:null,t:"画面のすみで、ぽん。"},{w:null,t:"赤い爪の手が、ケーキにフォークを入れる。"},{w:null,t:"女の手が、白い日傘を取る。"},{w:null,t:"第12話　獅子門の丘"}];
GR_SC.g12_02=[{w:null,t:"獅子門の丘。三千年前の王の城あとだ。今は、アイギス社が管理している。"},{w:null,t:"船着き場の、屋根だけの待合。"},{w:null,t:"船着き場からの道は、丘の上で行き止まり。"},{w:null,t:"アレク、紙の地図を広げる。"},{w:"alek",t:"……北へ抜ける道は、あの門の中だけだ。"},{w:"hero",t:"ご自由に、だって。ただで、名簿もなし。"},{w:"alek",t:"ただ、ってのが気にいらない。"},{w:"hero",t:"なんで。"},{w:"alek",t:"向こうが、何かほしいからだ。"},{w:null,t:"ヤマト、もう門をくぐっている。"},{w:"hero",t:"ほしいのは、こっちの見学だろ。"},{w:null,t:"エリー、看板に、ぺこりと頭を下げてから、くぐる。"},{w:null,t:"アレク、門の柱を見上げる。"},{w:null,t:"アレク、クロッコの背中を軽くたたく。"}];
GR_SC.g12_03=[{w:null,t:"見学の客が、二十人ほど。"},{w:"x",n:"案内のロボット",t:"ようこそ、獅子門の丘へ！　本日のお客さまは、二十一名さまと、テリオン三体さまです！"},{w:null,t:"客の足もとに、小さな丸い耳の子を抱いた女の子。"},{w:null,t:"ロボットの顔の光が、足もとを一つずつなめていく。"},{w:null,t:"フォルンで、ぴっ。"},{w:"x",n:"案内のロボット",t:"お知らせでーす！　登録の確認できない狐さまを、お連れのお客さまがいらっしゃいまーす！　あとで受付まで、おこしくださーい！"},{w:null,t:"客が、いっせいにふり向く。"},{w:null,t:"ヤマト、とっさにフォルンをだき上げて、パーカーのおなかに押しこむ。"},{w:null,t:"パーカーのおなかが、もこもこ動く。"},{w:null,t:"客たちが、手首の画面をかざして写真をとる。"},{w:null,t:"ヤマト、客に小さく会釈する。"},{w:null,t:"エリーは、ロボットの旗に、両手で手をふっている。"},{w:"x",n:"案内のロボット",t:"この町を作った英雄は、見た者を石にしてしまう、おそろしい怪物をたおしました！　怪物の目を見ないように、ぴかぴかにみがいた盾に映して、うしろ向きに近づいたのです！"},{w:null,t:"女の子が、腕の丸い耳の子の目を、手でかくす。"},{w:"x",n:"案内のロボット",t:"たおした怪物の顔は、知恵の女神の盾に、かざられました！　その盾の名前は——アイギス！　わが社の名前は、ここからいただきました！"},{w:null,t:"ロボットが、自分の胸の印を、旗の先でこんこんとたたく。"},{w:null,t:"ヤマト、ロボットの胸の印を見る。"},{w:"hero",t:"……あの会社のマーク、怪物の顔がついた盾かよ。なんで、そんなのマークにすんだよ。"},{w:null,t:"アレク、答えない。"},{w:null,t:"エリーは、坂のわきの小さな黄色い花をつんでいる。"}];
GR_SC.g12_04=[{w:null,t:"大きな石の門。"},{w:"x",n:"老人",t:"（となりのアレクに）頭は、どうしたんだね。"},{w:"alek",t:"……別の石で作って、はめてあった。だれかが持っていった。"},{w:null,t:"老人、うなずいて、アレクの手に硬貨を一枚にぎらせる。"},{w:null,t:"ヤマト、門の下で、獅子の渦巻く毛を見上げている。"},{w:null,t:"エリー、門のわきの石の古い文字に、顔を近づける。"},{w:"elly",t:"「この門をくぐる者は、獅子の見る前で、手を洗え」だって。"},{w:null,t:"エリー、自分の手のひらを見る。"},{w:null,t:"客のうしろから、ぱちぱちぱち、と小さな拍手。"},{w:"bella",t:"すごい。今の、古いギリシャ語でしょう？　声に出して読める子、初めて見たわ。"},{w:null,t:"白い日傘の、若い女の人。"},{w:null,t:"アレクの肩が、ぴくりと固くなる。"},{w:"bella",t:"アイギス社のベラドンナ。ここの持ち主、ってことになってるの。"},{w:"elly",t:"社長さん？　すごい！"},{w:"bella",t:"すごいのは、あなたよ。こんなにすらすら読む子、うちの学者にもいないの。"},{w:"elly",t:"ほんと？　おばあちゃんにしか、ほめられたことない。"},{w:"bella",t:"じゃあ、二人目ね。お名前は？"},{w:"elly",t:"エリー！　オリーヴァ村の。おばあちゃん、昔、研究所にいたんだよ。"},{w:null,t:"アレクの指が、エリーのそでをつまむ。"},{w:"bella",t:"よかったら、お茶でもどう？　ケーキがあるの。三人と、その子たちの分も。"},{w:"elly",t:"ケーキ！"},{w:"alek",t:"……先を急ぐ。"},{w:"bella",t:"ご心配なく。今日は、見に来ただけ。"},{w:null,t:"ベラドンナ、うしろの見回りの二人を、ふり返りもせずに、手のひらで止める。"},{w:null,t:"エリー、アレクの指から、そでをするりと抜く。"},{w:null,t:"ヤマトとアレク、顔を見合わせる。"},{w:"hero",f:"serious",t:"……ケーキって、言ったよな。"},{w:"alek",t:"言った。"},{w:null,t:"二人、歩きだす。"}];
GR_SC.g12_05=[{w:null,t:"丘のてっぺんの、ガラスの建物。三千年前の城あとを、見下ろす部屋だ。"},{w:null,t:"白い、広い部屋。"},{w:null,t:"白い机に、ケーキが並ぶ。"},{w:null,t:"エリーは、ベラドンナのとなりで足をぶらぶらさせている。"},{w:null,t:"ヤマトは、いすのはしに浅く座っている。"},{w:null,t:"アレクは、座らない。"},{w:null,t:"ベラドンナが、指を一つ鳴らす。"},{w:"x",n:"画面のベラドンナ",t:"——古代の力を、チップで。"},{w:null,t:"ヤマトの手のフォークが、皿に当たって、かちんと鳴る。"},{w:null,t:"アレクは、窓ガラスに映った画面の字を見ている。"},{w:null,t:"ベラドンナは、画面ではなく、三人の顔を見ている。"},{w:null,t:"ベラドンナ、もう一度、指を鳴らす。"},{w:"bella",t:"食べて食べて。"},{w:null,t:"ヤマト、ケーキを見る。"},{w:null,t:"フォークで、いちごのケーキをひと口。"},{w:null,t:"ヤマトの皿が、空になる。"},{w:"hero",f:"serious",t:"……焦げても、うまい。"},{w:"bella",t:"その狐ちゃん、登録がないんですってね。うちの施設なら、きょうにでも登録できるわよ。チップを一つ入れるだけ。痛くないの。"},{w:"hero",f:"serious",t:"……いい。自分でやる。"},{w:"bella",t:"そう。十五歳まで、待つの？"},{w:"bella",t:"エリーちゃん。おばあさま、研究者だったのよね。何か、預かってない？　大事な物。"},{w:"elly",t:"大事な物？　うーん……"},{w:"elly",t:"ねえ、あの獅子の頭、どこ行ったんだろうね。しっぽは残ってるのに。ほら、くるんってなってる。"},{w:"bella",t:"……また今度、ゆっくりね。"},{w:"bella",t:"困ったら、いつでも。"},{w:"elly",t:"「アイギス社　社長　ベラドンナ」。……名刺！　初めてもらった。"}];
GR_SC.g12_06=[{w:null,t:"建物の裏の、北へ下りる石の道。"},{w:"x",n:"見回りの男",t:"どうぞ。社長から、お通ししろと。"},{w:null,t:"三人、門を出る。"},{w:null,t:"坂を少し下りた所で、アレクがふり返る。"},{w:"elly",t:"いい人だったね。ケーキ、おいしかった。"},{w:"hero",t:"うまかった。"},{w:null,t:"ヤマト、自分の手を見る。"},{w:"hero",f:"serious",t:"……アレク。あの画面の。古代って。"},{w:"alek",t:"聞こえた。"},{w:"hero",t:"チップって。"},{w:"alek",t:"聞こえた。"},{w:null,t:"アレク、それ以上言わない。"},{w:null,t:"エリー、二人の顔を見る。"},{w:null,t:"坂の下に、古い店が一軒。"},{w:"elly",t:"あ、電話。おばあちゃんに、名刺もらったって言わなきゃ。"},{w:null,t:"エリー、店に走っていく。"}];
GR_SC.g12_07=[{w:null,t:"丘の西の道。"},{w:null,t:"日傘をたたんで、ベラドンナがうしろの席に乗る。"},{w:null,t:"となりの席。"},{w:"x",n:"影の男",t:"鍵は。"},{w:"bella",t:"かわいい子でした。字は、うちのどの学者より読めます。おばあさまの物は、まだ。"},{w:null,t:"ベラドンナ、見回りへの指示を打つ。"},{w:null,t:"黒い手袋の手が、横からのびて、画面の上に、ふたをするようにのる。"},{w:null,t:"赤い爪の指が、止まる。"},{w:null,t:"手袋の指が、写真の女の子の顔を、一回だけ、とんとたたく。"},{w:"x",n:"影の男",t:"その子も、いっしょに連れてきなさい。"},{w:null,t:"ベラドンナの笑顔が、消える。"},{w:null,t:"ベラドンナ、打った字を一文字ずつ消す。"},{w:"bella",t:"……はい。"},{w:null,t:"男は、一度もベラドンナを見ない。"},{w:null,t:"車が動きだす。"}];
GR_SC.g12_08=[{w:null,t:"乾いた道が、北へ長くのびている。"},{w:null,t:"三人と三体が歩いている。"},{w:"hero",t:"あれ、こえたら、白い都？"},{w:"alek",t:"あれをこえて、もう少し。"},{w:"hero",t:"あれ、雪じゃん。"},{w:"alek",t:"雪だ。"},{w:"hero",t:"おれ、雪、強いから。"},{w:"alek",t:"船も強かったな。"},{w:null,t:"ヤマト、だまる。"},{w:null,t:"エリー、二人のうしろを、くるくる回りながら歩いている。"},{w:null,t:"フォルンが、ふり返って、丘の上をしばらく見る。"},{w:null,t:"フォルン、前を向く。"}];
GR_SC.g12_09=[{w:null,t:"村はずれの古い石の家。"},{w:null,t:"机の上の古い電話。"},{w:"x",n:"エリーの声（留守番電話）",t:"おばあちゃん！　エリーだよ。きょうね、丘の上ですっごく親切な社長さんにケーキもらったの。名刺も。ベラドンナさんっていうの。おばあちゃんのこと、聞かれたよ。また電話するね！"},{w:null,t:"しわのある手が、ボタンを押して、声を止める。"},{w:null,t:"手が、棚の写真立てにのびる。"},{w:null,t:"手が、写真の上で止まる。"},{w:null,t:"窓の外で、オリーブの葉が、風でさわさわ鳴っている。"},{w:null,t:"手が、写真立てを伏せる。"}];
GR_EP[12]={"t": "獅子門の丘", "sc": [["g12_01", "獅子門の丘・見学の門〜どこかの部屋（朝）", 0], ["g12_02", "船着き場〜見学の門（朝）", 0], ["g12_03", "城あとの坂道（朝）", 0], ["g12_04", "獅子の門（昼前）", 0], ["g12_05", "丘の上・アイギス社の応接間（昼）", 0], ["g12_06", "丘の北の出口〜坂の下（昼すぎ）", 0], ["g12_07", "丘の反対側の道（昼すぎ）", 0], ["g12_08", "北への道（夕方）", 0], ["g12_09", "オリーヴァ村・おばあさんの家（夜）", 0]]};
GR_SC.g13_01=[{w:null,t:"白い都へ行くには、この山を越えるのが一番の近道だ。冬でなければ。"},{w:null,t:"横なぐりの雪。"},{w:null,t:"雷が光るたびに、石塚の上に大きな影が浮かぶ。"},{w:null,t:"下の谷から、赤い光を点滅させて、白い救助のドローンがのぼってくる。"},{w:"x",n:"救助のAIの声",t:"救助に、向かいます。到着まで、あと四分。"},{w:null,t:"影が、石塚の上で槌をふり上げる。"},{w:null,t:"太い雷が、空を横切って、遠いドローンのすぐ横の岩に落ちる。"},{w:"x",n:"救助のAIの声",t:"落雷のため、引き返します。再開は、天候の回復後です。"},{w:null,t:"第13話　雲の山道"}];
GR_SC.g13_02=[{w:null,t:"その日の昼。まだ、晴れていた。"},{w:null,t:"晴れた山道。"},{w:null,t:"先頭で、アレクが紙の地図を見ながら登る。"},{w:"elly",t:"ねえ、白い都まで、あとどのくらい？"},{w:"alek",t:"この山を越えて、運河の町を抜けて、谷を一つ。大会には、ぎりぎり間に合う。"},{w:"hero",t:"ぎりぎりって、どのくらい？"},{w:"alek",t:"一日でも止まったら、間に合わない。"},{w:null,t:"ヤマト、道ばたの雪に気づく。"},{w:"hero",t:"雪！　東京じゃ、画面でしか見たことない！"},{w:null,t:"アレク、ふり返らずに、いただきを指さす。"},{w:"alek",t:"あれが下りてきたら、止まれ。道が消える。"},{w:"hero",t:"はーい。"},{w:null,t:"ヤマト、もう聞いていない。"},{w:"alek",t:"おい。"},{w:"hero",t:"一回だけ！"},{w:null,t:"ヤマト、雪をける。"},{w:"hero",f:"surprised",t:"うおおおお！　はええ！"},{w:null,t:"赤い上着が、白い斜面の下へみるみる小さくなる。"},{w:"hero",f:"surprised",t:"見たー！？"},{w:null,t:"アレク、だまって、下りてくる雲を指さす。"},{w:null,t:"ヤマト、斜面を見上げる。"},{w:null,t:"のぼりはじめる。"},{w:null,t:"フォルンが、上から一直線に駆け下りてきて、ヤマトのリュックの上に、ぴょんと乗る。"},{w:"hero",f:"serious",t:"……重いって。"},{w:null,t:"フォルン、座ったまま、あくび。"},{w:null,t:"道のすぐ横に、さっきよりもっと長い斜面。"}];
GR_SC.g13_03=[{w:null,t:"アレク、地図をポケットに入れる。"},{w:"alek",t:"ヤマト、おれの上着。エリー、ヤマトの上着。"},{w:null,t:"ヤマトがアレクのすそをつかむ。"},{w:"alek",t:"避難小屋まで、百二十歩。さっきの岩から。"},{w:null,t:"アレク、歩きだす。"},{w:"alek",t:"……百十九。"},{w:null,t:"アレクの手のひらが、冷たい石の壁にさわる。"}];
GR_SC.g13_04=[{w:null,t:"石を積んだ低い小屋。"},{w:null,t:"小屋の手前の雪の上に、赤い登山服の男が、うつぶせに倒れている。"},{w:null,t:"雪の上に、戸口から男の方へ、子どもの足あとが何本も。"},{w:"elly",t:"人！"},{w:null,t:"レン、ヤマトを見る。"},{w:"hero",f:"serious",t:"……レン？"},{w:null,t:"レンの足もとで、黄色と黒のトラの子が、戸口の内側に立っている。"},{w:null,t:"レンの手もとの画面に、字。"},{w:null,t:"レン、画面を指でおす。"},{w:null,t:"エリー、赤い箱を開けて、古い受話器をつかむ。"},{w:"elly",t:"救助、お願いします！　人が倒れてて——"},{w:"x",n:"救助のAIの声",t:"現在、たいへん混み合っております。順番に、おうかがいします。"},{w:null,t:"フォルンが、ヤマトの胸から飛び下りる。"},{w:null,t:"ヤマト、男の腕を肩にかけようとする。"},{w:null,t:"反対側に、レンがしゃがむ。"},{w:null,t:"二人、目を合わせない。"},{w:null,t:"戸口の内側で、ライガが、運ばれてくる男を見上げている。"}];
GR_SC.g13_05=[{w:null,t:"だんろの火。"},{w:"x",n:"登山服のAIの声",t:"体温が、もどりつつあります。左足の指の温度が、まだ低いままです。"},{w:null,t:"男、子ども四人と、小さなテリオン四体を見る。"},{w:"x",n:"登山家",t:"坊主は、一人か。"},{w:null,t:"レン、答えない。"},{w:null,t:"窓の外が、まっ白に光る。"},{w:"x",n:"登山家",t:"……峠の主だ。冬になると下りてくる。空を飛ぶ物が大きらいでな。あいつがいる間は、ドローンは来ない。"},{w:null,t:"かち、かち、かち。"},{w:null,t:"エリー、うとうとして、こてんとヤマトの肩に寄りかかって寝る。"},{w:null,t:"フォルンが、男のひざの前で丸くなる。"},{w:"x",n:"登山家",t:"火ってのは、昔は、神さまの物だったんだってさ。それを、こっそり人に渡した神さまがいて、怒られて、山にしばられたんだと。ちょうど、こういう山に。"},{w:"hero",t:"しばられて、どうなったの。"},{w:"x",n:"登山家",t:"さあな。毎日、鳥につつかれてたらしい。"},{w:"hero",f:"serious",t:"……ひでえ。"}];
GR_SC.g13_06=[{w:null,t:"朝なのに、窓の外はまっ白。"},{w:null,t:"エリーが、袖をまくって、だんろの前に缶詰を並べている。"},{w:"elly",t:"ヤマト、まき。二本。レンくん、お湯。アレク、缶切り、どこ。"},{w:"alek",t:"棚の、いちばん上。"},{w:"elly",t:"とどかない。"},{w:null,t:"アレク、取ってわたす。"},{w:null,t:"エリー、缶詰をあけて、スプーンを配る。"},{w:null,t:"エリーの前には、何もない。"},{w:null,t:"ヤマト、自分の缶詰を見る。"},{w:null,t:"エリー、缶詰を見る。"},{w:null,t:"エリー、安全ピンを出して、レンのジャージの裂けた袖を、三つとめる。"},{w:"x",n:"登山服のAIの声",t:"左足の指の温度が、さらに下がっています。"},{w:"hero",t:"峠のやつ、どかせばいいんだろ。"},{w:"alek",t:"この雪じゃ、相手が見えない。"},{w:"hero",t:"じゃあ、いつ。"},{w:"alek",t:"やんだら。"}];
GR_SC.g13_07=[{w:null,t:"風の音が、ふっと止まる。"},{w:null,t:"谷の下から、赤い光の救助のドローンがのぼってくる。"},{w:"x",n:"救助のAIの声",t:"天候が、回復しました。救助に、向かいます。"},{w:null,t:"石塚の上に、雲の毛の大きな影が立ち上がる。"},{w:null,t:"ドローンが、ふらつきながら小屋の方へ逃げてくる。"},{w:null,t:"影が、石塚をけって追ってくる。"},{w:null,t:"ドローンは、もう谷へ消えている。"},{w:null,t:"影は、うしろの石塚を、ちらっとふり返る。"},{w:null,t:"ヤマトが、戸口から、それを見ている。"},{w:null,t:"小屋の横の、雪にうもれかけた古い柱が、ぴっと鳴る。"},{w:"x",n:"登山道の柱の声",t:"野生のテリオン、トールガです。近くの方は、建物の中へ。"}];
GR_SC.g13_08=[{w:null,t:"トールガは、石塚の上にもどっている。"},{w:null,t:"ヤマト、戸口の前でフォルンを下ろす。"},{w:null,t:"エリーの箱から、ピリポン。"},{w:null,t:"アレクのクロッコ。"},{w:null,t:"ヤマトは、小屋の戸口の前に立つ。"}];
GR_SC.g13_10=[{w:null,t:"フォルレオンの体が、ふわっと光る。"},{w:null,t:"ヤマト、戸口から走り出る。"},{w:null,t:"フォルン、ヤマトを見上げる。"},{w:null,t:"雪原の向こうで、トールガが起き上がる。"},{w:null,t:"トールガ、背を向ける。"},{w:"x",n:"登山服のAIの声",t:"天候が回復しました。夜間の山の飛行は、規則で行っておりません。救助は、あすの朝、七時に到着します。"},{w:"x",n:"登山家",t:"……七時か。"}];
GR_SC.g13_11=[{w:null,t:"だんろの火。"},{w:null,t:"レンのとなりで、ライガが丸くなっている。"},{w:null,t:"ヤマトのひざで、フォルンが寝ている。"},{w:null,t:"レンの目が、フォルンへ行く。"},{w:"hero",f:"serious",t:"……なんだよ。"},{w:"dimi",t:"別に。"},{w:null,t:"レン、まきを一本足す。"},{w:"hero",t:"レン、白い都の大会、出んの。"},{w:"dimi",t:"出る。"},{w:"hero",f:"serious",t:"……おれも。"},{w:"dimi",t:"登録、ないだろ。その狐。"},{w:"hero",t:"だから、出んの。"},{w:null,t:"レン、何か言いかけて、やめる。"}];
GR_SC.g13_12=[{w:null,t:"戸が、そっと開く。"},{w:null,t:"レン、雪の道を峠の方へ歩いていく。"},{w:null,t:"小屋の壁の板。"}];
GR_SC.g13_13=[{w:"x",n:"救助のAIの声",t:"お待たせしました。ご利用、ありがとうございます。"},{w:null,t:"男が、担架に乗せられる。"},{w:null,t:"エリー、壁の板の「決勝」を、指でなぞっている。"},{w:"elly",t:"レンくんの字？"},{w:"hero",f:"serious",t:"……さあ。"},{w:null,t:"ヤマト、リュックをしょって、先に戸口を出る。"},{w:"alek",t:"一日、なくした。"},{w:"elly",t:"でも、間に合う？"},{w:"alek",t:"……走ればな。"}];
GR_SC.g13_14=[{w:null,t:"峠の向こう側。"},{w:null,t:"店先のワゴンに、色ちがいの毛糸のマフラーの山。"},{w:null,t:"エリー、からし色を首に巻く。"},{w:null,t:"エリー、赤いのを、ヤマトにわたす。"},{w:"hero",t:"赤とか、目立つじゃん。"},{w:"elly",t:"ヤマト、目立つの好きでしょ。"},{w:null,t:"ヤマト、だまって巻く。"},{w:null,t:"アレクが、財布をさかさにふる。"},{w:"x",n:"店のおばあさん",t:"冬の売れ残りだからね。ほつれてても、文句なしだよ。"},{w:null,t:"ヤマト、赤いマフラーのはしから出た毛糸を、指で引っぱる。"},{w:"alek",t:"引っぱるな。"},{w:null,t:"ヤマト、あわてて毛糸を押しこむ。"},{w:null,t:"町の向こう。"}];
GR_SC.g13_15=[{w:null,t:"三人の横を、白い大きな車が追いこしていく。"},{w:null,t:"男、ペンで、写真の横に小さく丸をつける。"},{w:null,t:"荷台の布のすきまから、虹色の羽の先が一枚だけのぞいて、すぐ引っこむ。"}];
GR_EP[13]={"t": "雲の山道", "sc": [["g13_01", "雲の山・峠（夕方・吹雪）", 0], ["g13_02", "雲の山道（昼）", 0], ["g13_03", "雲の中（夕方）", 0], ["g13_04", "避難小屋の前（夕方）", 0], ["g13_05", "避難小屋の中（夜）", 0], ["g13_06", "避難小屋の中（次の日・吹雪）", 0], ["g13_07", "避難小屋の前（夕方）", 0], ["g13_08", "向かい合う", 0], ["g13_09", "勝負", 1], ["g13_10", "勝負のあと", 0], ["g13_11", "避難小屋の中（夜）", 0], ["g13_12", "避難小屋（夜明け前）", 0], ["g13_13", "避難小屋の前（朝）", 0], ["g13_14", "ふもとの町・小さな店の前（夕方）", 0], ["g13_15", "ふもとの町を出る道（夜）", 0]]};
GR_SC.g14_01=[{w:null,t:"運河の町コリンタ。海と海を、まっすぐな水の道がつないでいる。"},{w:null,t:"切り立った岩のかべのあいだを、細い運河がまっすぐ走る。"},{w:null,t:"橋の手前に、貨物船が何そうも、つらなって止まっている。"},{w:null,t:"アイギス社のドローンが、運河のかべに光の文字を映す。"},{w:null,t:"船室の窓から、ひげの男が顔を出す。"},{w:null,t:"橋のたもとに、白い大きな車。"},{w:null,t:"ユスフ、数えていた指を、ぎゅっとにぎる。"},{w:null,t:"第14話　運河の町コリンタ"}];
GR_SC.g14_02=[{w:null,t:"三人が山の道から下りてくる。"},{w:null,t:"運河の岸で、洗たく屋のおばさんの水の子が、つるしたシーツに霧をふいている。"},{w:null,t:"広場のまん中に、古い丸いモザイクの床。"},{w:"x",n:"実況の声",t:"ふんばったーっ！　変わったーっ！"},{w:null,t:"子どもたちがわっとさけぶ。"},{w:null,t:"エリー、画面の小さい方の子を、じっと見ている。"},{w:null,t:"ヤマト、肩のフォルンを両手で持ち上げて、子どもたちのうしろから割りこむ。"},{w:"hero",t:"おれのフォルンもな、あれより、もっとでっかくなるんだぜ。"},{w:"x",n:"子ども",t:"ちっちゃ。"},{w:"hero",t:"勝負になったらな。見てろよ。"},{w:null,t:"ヤマト、モザイクのまん中にフォルンを置く。"},{w:"hero",t:"フォルン、変われ。"},{w:"hero",f:"serious",t:"……こう、ぶわっとだよ、ぶわっと。"},{w:"yusuf",t:"お兄ちゃん、画面に出てた！　ぼく、ユスフ。うちの船、すぐそこだよ。"}];
GR_SC.g14_03=[{w:null,t:"さびた甲板。"},{w:"yusuf",t:"二年前に、この船で来たの、父さんと。"},{w:null,t:"ユスフ、地図の小さな丸を、一つずつ指でさす。"},{w:"yusuf",t:"ここがパン屋さん。きのう、ぼくの名前、おぼえてくれたの。ここ、サッカーする所。でも船、三日で沖へ行かなかったら、お預かりなんだって。"},{w:null,t:"ユスフの指が、パン屋の丸を何回もなぞる。"},{w:"yusuf",t:"……あしたも行くって、言っちゃったんだけどな。"},{w:null,t:"アレク、甲板のはしから、上がったままの橋を見ている。"},{w:"alek",t:"向こう岸へ渡るには、あの橋か、船だ。"},{w:"yusuf",t:"橋、沈むんだよ。水の中に沈めて、その上を船が通るの。ミハリスさんがレバーで。"},{w:"hero",t:"橋が、沈むの？"},{w:"yusuf",t:"うん。あとね、あのとりでの上の泉は、羽のある馬が、ひづめでこんってやったら、水が出たんだって。"},{w:null,t:"ユスフ、町の上の岩山を指さす。"},{w:null,t:"ヤマト、足で甲板を、こんとける。"},{w:null,t:"ヤマトの胸の時計のつまみに、指が当たっている。"}];
GR_SC.g14_04=[{w:null,t:"黄色い機械のあいだの、折りたたみの机。"},{w:null,t:"橋のたもとの小屋の窓から、油だらけの手の男が、こっちを見ている。"},{w:null,t:"ノモス、顔を上げる。"},{w:"nomos",t:"十二番。抹消、と書いてありますが。"},{w:"alek",t:"抜けたんだよ。"},{w:"nomos",t:"抜けた、とは聞いていません。"},{w:null,t:"ノモス、画面を流す。"},{w:"nomos",t:"そちらの娘さんを、保護します。保護者のいない旅行中のお子さんは、保護。決まりですので。"},{w:"elly",t:"えー、やだ。"},{w:"hero",t:"保護って、どこに連れてくんだよ。"},{w:"nomos",t:"上が決めます。わたしは、お連れするだけです。"},{w:"hero",t:"じゃあ、勝負しろよ。"},{w:"nomos",t:"申しこまれたら、受ける決まりです。わたしが負けたら、班はここから引き上げます。班がいなくなれば、船を動かす命令もなくなります。"},{w:null,t:"甲板の上で、ユスフが顔を上げる。"},{w:"alek",t:"そっちが勝ったら。"},{w:"nomos",t:"娘さんは保護。それと、その狐。名簿にありますので。"},{w:null,t:"ノモス、かごの布に手をかける。"},{w:"nomos",t:"上から、この子を使うように、と。"},{w:null,t:"布が取られる。"},{w:null,t:"右の羽の付け根に、白っぽい古い傷あと。"},{w:null,t:"エリーの笑顔が、そのまま止まる。"},{w:"elly",f:"serious",t:"……ニジッコ？"},{w:null,t:"鳥の頭が、ぴくっと動く。"},{w:null,t:"ノモスの指が画面をたたく。"}];
GR_SC.g14_05=[{w:null,t:"運河の広場。"},{w:null,t:"鳥は、奥の柱の上に下りて、羽をたたむ。"},{w:null,t:"岸に町の人が集まる。"},{w:null,t:"ヤマト、肩のフォルンを石だたみに下ろす。"},{w:null,t:"エリー、クッキーの箱を足もとに置く。"},{w:"nomos",t:"（腕時計を見て）始めます。"}];
GR_SC.g14_07=[{w:null,t:"わらの上の木の箱。"},{w:null,t:"8歳のエリーが、ぶどうを一粒、黄色いひよこに近づける。"},{w:null,t:"ひよこの右の羽の付け根に、小さな白い傷。"},{w:null,t:"次のしゅんかん、ひよこの体がぽうっと光る。"},{w:null,t:"物置の前に、白い回収車。"},{w:"x",n:"回収車の声",t:"持ち主の決まっていない子は、施設へ。審査中の子も、決まりです。持ち主になれるのは、十五歳からです。"},{w:null,t:"エリーが、ロボットの腕にしがみつく。"},{w:"x",n:"回収車の声",t:"ご協力、ありがとうございます。"},{w:null,t:"坂の上に、羽が一枚。"}];
GR_SC.g14_09=[{w:null,t:"ナルカミが光ってしぼみ、小さなピリポンにもどる。"},{w:null,t:"石だたみに、割れたチップ。"},{w:null,t:"鳥が起き上がる。"},{w:null,t:"エリー、ピリポンを片手に抱いたまま、もう片方の人さし指を、そっと前に出す。"},{w:null,t:"鳥が、ひと羽ばたきで、エリーの指にとまる。"},{w:null,t:"鳥の羽が、ぷうっとふくらむ。"},{w:null,t:"エリーは、指を曲げない。"},{w:null,t:"鳥が飛び立つ。"},{w:null,t:"エリーの手は、しばらく、そのままの形で上がっている。"},{w:null,t:"ノモス、画面の「回収　失敗」を見て、消す。"},{w:"nomos",t:"班は、引き上げます。"},{w:null,t:"運河のかべの光の文字が変わる。"},{w:null,t:"作業員が機械をたたむ。"},{w:null,t:"ノモスが机をたたむひょうしに、書類の板から画面が一枚すべり落ちる。"},{w:null,t:"クロッコがのそのそ歩いていって、曲がったあごで画面をくわえ、アレクの足もとに置く。"}];
GR_SC.g14_10=[{w:null,t:"ヤマト、足もとのフォルンを、だまって抱き上げる。"},{w:null,t:"アレクの指が、画面をめくる。"},{w:null,t:"ヤマト、肩のフォルンの耳のうしろを、指でさわる。"},{w:"elly",t:"大理石の谷って、どこ？"},{w:"alek",t:"白い都の、すぐ手前だ。"},{w:null,t:"エリー、北の山の方を見る。"}];
GR_SC.g14_11=[{w:null,t:"橋の横の小さな小屋。"},{w:null,t:"中で、ミハリスが橋の機械をいじっている。"},{w:"yusuf",t:"ミハリスさん、橋、沈めてよ。会社の人たち、もういないよ。"},{w:"mihalis",t:"上からの紙がない。紙がないと、沈めない。"},{w:"yusuf",t:"でも、もういないんだよ。"},{w:"mihalis",t:"紙は、まだ来てない。"},{w:null,t:"ユスフ、戸口の段に座って、紙袋のパンをちぎる。"},{w:"yusuf",t:"パン屋さんがくれたの。ぼくの名前、言って。"},{w:null,t:"ミハリスの手が止まる。"},{w:null,t:"フォルンがパンのかけらをしっぽの火であぶっている。"},{w:null,t:"ミハリス、立ち上がる。"},{w:"alek",t:"紙なしで沈めたら、あんた、クビだろ。"}];
GR_SC.g14_12=[{w:null,t:"ユスフの船が、沈んだ橋の上をゆっくり通る。"},{w:null,t:"北の岸の小さな船着き場で、三人が下りる。"},{w:"yusuf",t:"ぼくら、このまま白い都の港まで行くの。荷物を積む仕事、父さんが見つけたんだ。"},{w:null,t:"ひげの男が、操舵室の窓から一回うなずく。"},{w:null,t:"甲板のはしで、ユスフが右の手のひらを上げる。"},{w:null,t:"船着き場の上の道に、古い道しるべ。"},{w:null,t:"その道を、白い盾のトラックが一台、また一台と走っていく。"},{w:null,t:"エリーの目が、トラックを追う。"}];
GR_EP[14]={"t": "運河の町コリンタ", "sc": [["g14_01", "運河（夜明け）", 0], ["g14_02", "コリンタの広場（朝）", 0], ["g14_03", "止められた貨物船（朝）", 0], ["g14_04", "大橋のたもと", 0], ["g14_05", "向かい合う", 0], ["g14_06", "勝負", 1], ["g14_07", "オリーヴァ村・ぶどう畑の奥の物置（6年前）", 0], ["g14_08", "勝負・つづき", 1], ["g14_09", "勝負のあと", 0], ["g14_10", "橋のたもと（昼すぎ）", 0], ["g14_11", "技師の小屋（夕方）", 0], ["g14_12", "運河（夜）", 0]]};
GR_SC.g15_01=[{w:null,t:"大理石の谷。白い都の神殿の石は、ぜんぶ、ここから運ばれた。"},{w:null,t:"天井の高い、白い大理石の広間。"},{w:null,t:"ケースの中で、小さなテリオンたちが眠っている。"},{w:null,t:"作業員が、札の横にシールを貼っていく。"},{w:"x",n:"警備のAIの声",t:"警備の人員は、本日もテリオン一体です。経費は、前年の八割減です。"},{w:null,t:"見張りの目が、うすく開く。"},{w:null,t:"第15話　大理石の谷"}];
GR_SC.g15_02=[{w:null,t:"山を巨大な包丁で切ったような、まっ白ながけ。"},{w:null,t:"谷のふちで、三人が腹ばいになって見下ろしている。"},{w:"alek",t:"昔、ここも案内してた。あの辺の石で、白い都の丘の神殿を建てたんだ。牛で引いて、何年もかけて。"},{w:null,t:"エリー、がけを指でなぞる。"},{w:"elly",t:"……あの日ね、車に、ほかの子も乗ってたの。いるかな。"},{w:null,t:"ヤマトとアレクがエリーを見る。"},{w:null,t:"アレク、ポケットからノモスの画面を出す。"},{w:"alek",t:"おれは、この続きがほしい。課長の判を押したやつが、何をやってるか。"},{w:null,t:"ヤマトは谷の切れ目の先を見ている。"},{w:"hero",t:"大会、あしただぞ。"},{w:"alek",t:"だから、きょうのうちだ。"},{w:"hero",t:"分かってるって。"},{w:null,t:"ヤマト、立ち上がって、両手を口に当てる。"},{w:"alek",t:"おい——"},{w:"hero",t:"やっほーーー！"},{w:"x",n:"こだま",t:"……やっほー……やっほー……やっほー……"},{w:null,t:"ヤマト、ふり返って、にやっと笑う。"},{w:"hero",f:"smile",t:"三回！　すげえ、三回返ってきた！"},{w:null,t:"四回目のかわりに、谷のスピーカーが鳴る。"},{w:"x",n:"谷のスピーカーの声",t:"現在、作業中です。お静かにお願いいたします。"},{w:null,t:"建物の屋根から、カメラのついたドローンが二台、ふわりと浮いて、こっちを向く。"},{w:null,t:"アレク、ヤマトのマフラーをつかんで、うしろへ引き倒す。"},{w:null,t:"アレク、マフラーをはなさない。"},{w:"alek",t:"正面の門、なくなった。"},{w:"elly",t:"じゃあ、どこから入るの？"},{w:null,t:"アレク、がけの下を指さす。"},{w:"alek",t:"昔の石切り場の、排水路だ。"}];
GR_SC.g15_03=[{w:null,t:"石の管の中。"},{w:"hero",f:"serious",t:"……くっせえ。なんだここ。"},{w:"alek",t:"だれのせいだ。"},{w:null,t:"ヤマト、鼻をつまんで前を向く。"},{w:null,t:"ヤマトの足が、ぬるっとした物をふむ。"},{w:null,t:"エリー、箱を頭にのせたまま、ヤマトの上をまたいで通る。"},{w:null,t:"フォルン、アレクの頭の上から、ずぶぬれのヤマトを見下ろしている。"},{w:null,t:"上に、鉄の格子が三つ。"},{w:null,t:"アレク、冷たい水に手を入れる。"}];
GR_SC.g15_04=[{w:null,t:"床の格子が、がたんと持ち上がる。"},{w:null,t:"エリーがケースの並びのあいだを走る。"},{w:null,t:"エリーの足が止まる。"},{w:null,t:"丸い耳の子。"},{w:null,t:"エリー、ガラスに両手をつける。"},{w:null,t:"アレクは札のいちばん下を見ている。"},{w:null,t:"広間の奥で、台の上の金色の影が目を開ける。"},{w:null,t:"グリュプスが立ち上がる。"},{w:"x",n:"警備のAIの声",t:"侵入者のテリオンを確認しました。"}];
GR_SC.g15_05=[{w:null,t:"大理石の床。"},{w:null,t:"ヤマトの肩から、フォルンが床に飛び下りる。"},{w:"x",n:"警備のAIの声",t:"ケースに近づく物を、排除します。"}];
GR_SC.g15_07=[{w:null,t:"三体が光って、小さなフォルン、ピリポン、クロッコにもどる。"},{w:"x",n:"警備のAIの声",t:"警備のテリオンが倒れました。担当者には、あすの朝、お知らせします。"},{w:"hero",f:"serious",t:"……あすの朝？"},{w:"x",n:"警備のAIの声",t:"夜間のお知らせは、経費削減のため、行っておりません。"},{w:null,t:"グリュプスが目を開ける。"},{w:null,t:"グリュプス、ゆっくり歩いていって、ケースの並びの前で羽をたたんで伏せる。"},{w:"elly",f:"serious",t:"……守ってるの？"},{w:"alek",t:"（案内の時の言い方で）グリフォンは、金の番をする。"},{w:null,t:"エリーが、いちばん近いケースに走る。"},{w:null,t:"ヤマトが来て、いっしょに引く。"},{w:null,t:"伏せたグリュプスが、二人を見ている。"},{w:null,t:"アレクは、ノモスの画面をケースの札に向ける。"},{w:"hero",t:"それ、どうすんの。"},{w:"alek",t:"送る。"},{w:"hero",t:"だれに。警察か？"},{w:"alek",t:"保護局の研究所の、所長。課長の上だ。"}];
GR_SC.g15_08=[{w:null,t:"ガラス戸の小部屋。"},{w:null,t:"アレク、机の紙の束をめくる。"},{w:null,t:"ヤマトが横からのぞいて、胸の時計をにぎる。"},{w:null,t:"細い窓の向こうに、遠くの塔。"},{w:"alek",t:"……本番って、なんのだよ。"},{w:null,t:"だれも答えない。"},{w:null,t:"エリーは、壁の絵の前に立っている。"},{w:"elly",f:"serious",t:"……おっきい。"},{w:null,t:"ヤマト、絵の巨人の腕と、自分の腕を見くらべる。"},{w:null,t:"アレク、絵も撮る。"},{w:"alek",t:"出るぞ。あいつが知らせるのは、あすの朝だ。"},{w:null,t:"エリー、広間をふり返る。"}];
GR_SC.g15_09=[{w:null,t:"画面の横に、もう一つの窓。"},{w:null,t:"女の指が、ボタンの上に来て、止まる。"},{w:null,t:"指を下ろす。"}];
GR_SC.g15_10=[{w:null,t:"机にケーキの箱と紅茶。"},{w:"x",n:"画面の声",t:"谷のドローンが、けさ撮ったものです。昼すぎには、排水路の出口に子どもの足あとが。どうしますか。"},{w:"bella",t:"……あら。"},{w:null,t:"ベラドンナ、写真をとじる。"},{w:"bella",t:"放っておいて。もう、あそこは要らないもの。大会は、予定どおり。買い手のみなさまにも、そうお伝えして。"},{w:null,t:"塔のてっぺんの赤い明かり。"},{w:null,t:"白い都の港。"},{w:null,t:"甲板で、三人が毛布にくるまって並んで寝そべっている。"},{w:null,t:"ヤマト、塔を見たまま、胸の時計をにぎっている。"}];
GR_EP[15]={"t": "大理石の谷", "sc": [["g15_01", "大理石の谷・保管庫（夜）", 0], ["g15_02", "谷の上（朝）", 0], ["g15_03", "古い排水路（昼）", 0], ["g15_04", "保管庫（昼）", 0], ["g15_05", "向かい合う", 0], ["g15_06", "勝負", 1], ["g15_07", "勝負のあと", 0], ["g15_08", "保管庫のとなりの事務室", 0], ["g15_09", "研究所・所長室（夜）", 0], ["g15_10", "白い都・アイギス社のビルの最上階（夜）", 0]]};
GR_SC.g16_01=[{w:null,t:"白い都。神殿の丘のふもとに、二千年分の町が積み重なっている。"},{w:null,t:"古い神殿の屋根の上を、広告のドローンが飛ぶ。"},{w:null,t:"大競技場のガラスの屋根の上に、細長い白い塔。"},{w:null,t:"競技場の裏に、黒い車が何台も並ぶ。"},{w:null,t:"出むかえる、日傘の女。"},{w:"bella",t:"ようこそ。きょうは、いい物をお見せできますわ。"},{w:null,t:"ベラドンナ、塔を見上げる。"},{w:null,t:"第16話　白い都の大会"}];
GR_SC.g16_02=[{w:null,t:"広場はお祭り。"},{w:null,t:"エリーが、両手に串焼きを持って、もう一本くわえている。"},{w:"elly",t:"はい、これ。屋台のおじさんの火、ピリポンがつけてあげたの。そしたら、くれた。"},{w:null,t:"屋台の炭の上で、ピリポンの毛がまだぱちぱち鳴っている。"},{w:null,t:"アレク、受け取った串を見て、エリーを見る。"},{w:"alek",t:"……ただか。"},{w:null,t:"エリー、もぐもぐしながらうなずく。"},{w:null,t:"ヤマトは、入口の大きな組み合わせ表の前に立っている。"},{w:null,t:"表のいちばん上に、金色の字。"},{w:null,t:"ヤマトの目が、金色の字から足もとのフォルンへ。"},{w:null,t:"広場の上を、白いドローンが二台回っている。"},{w:null,t:"アレク、ヤマトのマフラーを鼻の上まで引き上げる。"}];
GR_SC.g16_03=[{w:null,t:"受付の机の横に、腕が一本の白いカメラの機械。"},{w:"x",n:"受付の係",t:"はい次の方。お名前を。子はこちらで写真をとります。"},{w:null,t:"ヤマト、名前の欄に「ヤ」と書きかける。"},{w:"alek",t:"（小さく）本名書いたら、狐ごと回収だぞ。"},{w:"hero",t:"（小さく）じゃあ、なんて書くんだよ。"},{w:"alek",t:"なんでもいい。"},{w:"hero",t:"なんでもいいが、いちばん困るんだって。"},{w:null,t:"エリーが、二人のあいだから串焼きごと顔を出す。"},{w:"elly",t:"ダレデモナイは？　おばあちゃんのお話の人。一つ目の巨人を、それでだましたの。"},{w:"hero",f:"serious",t:"……ずるっ。"},{w:"elly",t:"ずるいよね。"},{w:null,t:"ヤマト、もう書いている。"},{w:"x",n:"受付の係",t:"登録名の変更は、受けつけておりません。なりすましの防止のためです。"},{w:null,t:"アレク、天井を見る。"},{w:null,t:"ヤマト、フォルンを両手で高くカメラに向ける。"},{w:null,t:"ぱしゃ、の直前。"},{w:null,t:"画面に、歯を見せたヤマトと、そのとなりに、ふさふさのしっぽだけ。"},{w:"x",n:"受付の機械の声",t:"登録にない形式です。判定、できません。"},{w:"hero",t:"もう一回！　今のなし！"},{w:null,t:"係、画面を見て、うしろに並ぶ大勢の人を見る。"},{w:"x",n:"受付の係",t:"……次の方。"},{w:null,t:"ヤマト、押し出されながら、しっぽだけの写真をまだのぞきこんでいる。"},{w:null,t:"机の上の名簿が、風でめくれる。"}];
GR_SC.g16_04=[{w:null,t:"客席は満員。"},{w:"x",n:"司会",t:"昔むかし、この町の名前をめぐって、二人の神さまが、町の人に贈り物をくらべさせました！"},{w:null,t:"海の神がほこで地面をつく。"},{w:null,t:"女神がやりで地面をつく。"},{w:"x",n:"司会",t:"町の人が選んだのは、オリーブ！　それで、この町は女神の名前になったのです！"},{w:"elly",t:"村のオリーブも、ここから来たのかな。"},{w:"alek",t:"さあな。"},{w:null,t:"ヤマト、オリーブの木の根もとを見ている。"}];
GR_SC.g16_05=[{w:null,t:"通路の壁の結果の画面に、字が上へ上へとのびていく。"},{w:null,t:"「決勝　ダレデモナイ　対　レン」。"},{w:null,t:"通路の向こうから、レンが来る。"},{w:null,t:"すれちがう。"},{w:"dimi",t:"その狐、まだ言うこと聞かないのか。"},{w:"hero",t:"聞くよ。たまにな。"},{w:null,t:"レン、何も言わずに歩いていく。"},{w:null,t:"控えのベンチ。"},{w:"elly",t:"フォルン、こっちおいで。"},{w:null,t:"フォルンの耳が、くるっと左の箱を向く。"},{w:"elly",f:"serious",t:"……耳だけ、来た。"},{w:null,t:"ヤマト、フォルンの耳と足を見くらべる。"},{w:null,t:"頭の上で、ぶうん、と低い音。"},{w:null,t:"通路の向こうで、親子の連れた子が、びくっと体をすくめる。"},{w:null,t:"アレクが、天井を見上げる。"}];
GR_SC.g16_06=[{w:null,t:"ガラスの屋根ごしの夕日。"},{w:"x",n:"司会",t:"決勝は大将戦！　一体どうしの、真っ向勝負です！"},{w:null,t:"大競技場の場内。"},{w:null,t:"貴賓席に、ベラドンナと外国の買い手たち。"},{w:null,t:"レンが、足もとにライガを下ろす。"},{w:null,t:"光がはじける。"},{w:null,t:"大きな画面に「エレグリオ」。"},{w:"x",n:"司会",t:"重ねた子も、一体です！"},{w:null,t:"ヤマト、フォルンを走路に下ろす。"},{w:"x",n:"司会",t:"決勝、始め！"}];
GR_SC.g16_08=[{w:null,t:"フォルレオンが光って、小さなフォルンにもどる。"},{w:null,t:"ヤマトが走路に走りこんで、フォルンの前ですべって止まる。"},{w:null,t:"ヤマト、頭の葉をつまんで取ろうとする。"},{w:null,t:"走路の向こう。"},{w:null,t:"レンが、ライガの横にしゃがんで、背中に手をのせている。"},{w:null,t:"レン、ヤマトの方を見ない。"},{w:null,t:"客席の手すりを乗りこえかけたエリーの上着を、アレクがつかんでいる。"}];
GR_SC.g16_09=[{w:null,t:"いちばん上にヤマト。"},{w:null,t:"係が、フォルンに登録のチップを入れる白い機械を当てる。"},{w:null,t:"係が、ヤマトに金色のふちの登録の札をわたす。"},{w:null,t:"ヤマト、札を見る。"},{w:"hero",f:"serious",t:"……これ、おれ？"},{w:null,t:"客席のいちばん前で、エリーがおなかを抱えて笑っている。"},{w:null,t:"ヤマト、札をパーカーのポケットに大事にしまう。"},{w:null,t:"レンも準優勝の札を受け取る。"},{w:"x",n:"司会",t:"それでは、協賛のアイギス社、ベラドンナ社長より、ひとこと！"},{w:null,t:"ベラドンナが日傘をたたんで立つ。"},{w:"bella",t:"おめでとう、ダレデモナイくん。いいお名前ね。"},{w:null,t:"ベラドンナがヤマトに小さく手をふる。"},{w:"bella",t:"では、本日の目玉を。"},{w:null,t:"赤い爪の指が、手もとの画面を、とん、とたたく。"}];
GR_SC.g16_10=[{w:null,t:"頭の上で、塔が鳴る。"},{w:null,t:"客席のチップの子たちが、いっせいに体をすくめる。"},{w:null,t:"エリーの腕の箱の中で、ピリポンが耳をぴんと立てる。"},{w:null,t:"表彰台の上。"},{w:null,t:"四つとも、いっぺんに、まっ赤に光る。"},{w:null,t:"音が、やむ。"},{w:null,t:"足の下から、低い、長い声が上がってくる。"},{w:null,t:"表彰台が、ことん、と小さくゆれる。"}];
GR_EP[16]={"t": "白い都の大会", "sc": [["g16_01", "白い都・大通り（朝）", 0], ["g16_02", "大競技場の前（朝）", 0], ["g16_03", "受付の机（朝）", 0], ["g16_04", "大競技場・開会の出し物（昼前）", 0], ["g16_05", "控えの通路（昼〜夕方）", 0], ["g16_06", "決勝（夕方）", 0], ["g16_07", "勝負", 1], ["g16_08", "勝負のあと", 0], ["g16_09", "表彰台（夕方）", 0], ["g16_10", "大競技場（夕方）", 0]]};
GR_SC.g17_01=[{w:null,t:"白い都の大会は、終わったばかりだった。"},{w:null,t:"足の下から、牛の吠える声。"},{w:null,t:"競技場のまん中の白い線に沿って、地面が割れる。"},{w:null,t:"割れ目の前に、警察のロボットが十体、盾をかまえて、横一つにならぶ。"},{w:"x",n:"警察のロボット",t:"危険区域です。下がってください。"},{w:null,t:"割れ目の奥で、赤い光が一つ、点いて、消える。"},{w:null,t:"黒く反ったつのが二本、地面から突き出る。"},{w:null,t:"ならんだロボットが、まとめて宙に浮く。"},{w:null,t:"つのが、割れ目の奥へ引っこむ。"},{w:null,t:"第17話　守り①ミノタス・前編"}];
GR_SC.g17_02=[{w:null,t:"割れ目は、客席のいちばん前まで来ている。"},{w:null,t:"その前に、レン。"},{w:null,t:"ライガが、レンの前に出て、毛の雷を逆立てる。"},{w:null,t:"割れ目から、つのが、もう一突き。"},{w:null,t:"レン、走って、ライガの前に立つ。"},{w:null,t:"つのは、もう出てこない。"},{w:null,t:"ヤマトが走ってくる。"},{w:null,t:"レン、ヤマトを見ない。"},{w:"dimi",f:"serious",t:"……息は、ある。"},{w:null,t:"ヤマト、何か言いかける。"},{w:null,t:"保護局の制服の男が、白い顔で割れ目の前に立つ。"},{w:"x",n:"保護局の職員",t:"近づかないで！　だれも、近づかないでください！"},{w:null,t:"職員のうしろで、割れ目のふちが、ぽろぽろと崩れていく。"}];
GR_SC.g17_03=[{w:null,t:"ガラスで囲まれた席。"},{w:null,t:"赤い爪の女、ベラドンナ。"},{w:"bella",t:"……受けつけない？"},{w:null,t:"ベラドンナ、画面を伏せる。"},{w:null,t:"競技場の裏。"}];
GR_SC.g17_04=[{w:null,t:"大きな画面に、ニュース。"},{w:"x",n:"ニュースの声",t:"白い都で、地震がありました。市の中心部で、地面が割れています。"},{w:null,t:"牛のことは、一言も出ない。"},{w:"alek",t:"……地震で、ロボットが十体、飛ぶか。"},{w:null,t:"ヤマト、胸に革ひもで下げた古い時計の、つまみを押す。"},{w:null,t:"村の丘の印だけ、ほかより大きい。"},{w:null,t:"エリー、通路のはしの公衆電話へ走る。"},{w:null,t:"ヤマトが、硬貨を一枚、エリーの手のひらに落とす。"},{w:"elly",t:"おばあちゃん！　ヤマト、優勝したよ！"},{w:"oba",n:"おばあさん（電話）",t:"……うん。中継で、見てた。"},{w:null,t:"電話の向こうで、食器が、かたかた鳴っている。"},{w:"oba",n:"おばあさん（電話）",t:"こっちも、ゆれてる。丘の方から。……エリー、丘の子が起ききったら、村がつぶれる。"},{w:"elly",t:"丘の子？"},{w:"oba",n:"おばあさん（電話）",t:"……ごめん。切るね。"},{w:null,t:"エリー、受話器を耳に当てたまま、まばたきをする。"},{w:null,t:"足の下で、また、ずん。"},{w:null,t:"レンが、ライガを抱えて救護のテントへ歩いていく。"},{w:null,t:"ヤマト、メダルを首からはずして、ポケットにつっこむ。"},{w:"hero",t:"アレク。丘の下、入れる所ある？"},{w:"alek",t:"……裏に、閉めた入口がある。大会の案内の地図に、のってた。"},{w:"elly",t:"村は？"},{w:"hero",t:"村のは、あとでいい。足の下のが、先。"}];
GR_SC.g17_05=[{w:null,t:"丘の裏には、見学をやめた古い入口がある。"},{w:null,t:"草にうもれた石の門。"},{w:"x",n:"警察のロボット",t:"立ち入り禁止です。"},{w:null,t:"ヤマト、胸を張って、ポケットから優勝の札を出す。"},{w:"hero",t:"白い都の大会、優勝。通して。"},{w:null,t:"ロボットの目が、札を読む。"},{w:"x",n:"警察のロボット",t:"登録者、ダレデモナイ。該当者、なし。"},{w:null,t:"ロボットの腕が、ヤマトの胸を、やさしく押しもどす。"},{w:null,t:"エリーが札を拾う。"},{w:null,t:"ヤマト、しりもちのまま、口をとがらす。"},{w:null,t:"アレク、さくの横の草をかき分ける。"},{w:null,t:"ロボットは、正面のさくを見たまま。"},{w:null,t:"くぐり戸の上に、色のあせた札。"}];
GR_SC.g17_06=[{w:null,t:"石の柱が二本。"},{w:null,t:"エリー、カバンの中をさぐる。"},{w:"elly",t:"ひも、ない。"},{w:"alek",t:"ひも？"},{w:"elly",t:"迷路でしょ。"},{w:null,t:"エリー、自分のからし色のマフラーに手をかける。"},{w:null,t:"ヤマト、自分の赤いマフラーをはずす。"},{w:"hero",t:"おれの使えよ。"},{w:null,t:"エリー、赤いマフラーの端の糸を一本、ぷつりと引く。"},{w:null,t:"エリー、マフラーをヤマトの首に、ふわっともどす。"},{w:"elly",t:"ヤマトが持ってて。歩くと、ほどける。"},{w:"hero",f:"serious",t:"……巻いたまま？"},{w:"elly",t:"そのほうが、なくさないでしょ。"},{w:null,t:"ヤマト、階段を下りる。"}];
GR_SC.g17_07=[{w:null,t:"天井の低い石の通路。"},{w:null,t:"角を曲がる。"},{w:null,t:"アレク、くつの先で送信機のふたを起こす。"},{w:null,t:"アレク、札をポケットにしまう。"},{w:null,t:"ヤマトの首のマフラーが、ひと回り細くなっている。"},{w:null,t:"通路の先の壁に、古い文字が一行。"},{w:null,t:"エリー、指で字を一つずつなぞる。"},{w:null,t:"字の頭の一つが、欠けている。"},{w:"elly",f:"serious",t:"……「……数えて、壁は動く」、だって。"},{w:null,t:"……止まる。"},{w:null,t:"三人、だまる。"},{w:null,t:"しんとした中で、どこかで、ゴトン、と石の音。"},{w:null,t:"……カツン、ドン。"},{w:null,t:"ヤマトが歩き出す。"},{w:null,t:"首から出た毛糸が、閉じた壁のすきまにはさまって、ぴんと張る。"},{w:null,t:"アレク、毛糸を拾う。"},{w:null,t:"通路の先が、急に広くなる。"},{w:null,t:"奥の暗がりで、何かが立ち上がる。"},{w:null,t:"大きな茶色い牛。"},{w:null,t:"胸の毛の奥で、四角い物が、赤く点いて、消える。"},{w:null,t:"牛が、ひづめで、床を、ドン、と一回ける。"}];
GR_SC.g17_09=[{w:null,t:"三人、毛糸を手でたぐりながら、早足で通路をもどる。"},{w:null,t:"うしろで、ひづめの音が近づいたり、遠ざかったりする。"},{w:null,t:"角ごとに、毛糸が壁のすきまにはさまっている。"},{w:"alek",t:"引くな。待て。"},{w:null,t:"三人、壁の前で止まる。"},{w:null,t:"しばらくして、壁が開いて、毛糸が、ぱさりと落ちる。"}];
GR_SC.g17_10=[{w:null,t:"階段を上がる。"},{w:null,t:"三人、石段に、ばらばらに座りこむ。"},{w:null,t:"フォルン、ヤマトのひざの上で目をつぶっている。"},{w:null,t:"アレク、クロッコの頭に、水の筒から水をたらす。"},{w:null,t:"ヤマトの首には、赤いマフラーが、指二本分だけ残っている。"},{w:null,t:"エリー、柱から階段の下まで続く毛糸を、手のひらの上でたぐる。"},{w:null,t:"エリーの指が止まる。"},{w:null,t:"エリー、跡の一つを、ヤマトの前にさし出す。"},{w:null,t:"アレクが、横から毛糸の別の所を取る。"},{w:null,t:"アレクの手が、止まる。"},{w:null,t:"丘の奥から、牛の吠える声。"},{w:null,t:"ヤマト、胸の時計のつまみを押す。"}];
GR_EP[17]={"t": "守り①ミノタス・前編", "sc": [["g17_01", "白い都の競技場（表彰のすぐあと）", 0], ["g17_02", "客席の前", 0], ["g17_03", "貴賓席", 0], ["g17_04", "表彰台のうら", 0], ["g17_05", "丘の裏・閉めた入口（夕方）", 0], ["g17_06", "迷宮の入口", 0], ["g17_07", "迷宮", 0], ["g17_08", "勝負", 1], ["g17_09", "帰り道", 0], ["g17_10", "迷宮の入口（夜）", 0]]};
GR_SC.g18_01=[{w:null,t:"17話の続き。"},{w:null,t:"アレク、毛糸を石段の上にまっすぐのばしていく。"},{w:null,t:"毛糸の端は、まだ柱に結んだまま。"},{w:null,t:"階段の下から、ゴトン、と石の音。"},{w:null,t:"エリーが、指を一本折る。"},{w:null,t:"ヤマトとアレクが、エリーの手を見る。"},{w:null,t:"同時に、アレクの手の中の毛糸が、ぴん、と張る。"},{w:null,t:"エリー、折った指を、二人の前にそのまま出す。"},{w:null,t:"アレク、エリーの指を見る。"},{w:null,t:"アレク、何も言わずに、ならんだ小石の横の土に、指で通路の形を描きはじめる。"},{w:null,t:"アレクの指が、図のすみの、どこにもつながらない一角で止まる。"},{w:"hero",t:"行き止まり？"},{w:"alek",t:"作ったやつも、出られなくなったって話だ。"},{w:"hero",t:"ばっかでー。"},{w:null,t:"ヤマト、フォルンをひざにのせたまま、図の横に、指でまっすぐな線を一本、長く引く。"},{w:null,t:"アレク、ヤマトの線を見る。"},{w:null,t:"アレク、自分の図の中の一か所を、とんとん、とたたく。"},{w:"alek",t:"七つ目に、ここの溝から壁が出る。"},{w:null,t:"ヤマト、柱の四角と、自分の線を見くらべる。"},{w:null,t:"アレク、小石を一つ、柱の四角の中に置く。"},{w:null,t:"エリー、小石を見て、ヤマトを見て、アレクを見る。"},{w:null,t:"丘の奥で、牛の吠える声。"},{w:null,t:"第18話　守り①ミノタス・後編"}];
GR_SC.g18_02=[{w:null,t:"白い都の人たちは、その夜、家の外で寝た。"},{w:null,t:"広場に、毛布を敷いた人たち。"},{w:null,t:"大きな画面に、ニュース。"},{w:"x",n:"ニュースの声",t:"政府は、今日の地震を、地下の古い水路のくずれによるものと発表しました。余震に注意してください。"},{w:null,t:"羊のぬいぐるみをだいた小さな男の子が、画面を見上げている。"},{w:null,t:"三人、広場のはしを通る。"},{w:null,t:"ヤマト、首に手をやる。"},{w:null,t:"エリー、自分のからし色のマフラーをはずして、ヤマトの首に一周だけ巻く。"},{w:null,t:"ヤマト、何も言わない。"}];
GR_SC.g18_03=[{w:null,t:"階段を下りる。"},{w:null,t:"どこかで、ゴトン。"},{w:null,t:"ヤマト、指を折る。"},{w:"hero",f:"serious",t:"……ご、ろく、なな。"},{w:null,t:"ヤマト、目の前の溝をまたいで、一歩ふみ出す。"},{w:null,t:"壁は、動かない。"},{w:null,t:"ヤマト、胸を張って、もう一歩。"},{w:null,t:"壁が、ごごご、と立ち上がる。"},{w:null,t:"アレク、ヤマトの顔の前に、指を一本立てる。"},{w:null,t:"ヤマト、ひっくり返ったまま、天井を見て、指を折り直す。"},{w:"hero",f:"serious",t:"……いち、に、さん、し、ご、ろく……"}];
GR_SC.g18_04=[{w:null,t:"天井の高い四角い広間。"},{w:null,t:"奥の暗がりで、牛が柱にもたれて、すわっている。"},{w:null,t:"肩と首の葉の毛は、焦げて黒いまま。"},{w:null,t:"牛が、三人を見る。"},{w:null,t:"エリー、牛の目を見る。"},{w:null,t:"牛が、ひづめで、ドン、と一回ける。"}];
GR_SC.g18_08=[{w:null,t:"牛の鼻から、白い息。"},{w:null,t:"ヤマト、牛の方へ、一歩、二歩。"},{w:null,t:"牛の鼻が、ぶふううっと鳴る。"},{w:null,t:"牛が、ひづめで土をかく。"},{w:null,t:"エリーが、クッキーの箱を、ヤマトのひざの上に、そっと置く。"},{w:null,t:"エリー、一人で、牛の方へ歩いていく。"},{w:"alek",t:"おい。"},{w:null,t:"エリー、ふり向かずに、片手だけうしろに上げる。"},{w:null,t:"牛の前で、エリーが止まる。"},{w:null,t:"エリーの口から、短い言葉。"},{w:null,t:"牛の耳が、ぴくっと動く。"},{w:null,t:"エリーが、もう一言。"},{w:null,t:"牛が、ゆっくり頭を下げる。"},{w:null,t:"エリー、手のひらを牛の鼻の前に出す。"},{w:null,t:"エリー、割れたチップを拾う。"},{w:"hero",f:"serious",t:"……なんて言ったの。"},{w:"elly",t:"ないしょ。"},{w:null,t:"ヤマト、口を開けたまま、アレクを見る。"},{w:null,t:"フォルンが、ヤマトのひざから下りて、牛の前まで歩いていく。"},{w:null,t:"エリーが、からし色のマフラーを拾って、ヤマトの首に、ぐるぐる巻く。"}];
GR_SC.g18_09=[{w:null,t:"三人、毛糸をたぐりながら、階段を上がる。"},{w:null,t:"うしろの暗がりに、牛が立っている。"},{w:null,t:"エリーが、階段の上から、古い言葉で一言。"},{w:null,t:"牛が、ひづめで床を、こつん、と軽く鳴らす。"},{w:null,t:"アレク、くぐり戸のハンドルを回して、戸を閉める。"},{w:null,t:"外は、明け方。"},{w:null,t:"広場で、毛布をたたむ人たち。"},{w:null,t:"ヤマト、胸の時計のつまみを押す。"},{w:null,t:"ほかの三つは、赤いまま。"},{w:null,t:"広場の大きな画面。"},{w:"x",n:"ニュースの声",t:"続いて、運河の町コリンタです。きのうの夕方から、町の上空に雷雲がとどまり、落雷が続いています。運河の橋は、すべて沈められ——"},{w:null,t:"画面に、コリンタの空。"},{w:"elly",t:"ユスフの町だ。"},{w:null,t:"アレク、ポケットのチップを、指でさわる。"},{w:null,t:"ヤマト、からし色のマフラーと赤い結び目を巻き直して、港の方の道を見る。"}];
GR_EP[18]={"t": "守り①ミノタス・後編", "sc": [["g18_01", "迷宮の入口（夜）", 0], ["g18_02", "丘の下の広場（夜）", 0], ["g18_03", "迷宮", 0], ["g18_04", "迷宮の広間", 0], ["g18_05", "勝負・柱の四角", 1], ["g18_06", "勝負・左右から", 1], ["g18_07", "勝負・決め手", 1], ["g18_08", "勝負のあと", 0], ["g18_09", "迷宮の入口（明け方）", 0]]};
GR_SC.g19_01=[{w:null,t:"運河の町の空に、雷雲が居すわった。"},{w:null,t:"運河の両岸の、高い岩のかべ。"},{w:null,t:"雲の中を、羽のある白い影が、ぐるりと回る。"},{w:null,t:"橋のたもとの制御室。"},{w:null,t:"ミハリス、レバーを引く。"},{w:null,t:"雷が、橋の沈んだあとの水面に落ちる。"},{w:null,t:"雲の中の白い影が、町の上の高い丘へ、すうっともどっていく。"},{w:null,t:"制御室の小さな画面。"},{w:"x",n:"ニュースの声",t:"コリンタでは、落雷が続いています。市は、屋内にとどまるよう呼びかけています。"},{w:null,t:"ミハリス、画面を消す。"},{w:null,t:"第19話　守り②ペガライ・前編"}];
GR_SC.g19_02=[{w:null,t:"港の待合の画面に、「コリンタで落雷つづく」。"},{w:null,t:"三人、それを見上げる。"},{w:null,t:"甲板で、ユスフが洗濯物を取りこんでいる。"},{w:"yusuf",t:"エリー！"},{w:null,t:"エリー、両手をふり返して、かけていく。"},{w:"yusuf",t:"大会、見たよ。船のみんなで。画面、一個しかないから、取り合いだった。"},{w:"elly",t:"ヤマト、優勝したんだよ。"},{w:"yusuf",t:"だから、見たって。"},{w:null,t:"ヤマト、胸を張る。"},{w:null,t:"ユスフの父さんが、操舵室の窓から顔を出す。"},{w:"x",n:"ユスフの父さん",t:"白い都で荷を積んでた。コリンタへ帰るとこだ。橋が全部沈めてあるから、今なら通れる。……乗るか。"}];
GR_SC.g19_03=[{w:null,t:"船が、港を出る。"},{w:null,t:"ヤマト、操舵室の大きな木の舵輪を、じっと見ている。"},{w:"hero",t:"おじさん。それ、ちょっとだけ。"},{w:"x",n:"ユスフの父さん",t:"だめだ。"},{w:"hero",f:"serious",t:"……ちょっとだけ。"},{w:null,t:"父さん、前を見たまま、首をふる。"},{w:"yusuf",t:"ぼくも、前、やらせてもらったよ。"},{w:"x",n:"ユスフの父さん",t:"……ちょっとだけな。まっすぐ持ってろ。"},{w:null,t:"ヤマト、両手で舵輪をにぎる。"},{w:null,t:"窓の外の甲板で、ユスフが見ている。"},{w:"hero",t:"見ろ、片手！"},{w:null,t:"舵輪が、からからと回る。"},{w:null,t:"がりがりがり。"},{w:"hero",f:"serious",t:"……手伝わなくていいよ。"}];
GR_SC.g19_04=[{w:null,t:"運河は、岩の山をまっすぐ切ってつくった水の道だ。"},{w:null,t:"両側に、そそり立つ岩のかべ。"},{w:null,t:"沈んだ橋の上を、船がゆっくり通る。"},{w:null,t:"運河を出ると、町。"},{w:null,t:"町の上の高い丘。"},{w:"yusuf",t:"あそこのいちばん上に、泉があるんだよ。昔、羽のある馬が——"},{w:"hero",t:"ひづめで掘った、だろ。前、聞いた。"},{w:"yusuf",t:"……覚えてたんだ。"},{w:null,t:"ユスフ、手すりをにぎったまま、だまる。"},{w:null,t:"ヤマト、胸の時計のつまみを押す。"},{w:null,t:"船が、岸に横づけする。"},{w:"yusuf",t:"船、ここで待ってるから。"},{w:null,t:"ユスフの父さんが、操舵室から、だまって親指を立てる。"}];
GR_SC.g19_05=[{w:null,t:"乾いた岩の丘。"},{w:null,t:"三つ目の門の下に、保護局の車が一台。"},{w:"x",n:"保護局の職員",t:"……君たち、上はだめだ。雷だから。"},{w:"alek",t:"雷？"},{w:"x",n:"保護局の職員",t:"雷だよ。発表で、そう言ってる。"},{w:null,t:"職員の手は、ハンドルからはなれない。"},{w:null,t:"三人、車の横を通りすぎる。"}];
GR_SC.g19_06=[{w:null,t:"中庭の左に、石でふちどった四角い泉。"},{w:null,t:"水面が、ぶるっとふるえる。"},{w:null,t:"天馬が、泉の上で、ひづめを一つ空にける。"},{w:null,t:"天馬が、塔の上の石にとまる。"},{w:null,t:"ヤマト、首を上に向ける。"},{w:null,t:"天馬の目が、ヤマトの方へ動く。"},{w:null,t:"ヤマトが止まる。"},{w:"elly",t:"ヤマト？"},{w:null,t:"ヤマト、まばたきもしない。"},{w:null,t:"アレク、塔の方を見ないように、うつむいたまま、ヤマトの足首をつかむ。"},{w:null,t:"ヤマト、柱のかげから首を出して、上を見ようとする。"},{w:null,t:"アレクの手のひらが、横から、ヤマトの目の上に、ばふっとかぶさる。"},{w:"alek",t:"見るな。"},{w:"hero",f:"serious",t:"……おれ、止まってた？"},{w:"elly",t:"うん。片足で。"},{w:null,t:"ヤマト、手のひらの下で、口をへの字にする。"},{w:null,t:"塔の上で、天馬が、ひづめで石を、かつん、とたたく。"}];
GR_SC.g19_10=[{w:null,t:"三人とも、城壁のかげにひざをつく。"},{w:null,t:"アレク、すきまから泉の水をすくって、クロッコの頭にかける。"},{w:null,t:"エリー、ピリポンの背中を指でなでる。"},{w:null,t:"ヤマトのうでの中で、フォルンが片目を開けて、メダルのひもを前足でちょいとはじく。"},{w:null,t:"ヤマト、石のすきまから、泉の水面を見下ろす。"},{w:null,t:"水面に、黒い雲。"},{w:null,t:"ヤマト、びくっと肩を上げる。"},{w:null,t:"……指が、動く。"},{w:null,t:"水面の中で、天馬の目がこっちを向いている。"},{w:null,t:"ヤマト、動ける。"},{w:null,t:"アレク、ヤマトの横顔を見る。"},{w:null,t:"エリー、二人の顔を見くらべる。"},{w:null,t:"ヤマト、水面から目をそらさないまま、フォルンを胸にかかえ直す。"},{w:null,t:"アレクの手が、ヤマトのパーカーのすそを、うしろから、ぐっとつかむ。"},{w:null,t:"ヤマトの目は、水面からはなれない。"}];
GR_EP[19]={"t": "守り②ペガライ・前編", "sc": [["g19_01", "運河の町コリンタ（きのうの夕方）", 0], ["g19_02", "白い都の港（朝）", 0], ["g19_03", "貨物船・操舵室（昼）", 0], ["g19_04", "運河（午後）", 0], ["g19_05", "とりでの坂道（夕方近く）", 0], ["g19_06", "とりでの上の中庭", 0], ["g19_07", "勝負・一度目", 1], ["g19_08", "勝負・二度目", 1], ["g19_09", "勝負・引く", 1], ["g19_10", "泉の裏・くずれた城壁のかげ（夕方）", 0]]};
GR_SC.g20_01=[{w:null,t:"コリンタの運河。ゆうべ、三人は、とりでを下りて船にもどった。"},{w:null,t:"岸に横づけした古い貨物船。"},{w:null,t:"船のへりで、ヤマトが、ロープのついたバケツを運河に下ろしている。"},{w:null,t:"ヤマト、バケツを胸の前に持って、水面をのぞく。"},{w:null,t:"ヤマト、水面から目をはなさずに、甲板を歩きだす。"},{w:null,t:"ヤマトの口のはしが、上がる。"},{w:null,t:"マストの柱に、おでこから当たる。"},{w:null,t:"毛布の中から、アレクの声。"},{w:"alek",t:"……朝から、うるさい。"},{w:"hero",t:"今の、マストが悪い。あんなとこに立ってんのが悪い。"},{w:"alek",t:"船ができた時から、そこに立ってる。"},{w:null,t:"ヤマト、ぬれた前髪のまま、またバケツを運河に下ろす。"},{w:null,t:"操舵室の横で、ユスフがパンをかじりながら見ている。"},{w:"yusuf",t:"何してんの。"},{w:"hero",t:"練習。"},{w:"yusuf",t:"バケツの？"},{w:"hero",f:"serious",t:"……まあ、そんな感じ。"},{w:null,t:"第20話　守り②ペガライ・後編"}];
GR_SC.g20_02=[{w:null,t:"甲板のまん中に、ユスフが持ってきたパンとオリーブのびん。"},{w:null,t:"フォルン、オリーブを一つくわえて、しっぽの火の上でころがす。"},{w:null,t:"アレク、紙に、とりでの中庭の絵を描いている。"},{w:"alek",t:"ゆうべ、おれがすそを引っぱらなかったら、おまえ、そのまま泉に落ちてたぞ。"},{w:"hero",t:"落ちてない。"},{w:"alek",t:"片足、もう出てた。"},{w:"hero",t:"出てたけど、落ちてない。"},{w:null,t:"ヤマト、紙の泉を、指でとん、とたたく。"},{w:"hero",t:"ここで、やる。水の方だけ見てれば、止まんない。"},{w:null,t:"アレク、ヤマトの赤いおでこを見る。"},{w:"alek",t:"あいつは塔の石の上で治る。泉からじゃ、石の上までは届かない。"},{w:null,t:"ヤマト、パンをかじりながら、紙の塔をにらむ。"},{w:"hero",t:"撃ったら、降りてくるじゃん、あいつ。きのう、そうだった。"},{w:"alek",t:"降りてきたのは、ピリポンの顔をのぞきこみに来た時だ。"},{w:"hero",t:"水だけ見てりゃ、のぞかれたって平気だろ。"},{w:null,t:"アレク、返事をしない。"},{w:"alek",t:"……降りてきたら、そこは草だ。石じゃない。"},{w:null,t:"甲板のむこうで、とりでの雲から雷が一つ落ちる。"},{w:null,t:"ユスフが、パンを半分にちぎって、ヤマトにわたす。"},{w:"yusuf",t:"顔を見ないで、どうやって戦うの。"},{w:"hero",t:"下、見る。"},{w:null,t:"ユスフ、操舵室の父さんの方を見る。"},{w:"x",n:"ユスフの父さん",t:"昼には、船を出す。そのころ、まだ雲があったら、置いていくぞ。"},{w:null,t:"ヤマト、パンを口いっぱいにつめこんで、立ち上がる。"}];
GR_SC.g20_03=[{w:null,t:"三つ目の門の下。"},{w:null,t:"奥の塔の上に、白い天馬。"},{w:null,t:"三人、うつむいたまま、中庭のはしを、泉の方へ歩く。"},{w:null,t:"泉のふちの石。"},{w:null,t:"エリー、浮き彫りの前にしゃがむ。"},{w:"elly",t:"この人も、盾、見てる。"},{w:null,t:"ヤマト、浮き彫りの盾を見る。"},{w:null,t:"ヤマト、何も言わずに、塔に背を向けて、泉のふちにすわる。"},{w:null,t:"アレクも、塔に背を向けて、となりにすわる。"},{w:null,t:"三人の顔が、水面に並んで映る。"},{w:null,t:"水面の中で、天馬が首を上げる。"}];
GR_SC.g20_07=[{w:null,t:"獣の闘気が引いて、光がほどけて、小さなフォルンと、小さなクロッコ。"},{w:null,t:"フォルン、起き上がる。"},{w:null,t:"フォルン、前足で鼻をごしごしこすって、クロッコから一歩はなれてすわる。"},{w:null,t:"アレク、クロッコの頭を、指で一回、こつんとたたく。"},{w:null,t:"天馬が、前足を折ったまま、首を上げる。"},{w:null,t:"水面に映った天馬の目には、もう、光がない。"},{w:null,t:"エリー、ピリポンの箱をヤマトにあずけて、天馬のそばへ行く。"},{w:null,t:"エリーの口から、短い言葉。"},{w:null,t:"天馬が、水を飲むのをやめる。"},{w:null,t:"エリーが、もう一言。"},{w:null,t:"天馬が、ゆっくり、前のひざを折る。"},{w:null,t:"エリー、天馬の首の毛に、手をのせる。"},{w:null,t:"アレク、草の上の割れたチップを拾う。"},{w:null,t:"ヤマト、浮き彫りの盾の男を、もう一度見る。"},{w:"hero",f:"serious",t:"……これ、乗れんの？"},{w:null,t:"エリー、天馬の首をなでて、古い言葉で一言。"},{w:null,t:"天馬が、羽を一回、ばさっと広げる。"}];
GR_SC.g20_08=[{w:null,t:"天馬の背に、三人。"},{w:null,t:"天馬が、泉のふちから草をけって浮く。"},{w:null,t:"とりでが、下へ遠ざかる。"},{w:null,t:"ヤマト、片手を上げかけて、すぐに首の毛をつかみ直す。"},{w:null,t:"海と山と、オリーブの畑が、ずっと先まで見える。"},{w:null,t:"ヤマト、胸の時計のつまみを押す。"},{w:null,t:"村の丘の印が、ゆうべより、また大きい。"},{w:null,t:"エリー、肩ごしに地図を見る。"},{w:null,t:"村の競技場の赤い印が、どくん、と一度強く光る。"},{w:null,t:"天馬が、羽の向きを変える。"}];
GR_EP[20]={"t": "守り②ペガライ・後編", "sc": [["g20_01", "貨物船の甲板（明け方）", 0], ["g20_02", "貨物船・甲板（朝）", 0], ["g20_03", "とりでの上の中庭", 0], ["g20_04", "勝負・はじめ", 1], ["g20_05", "勝負・なか", 1], ["g20_06", "勝負・おわり", 1], ["g20_07", "勝負のあと", 0], ["g20_08", "とりでの上・空（朝）", 0]]};
GR_SC.g21_01=[{w:null,t:"コリンタから、ふるさとの村まで。歩けば四日の道を、天馬は昼までに飛ぶ。"},{w:null,t:"下に、見なれた丘。"},{w:null,t:"ヤマト、エリーの肩につかまったまま、立ち上がる。"},{w:"hero",t:"見ろ見ろ！　村！　天馬に乗って帰ってきたやつなんて、村の歴史で、おれが初めてだぞ。"},{w:"alek",t:"すわれ。"},{w:"hero",t:"村のやつら、腰ぬかすぞ。手、ふっとこ。おーい！"},{w:null,t:"ヤマト、両手を大きくふる。"},{w:null,t:"天馬が、左へ、ゆるく曲がる。"},{w:null,t:"ヤマト、背中の上を、ずるずるすべっていく。"},{w:null,t:"エリー、ふり返って、ふき出す。"},{w:"hero",t:"あ、ホテル！　アナの屋根！"},{w:null,t:"第21話　守り③ゴッドヘラク"}];
GR_SC.g21_02=[{w:null,t:"広場に、村の人たち。"},{w:"x",n:"村のおじいさん",t:"……あそこ、二千年前の運動場だよ。ガスなんか通ってるもんか。"},{w:null,t:"だれも答えない。"},{w:null,t:"競技場の方から、何かが飛んでくる。"},{w:null,t:"村の人たちが、いっせいに家の中へ走る。"},{w:null,t:"ホテルの戸が開いて、エプロンのアナが、ほうきを持って出てくる。"},{w:null,t:"ぶどう畑の方から、三人が歩いてくる。"},{w:null,t:"アナ、ほうきを落とす。"},{w:null,t:"天馬が、アナの前で首を下げる。"},{w:null,t:"アナ、髪を押さえたまま、だまって競技場の方を指さす。"}];
GR_SC.g21_03=[{w:null,t:"土手にかこまれた、長い土の走路。"},{w:null,t:"入口の石のアーチの前に、黄色いテープ。"},{w:"x",n:"保護局の職員",t:"……はい。ドローンは、六台目です。ロボットは……今、腕が一本、村まで。……いえ、近づけません。"},{w:null,t:"職員、三人に気づいて、片手を広げる。"},{w:"x",n:"保護局の職員",t:"だめ。ここから先は、だめ。"},{w:null,t:"アーチの向こう、走路のまん中。"},{w:null,t:"金色のよろい。"},{w:null,t:"アーチのわきの石の扉。"},{w:null,t:"エリー、浮き彫りの角と、走路の王のつのを見くらべる。"},{w:"hero",f:"serious",t:"……カブトムシじゃん。"},{w:"elly",t:"ヘラクレスは、人だってば。何回言わせるの。"},{w:"x",n:"保護局の職員",t:"……七台目、です。"},{w:"x",n:"警察のロボット",t:"危険区域です。立ち止まってください。"},{w:"x",n:"保護局の職員",t:"ちょっと、きみ——"}];
GR_SC.g21_07=[{w:null,t:"獣の光がほどけて、フォルンとクロッコが、並んで土の上にへたりこむ。"},{w:null,t:"ヤマト、フォルンの横にしゃがむ。"},{w:null,t:"王は、両ひざをついたまま、肩で息をしている。"},{w:null,t:"ヤマトが、王の方へ一歩出かける。"},{w:null,t:"エリーが、ピリポンを抱き上げて箱に入れ、ヤマトの横に置く。"},{w:null,t:"王の顔は、エリーの体より大きい。"},{w:null,t:"エリーが、古代のギリシャ語で、短く話しかける。"},{w:null,t:"王の鼻息が、止まる。"},{w:null,t:"王が、エリーの顔を見る。"},{w:null,t:"王が立ち上がる。"},{w:null,t:"走路のはしで止まって、土手の向こうの、村の丘の方を向く。"},{w:null,t:"エリーも、王のとなりまで歩いていって、同じ方を見る。"},{w:null,t:"ヤマトの時計が、ふるえる。"},{w:null,t:"アレク、土の上の割れたチップを拾う。"},{w:null,t:"アーチの外で、保護局の職員が、手もとの画面に何か言いかけて、やめる。"}];
GR_SC.g21_08=[{w:null,t:"村のうしろの、オリーブ畑の丘。"},{w:null,t:"ため池の水面が、こまかくふるえている。"},{w:null,t:"オリーブの葉が、いっせいに、ざあっと鳴る。"},{w:null,t:"くずれた丸屋根の下の地面が、まん中から割れる。"},{w:null,t:"割れ目から、石の手が出る。"},{w:null,t:"石の指が、ゆっくり、地面をつかむ。"},{w:null,t:"競技場の走路のはしで、王が、低く鳴く。"},{w:null,t:"丘のふもとの道。"}];
GR_EP[21]={"t": "守り③ゴッドヘラク", "sc": [["g21_01", "空・天馬の背（昼前）", 0], ["g21_02", "オリーヴァ村・広場（昼）", 0], ["g21_03", "古代の競技場・入口のアーチ（昼）", 0], ["g21_04", "勝負・はじめ", 1], ["g21_05", "勝負・なかほど", 1], ["g21_06", "勝負・おしまい", 1], ["g21_07", "勝負のあと", 0], ["g21_08", "村の丘（昼すぎ）", 0]]};
GR_SC.g22_01=[{w:null,t:"オリーヴァ村のうしろの丘。二十年前まで、てっぺんに研究所があった。"},{w:null,t:"丘のてっぺん。"},{w:null,t:"石の手が、二本。"},{w:null,t:"立ち上がる。"},{w:null,t:"オリーブ畑いっぱいに、巨人の影が落ちる。"},{w:null,t:"村の家の戸が、あちこちで開く。"},{w:null,t:"丘のふもとのオリーブの木の下。"},{w:null,t:"アレクが、パーカーのポケットから、ノモスの画面を出す。"},{w:null,t:"アレク、画面と丘の上を見くらべる。"},{w:null,t:"ヤマトの口が、開いたまま。"},{w:null,t:"第22話　守り④アトラード・前編"}];
GR_SC.g22_02=[{w:null,t:"広場の柱から、政府の放送の声。"},{w:"x",n:"政府の放送の声",t:"オリーヴァ村のみなさん。北の丘で、地すべりのおそれがあります。南の道から、すみやかに避難してください。"},{w:null,t:"村の人たちが、荷物を持って、南の道へ歩きだす。"},{w:null,t:"ホテルの前で、アナが、泊まり客を順に送り出している。"},{w:null,t:"広場のはしの石のベンチに、おばあさん。"}];
GR_SC.g22_03=[{w:null,t:"丘へのぼる細い道。"},{w:null,t:"車の横に、三本足の台にのった細長い筒の機械。"},{w:null,t:"車のドアが開く。"},{w:"bella",t:"あら、エリーちゃん。お里帰り？　ここ、あなたの村だものね。"},{w:"elly",t:"それ、なに？"},{w:"bella",t:"お薬。大きい子用の。"},{w:null,t:"ベラドンナ、日がさのかげで、丘の上を見上げる。"},{w:"bella",t:"白い都の子も、運河の子も、王さまも、みんなほしかったけど。……一番ほしかったのは、この子。"},{w:null,t:"アレク、パーカーのポケットから、割れたチップを三つ出して、手のひらにのせて見せる。"},{w:"bella",t:"あら、拾い集めてるの。えらいわね。"},{w:null,t:"ベラドンナ、作業員に、あごで合図。"},{w:null,t:"筒の先から、細い光が一本、丘の上へ走る。"},{w:null,t:"巨人の星座の線が、いっせいに赤くなる。"},{w:null,t:"巨人が、ほえる。"},{w:null,t:"巨人の頭が、ゆっくり回る。"},{w:"x",n:"作業員",t:"社長、……村の方に。"},{w:"bella",t:"大きい子は、なれるのに時間がかかるのよ。"},{w:"hero",t:"前のより、でかいだけだろ！　あんなの、赤と青のやつで、三発！"},{w:"alek",t:"おい。"},{w:"hero",f:"serious",t:"……四発！"}];
GR_SC.g22_04=[{w:null,t:"段々畑のいちばん上。"},{w:null,t:"手前の左のすみ。"},{w:null,t:"右のはしに、村へ下る細い道。"},{w:null,t:"巨人の足もとから、くずれた石垣の岩が、ごろごろと、その道の方へ転がっていく。"},{w:null,t:"巨人が、三人を見下ろす。"}];
GR_SC.g22_08=[{w:null,t:"巨人は、それから一歩も動かなかった。球を、頭の上に持ったまま。"},{w:null,t:"南の丘の、小さな教会。"},{w:null,t:"三人が、石段のはしに並んですわっている。"},{w:null,t:"フォルンが、ヤマトのひざの上で、丸くなって眠っている。"},{w:null,t:"エリーは、ひざの上のピリポンの箱を、指でとん、とん、とたたいている。"},{w:null,t:"石段の下の草地で、天馬が立ったまま眠っている。"},{w:null,t:"教会の扉が開く。"},{w:null,t:"エリーが、箱をたたく指を止めて、おばあさんの横顔を見る。"},{w:"oba",t:"……あの子、昔の本だと、空を持たされてたのよ。ずうっと。"},{w:null,t:"それだけ言って、おばあさんは、石段を一段ずつもどっていく。"},{w:null,t:"エリー、何も聞かない。"}];
GR_SC.g22_09=[{w:null,t:"教会の窓のろうそくが、一つずつ消えていく。"},{w:null,t:"ヤマトが、そっと、フォルンをひざから毛布の上に下ろす。"},{w:null,t:"石段を下りて、北の丘の方へ歩きだす。"},{w:null,t:"段々畑の、いちばん下の石垣の前。"},{w:null,t:"ヤマトの手が、石垣の石をつかむ。"},{w:null,t:"ヤマト、自分のあいた両手を見る。"},{w:null,t:"ヤマト、石垣から手をはなす。"},{w:null,t:"教会の石段。"},{w:null,t:"ヤマト、アレクの前で止まる。"},{w:null,t:"ヤマト、頭を下げる。"},{w:null,t:"遠くで、巨人の星座の線が、ゆっくりまたたく。"},{w:null,t:"アレク、ヤマトのつむじを見る。"},{w:null,t:"アレクの枝が、左の手前のすみで止まる。"},{w:null,t:"ヤマト、顔を上げる。"},{w:"hero",f:"serious",t:"……ため池。"},{w:null,t:"アレク、何も言わない。"},{w:null,t:"ヤマト、丸屋根の×と、点線の×を、見くらべる。"},{w:null,t:"エリーは、毛布にくるまって、ピリポンの箱を抱いたまま眠っている。"},{w:null,t:"アレクが、枝を、草の中へ放る。"},{w:"alek",t:"……あしたの朝だ。"}];
GR_SC.g22_10=[{w:null,t:"空のはしが、少しだけ白い。"},{w:null,t:"丘の上の巨人。"},{w:null,t:"頭の上の星の球が、ほんの少し、南へかたむく。"},{w:null,t:"巨人の腕が、ふるえはじめる。"},{w:null,t:"胸の奥で、二つのチップが、赤く、ちかちかと光る。"},{w:null,t:"村の家の屋根に、球の影が、ゆっくりかかっていく。"},{w:null,t:"丘のふもとの黒い車。"}];
GR_EP[22]={"t": "守り④アトラード・前編", "sc": [["g22_01", "オリーヴァ村・丘のふもとのオリーブ畑（昼すぎ）", 0], ["g22_02", "村の広場（昼すぎ）", 0], ["g22_03", "丘のふもとの道（昼すぎ）", 0], ["g22_04", "丘の上・研究所あとの前（昼すぎ）", 0], ["g22_05", "勝負・はじめ", 1], ["g22_06", "勝負・なかほど", 1], ["g22_07", "勝負・おしまい", 1], ["g22_08", "南の丘の教会・石段（夜）", 0], ["g22_09", "同じ石段（真夜中）", 0], ["g22_10", "丘の上（夜明け前）", 0]]};
GR_SC.g23_01=[{w:null,t:"夜明け。村の人は、南の丘の教会で、眠れない夜を明かした。"},{w:null,t:"北の丘の上。"},{w:null,t:"オリーブ畑の中の道を、三人が丘の方へ歩いていく。"},{w:null,t:"いちばん前にアレク。"},{w:null,t:"ヤマトは走らない。"},{w:null,t:"巨人の片足が、丸屋根の石から下りる。"},{w:null,t:"第23話　守り④アトラード・後編"}];
GR_SC.g23_02=[{w:null,t:"段々畑のいちばん上。"},{w:null,t:"村へ下る道の上に、黒い車。"},{w:null,t:"車の前の折りたたみのいすに、ベラドンナ。"},{w:"bella",t:"おはよう。早いのね。見に来たのよ。この子が、うちの子になる所。"},{w:null,t:"だれも答えない。"},{w:null,t:"巨人が、三人の前で、乾いた土を一回ふむ。"},{w:null,t:"ヤマト、左の手前のすみを見る。"},{w:null,t:"三体が、巨人の前に下りる。"},{w:null,t:"上の段の石垣のきわに、天馬。"}];
GR_SC.g23_06=[{w:null,t:"獣の光がほどけて、ため池のふちに、ピリポンとクロッコ。"},{w:null,t:"赤い光のあった所で、フォルレオンの光がほどける。"},{w:null,t:"巨人の腕から、力がぬける。"},{w:null,t:"フォルン、立ち上がろうとして、前足がくずれる。"},{w:null,t:"エリーが、畑のきわから、乾いた土の上へ一歩出る。"},{w:"elly",t:"（字幕）……ちょっと、持ってて。"},{w:null,t:"巨人の目が、エリーを見る。"},{w:null,t:"巨人が、ひざをついたまま、体ごと前へのり出す。"},{w:null,t:"フォルンの、耳の先の、すぐ上。"},{w:null,t:"巨人が、ゆっくり、球を持ち上げていく。"},{w:null,t:"村の屋根から、球の影がひいていく。"},{w:null,t:"フォルン、上を見上げる。"},{w:null,t:"ヤマト、にぎっていた手を、やっと開く。"},{w:null,t:"ヤマトは、近づかない。"},{w:null,t:"エリーが、ピリポンをアレクにあずけて、巨人の足もとまで歩いていく。"},{w:null,t:"エリーが、巨人の足に手をそえて、古代のギリシャ語で話しかける。"},{w:null,t:"巨人が、球を頭の上に持ったまま、ゆっくりひざをつきなおす。"},{w:null,t:"エリーが、巨人のあごの石を、手のひらで、ぽん、とたたく。"},{w:null,t:"上の段の石垣のきわから、天馬と王が、巨人のそばへ歩いてくる。"},{w:null,t:"ベラドンナの足もとまで、割れた銀色のチップが一つ、転がってきている。"},{w:"bella",t:"……負けね。"},{w:null,t:"ヤマトが、ベラドンナの前に出る。"},{w:"hero",t:"社長なんだろ。もう、おしまいだぞ。"},{w:null,t:"ベラドンナ、ヤマトを見て、いつもの顔で笑う。"},{w:"bella",t:"わたしは、四番目。"},{w:null,t:"ヤマトの顔が、止まる。"},{w:null,t:"ベラドンナ、いすにもどって、冷めたコーヒーを、ひと口。"}];
GR_SC.g23_07=[{w:null,t:"丘のふもとから、紺色の車が三台、のぼってくる。"},{w:null,t:"先頭の車から、白衣の女。"},{w:null,t:"所長が、巨人を見上げる。"},{w:null,t:"束のいちばん上の紙。"},{w:null,t:"保護局の人が、ベラドンナの手から画面を取り上げる。"},{w:null,t:"ベラドンナ、だれにも腕をとられずに、紺色の服のあいだを、自分の足で車の方へ歩いていく。"},{w:null,t:"保護局の人が、巨人と、王と、天馬を見上げる。"},{w:"x",n:"保護局の人",t:"……はい。三体、ここに。白い都の一体も、動いていません。……では、古代は、上の指示どおり、もう一度、封印の手続きを——"},{w:null,t:"保護局の人が、袋に入れようとしたベラドンナの画面に、目を落とす。"},{w:null,t:"「封印は、また割ればいい」"},{w:null,t:"保護局の人の声が、止まる。"},{w:null,t:"所長、紙の束のいちばん下の一枚を見る。"},{w:"shocho",t:"……今日の書類は、これで全部です。"},{w:null,t:"保護局の人が、所長を見る。"},{w:null,t:"巨人の足もとで、エリーが、巨人のひざにすわっている。"}];
GR_SC.g23_08=[{w:null,t:"保護局の車の横の机。"},{w:null,t:"持ち主の欄。"},{w:"x",n:"保護局の人",t:"持ち主の方は……ダレデモナイさん？"},{w:"hero",t:"はい。おれ。"},{w:null,t:"保護局の人、ヤマトの顔を見る。"},{w:"x",n:"保護局の人",t:"お名前の、書き直しの手続きは——"},{w:"hero",t:"あとで、やる。"},{w:null,t:"ヤマト、もう、フォルンの方を見ている。"},{w:null,t:"巨人のひざの上で、エリーが、ふき出す。"},{w:null,t:"保護局の人、「ダレデモナイ」の横に、小さく「確認済み」を押す。"}];
GR_SC.g23_09=[{w:null,t:"大きな画面。"},{w:"x",n:"ニュースの声",t:"白い都の電波の塔で起きた事故について、政府は、設備の工事の責任者を——"},{w:null,t:"待合室のいすに、レン。"},{w:null,t:"レン、画面を見ている。"},{w:null,t:"レンの画面に、「父さん」からの着信。"}];
GR_SC.g23_10=[{w:null,t:"巨人が、くずれた丸屋根のあった所に、ひざをついてすわっている。"},{w:null,t:"教会から帰ってきた村の人たちが、段々畑の下から、巨人を見上げている。"},{w:null,t:"村の柱から、政府の放送の声。"},{w:"x",n:"政府の放送の声",t:"北の丘の地すべりのおそれは、なくなりました。"},{w:null,t:"おじいさんが、オリーブのかごを抱えたまま、巨人を見て、放送の柱を見て、また巨人を見る。"},{w:null,t:"段々畑のいちばん上の石垣に、三人がすわっている。"},{w:null,t:"ヤマトの胸の時計が、小さくふるえる。"},{w:null,t:"地図が、その外へ、ぐうっと広がっていく。"},{w:null,t:"エリーが、その印を見て、ヤマトの顔を見る。"},{w:null,t:"アレクは、印を見たまま、パーカーのポケットの中で、割れたチップの欠けらを、にぎる。"},{w:null,t:"保護局の車の中。"},{w:null,t:"「古代と話せる女の子と、優勝した男の子を」"},{w:null,t:"画面が、消える。"}];
GR_SC.g23_11=[{w:null,t:"割れた石の横に、ヤマトとフォルンが並ぶ。"},{w:null,t:"エリーが、フォルンの前にしゃがんで、手のひらを出す。"},{w:null,t:"フォルン、エリーの手のひらを見る。"},{w:null,t:"エリー、手のひらを出したまま、目を丸くする。"},{w:null,t:"アレクは、土手の石に腰を下ろしている。"},{w:null,t:"走路のはしで、王がすわって見ている。"},{w:null,t:"エリーが、横で片手を上げる。"},{w:"elly",t:"よーい……。"},{w:null,t:"ヤマトの足が、ぴくっと前に出かける。"},{w:null,t:"エリーの手が、下りる。"},{w:"hero",t:"いちばん！"},{w:null,t:"ヤマト、走りだす。"},{w:null,t:"フォルンが、となりにいる。"},{w:null,t:"走路の向こう。"}];
GR_EP[23]={"t": "守り④アトラード・後編", "sc": [["g23_01", "丘の道（夜明け）", 0], ["g23_02", "丘の上（夜明け）", 0], ["g23_03", "勝負・はじめ", 1], ["g23_04", "勝負・なかほど", 1], ["g23_05", "勝負・おしまい", 1], ["g23_06", "勝負のあと", 0], ["g23_07", "丘の上（朝）", 0], ["g23_08", "保護局の車の前（朝）", 0], ["g23_09", "白い都・テリオンの病院の待合室（昼）", 0], ["g23_10", "丘の上（夕方）", 0], ["g23_11", "古代の競技場・走路（あくる朝）", 0]]};
